	private static final Set<ChatMessageType> PARSED_CHAT = EnumSet.of(ChatMessageType.GAMEMESSAGE,
			ChatMessageType.SPAM, ChatMessageType.MESBOX, ChatMessageType.FRIENDSCHATNOTIFICATION);

