	/** The starting-shot card's live requirements: session age, then position. Any thread. */
	List<StartProofRules.Check> startProofChecks(StartProof proof) {
		List<StartProofRules.Check> checks = new ArrayList<>(2);
		StartProofRules.Check session = StartProofRules.sessionCheck(proof, sessionLoginAtMs, now());
		if (session != null) {
			checks.add(session);
		}
		WorldPoint p = loggedIn() ? startProofPosition : null;
		StartProofRules.Check where = StartProofRules.positionCheck(proof,
				p == null ? null : p.getX(), p == null ? null : p.getY());
		if (where != null) {
			checks.add(where);
		}
		return checks;
	}

	/**
	 * Take what's waiting in the KC / XP / activity pushes and the moments queue for this character,
	 * clear them, and return the disk write that keeps them (null when there's nothing, or no way to
	 * tell whose they are). Any thread: the snapshot is memory only; run the result off the client thread.
	 */
	private Runnable stashPushes(String rsn, String accountHash) {
		String key = PushStash.keyFor(rsn, accountHash);
		PushStash stash = pushStash;
		if (key == null || stash == null) {
			return null;
		}
		PushStash.Data data = new PushStash.Data();
		data.savedAt = now();
		data.kc = kcPush.snapshot();
		data.xp = skillXpPush.snapshot();
		data.activity = activityPush.snapshot();
		synchronized (moments) {
			for (AnvilMoments.Moment m : moments.snapshot()) {
				data.moments.add(PushStash.SavedMoment.of(m));
			}
			moments.reset();
		}
		kcPush.reset();
		skillXpPush.reset();
		activityPush.reset();
		return data.isEmpty() ? null : () -> stash.save(key, data);
	}

	/** This character logged in: queue again what an earlier session couldn't send. Executor only (disk). */
	private void restorePushes(String rsn, String accountHash) {
		PushStash stash = pushStash;
		if (stash == null || !apiClient.isConfigured()) {
			return;
		}
		long t = now();
		PushStash.Data data = null;
		// By hash first; by name for one saved before the hash was known.
		for (String key : new String[]{PushStash.keyFor(null, accountHash), PushStash.keyFor(rsn, null)}) {
			if (key != null) {
				data = PushStash.merge(data, stash.take(key, t));
			}
		}
		if (data == null || data.isEmpty()) {
			return;
		}
		log.info("Anvil: resending {} count(s) and {} moment(s) saved from an earlier session",
				sizeOf(data.kc) + sizeOf(data.xp) + sizeOf(data.activity), sizeOf(data.moments));
		kcPush.restore(data.kc);
		skillXpPush.restore(data.xp);
		activityPush.restore(data.activity);
		if (data.moments != null && !data.moments.isEmpty()) {
			List<AnvilMoments.Moment> saved = new ArrayList<>();
			for (PushStash.SavedMoment m : data.moments) {
				saved.add(m.toMoment());
			}
			synchronized (moments) {
				moments.restore(saved, t, PushStash.MAX_AGE_MS);
			}
			scheduleMomentPush();
		}
	}

	/** Client closing (not just the plugin stopping): save unsent pushes, and have the client wait for it. */
	@Subscribe
	public void onClientShutdown(ClientShutdown event) {
		Runnable save = stashPushes(apiClient.getCurrentRsn(), apiClient.getAccountHash());
		if (save != null) {
			event.waitFor(sharedExecutor.submit(save));
		}
	}

	/**
	 * The site answered after a stretch of not answering. Everything that backed off while it was down
	 * goes now rather than sitting out the rest of its wait (up to ten minutes for the profile syncs).
	 */
	private void onSiteRecovered() {
		log.info("Anvil: site reachable again — sending what was waiting");
		clogBackoff.reset();
		clogFullBackoff.reset();
		pbBackoff.reset();
		rosterBackoff.reset();
		proofBackoff.reset();
		kcPush.kick();
		skillXpPush.kick();
		activityPush.kick();
		synchronized (moments) {
			momentFailures = 0;
		}
		if (!moments.isEmpty()) {
			scheduleMomentPush();
		}
		NotifyOutbox outbox = notifyOutbox;
		if (outbox != null) {
			outbox.kick();
		}
		submit(() -> {
			safely("retryPendingSubmissions", this::retryPendingSubmissions);
			safely("flushClogSync", this::flushClogSync);
			safely("flushFullClogSync", this::flushFullClogSync);
			safely("flushPersonalBests", this::flushPersonalBests);
		});
	}

	private void configureApiClient() {
		apiClient.configure(config.playerToken());
		// Signing out, or another account signing in: the saved answers were the last account's.
		ResponseDiskCache rc = responseCache;
		String stale = rc == null ? null : rc.switchAccount(config.playerToken());
		if (stale != null) {
			forgetSavedResponses();
			submit(() -> rc.clear(stale));
		}
	}

	/** Read last session's config off disk for the panel. Executor only (disk). */
	private void loadSavedResponses() {
		ResponseDiskCache rc = responseCache;
		if (rc == null || !apiClient.isConfigured() || liveConfigAnswered) {
			return;
		}
		ResponseDiskCache.Entry cfgEntry = rc.load(ResponseDiskCache.CONFIG);
		// Saved for another character than the one about to play: their team, not this one's.
		String who = apiClient.getCurrentRsn() != null ? apiClient.getCurrentRsn() : apiClient.getRsnHint();
		if (cfgEntry != null && cfgEntry.rsn != null && who != null && !Rsn.same(cfgEntry.rsn, who)) {
			return;
		}
		PluginConfigResponse cfg = apiClient.seedFromDisk(cfgEntry, PluginConfigResponse.class);
		if (cfg == null || liveConfigAnswered) {
			return; // the site beat the disk to it
		}
		savedConfig = cfg;
		log.debug("Showing last session's config until the site answers");
		repaintSidebar();
	}

	/** The site has answered (or the account changed): stop showing last session's copy. */
	private void forgetSavedResponses() {
		savedConfig = null;
	}

	/**
	 * What the SIDE PANEL draws from: the live config, or — until the site's first answer this
	 * session — last session's saved copy. Never read by tracking; that is {@link #pluginConfig}.
	 */
	PluginConfigResponse sidebarConfig() {
		PluginConfigResponse live = pluginConfig;
		return live != null || liveConfigAnswered ? live : savedConfig;
	}

	/** The panel is drawing last session's copy, not a live answer. */
	boolean showingSavedConfig() {
		return pluginConfig == null && !liveConfigAnswered && savedConfig != null;
	}

	// ─── Admin clan-roster sync (triggered from the in-game collection-log "Bingo" tab) ───
	// Authenticated solely by the player's per-user account token (config.playerToken()) plus
	// their site admin role. No admin-link-code mechanism exists anymore.
	/**
	 * Once per login, ask the site whether this account token belongs to an
	 * admin (GET /api/plugin/me). On success, flip the isAdmin flag so the
	 * in-game collection-log "Bingo" tab renders its admin-only "Sync clan
	 * roster" button; otherwise it stays hidden. Guarded so it only probes when
	 * both the player token and site URL are set, and only once per login
	 * session.
	 */
	private void probeAdmin() {
		if (adminProbeAttempted) {
			return;
		}
		String token = config.playerToken();
		if (token == null || token.isEmpty()) {
			return;
		}
		adminProbeAttempted = true;
		lastAdminProbeAt = now();
		boolean wasAdmin = isAdmin;
		isAdmin = apiClient.fetchIsAdmin(token);
		if (wasAdmin != isAdmin) {
			redrawSidebarLocal();
		}
		// Repaint the side panel so the admin button appears/disappears.
	}

	/**
	 * Is the clan roster readable RIGHT NOW, as last seen from the client thread?
	 *
	 * <p>The side panel renders on Swing's EDT and has to know whether to offer a roster sync, but
	 * asking the client directly from there is a thread violation. This is refreshed on the game
	 * tick and read from anywhere.
	 */
	@Getter
	private volatile boolean clanRosterReadable;
	/** Consecutive ticks the clan channel has been missing — see updateClanRosterReadable. */
	private int clanRosterMissingTicks;
	/** ~6 seconds of a genuinely absent channel before the button goes away. */
	private static final int CLAN_ROSTER_GRACE_TICKS = 10;

	/**
	 * Refresh the cached "can we read the roster" answer, with hysteresis.
	 *
	 * <p>{@code getClanChannel()} is momentarily null on login, on a world hop, and while the clan
	 * tab loads. Mirroring that straight into the panel made the roster button appear and disappear
	 * for no reason a player could see, so it takes a few seconds of genuinely NOT being there
	 * before we withdraw the button — while it comes back the instant the channel does.
	 */
	private void updateClanRosterReadable() {
		boolean before = clanRosterReadable;
		if (isClanScrapeAvailable()) {
			clanRosterReadable = true;
			clanRosterMissingTicks = 0;
		} else if (!clanRosterReadable || ++clanRosterMissingTicks >= CLAN_ROSTER_GRACE_TICKS) {
			clanRosterReadable = false;
		}
		// The roster button follows this; the clan channel usually loads a few seconds after login.
		if (before != clanRosterReadable) {
			ClanSettings cs = client.getClanSettings();
			log.info("Clan roster {} (channel={}, settings={}, members={})",
					clanRosterReadable ? "readable" : "not readable",
					client.getClanChannel() != null, cs != null,
					cs == null || cs.getMembers() == null ? 0 : cs.getMembers().size());
			redrawSidebarLocal();
		}
	}

	public boolean isClanScrapeAvailable() {
		if (client == null) {
			return false;
		}
		ClanChannel ch = client.getClanChannel();
		ClanSettings settings = client.getClanSettings();
		return ch != null && settings != null && settings.getMembers() != null && !settings.getMembers().isEmpty();
	}


	/**
	 * Scrape the in-game clan roster (on the client thread) then POST it to the
	 * site (off the client thread), authenticated with the player's account
	 * token.
	 */
	public void syncClanRoster(AdminActionCallback cb) {
		// Every way out of here says why when somebody pressed the button: after "Syncing the clan
		// roster..." a silent return reads as a sync that never finished.
		boolean automatic = autoRosterAnnounce;
		if (!execLive()) {
			cb.onResult(false, "Plugin not running");
			return;
		}
		String token = config.playerToken();
		if (token == null || token.isEmpty()) {
			syncFailed(cb, !automatic, null, "Sign in from the Anvil side panel first.");
			return;
		}

		// Wait your turn. Both buttons and the login-time push come through here, so this is the one
		// place that can hold the line — a cooldown after a push that worked, and a doubling wait
		// after one that didn't, so a site that's down isn't asked again every time someone clicks.
		long gate = now();
		boolean backedOff = !rosterBackoff.ready(gate);
		long waitMs = backedOff
				? rosterBackoff.secondsUntilReady(gate) * 1000L
				: rosterPushAllowedAt - gate;
		if (waitMs > 0) {
			// This attempt isn't happening, so it doesn't get to speak for the login either.
			autoRosterAnnounce = false;
			long secs = secs(waitMs);
			String why = backedOff
					? "The site didn't take the last roster push — trying again in " + secs + "s."
					: "The roster was just synced — try again in " + secs + "s.";
			syncFailed(cb, !automatic, why, why);
			return;
		}

		// Read clan data on the client thread, then POST on the executor thread.
		clientThread.invokeLater(() -> {
			if (!isClanScrapeAvailable()) {
				autoRosterAnnounce = false;
				// The panel offered the button off a cached answer; this is the live one, so believe
				// it and take the button away now rather than after the grace period.
				clanRosterReadable = false;
				clanRosterMissingTicks = CLAN_ROSTER_GRACE_TICKS;
				redrawSidebarLocal();
				syncFailed(cb, !automatic, null, "Join your clan channel first — the roster is read from it.");
				return;
			}
			ClanSettings settings = client.getClanSettings();
			String clanName = settings.getName();
			List<BingoApiClient.ClanMember> members = new ArrayList<>();
			for (net.runelite.api.clan.ClanMember m : settings.getMembers()) {
				BingoApiClient.ClanMember out = new BingoApiClient.ClanMember();
				out.rsn = m.getName();
				ClanRank rank = m.getRank();
				if (rank != null) {
					ClanTitle title = settings.titleForRank(rank);
					out.rank = title != null ? title.getName() : String.valueOf(rank.getRank());
				}
				LocalDate joined = m.getJoinDate();
				if (joined != null) {
					out.joinedDays = (int) java.time.temporal.ChronoUnit.DAYS.between(joined, LocalDate.now());
				}
				members.add(out);
			}

			executor.submit(() -> {
				try {
					ClanSyncResponse r = apiClient.syncClan(config.playerToken(), clanName, members);
					rosterBackoff.onSuccess();
					rosterPushAllowedAt = now() + ROSTER_PUSH_COOLDOWN_MS;
					lastSyncSummary = "+" + r.added + " added · " + r.updated + " updated · " + r.markedLeft + " left";
					// A sync nobody asked for reports itself only when the roster actually MOVED.
					// Silence on the login where nothing changed; one line when somebody joined or
					// left, because that's news whether or not you pressed anything.
					autoRosterAnnounce = false;
					if (automatic) {
						List<String> parts = new ArrayList<>();
						if (r.added > 0) {
							parts.add(r.added + " joined");
						}
						if (r.returned > 0) {
							parts.add(r.returned + " returned");
						}
						if (r.markedLeft > 0) {
							parts.add(r.markedLeft + " left");
						}
						if (r.renamed > 0) {
							parts.add(r.renamed + " renamed");
						}
						// News always gets said. "Nothing changed" gets said once a login — enough to
						// prove the sync ran, not so often that it becomes something to scroll past.
						boolean moved = !parts.isEmpty();
						boolean firstThisLogin = !autoRosterReportedThisLogin;
						autoRosterReportedThisLogin = true;
						if (moved) {
							sendChatMessage("Clan roster updated: " + String.join(", ", parts) + ".");
						} else if (firstThisLogin) {
							sendChatMessage("Clan roster checked — nothing changed.");
						}
					} else {
						sendChatMessage("Clan roster synced: " + lastSyncSummary);
					}
					// Per-member changes — one chat line each, capped so a busy sync doesn't flood
					// chat. Only for a sync somebody asked for: the automatic one has said its piece.
					if (!automatic && r.changes != null && !r.changes.isEmpty()) {
						int cap = 12;
						int shown = 0;
						for (ClanChange ch : r.changes) {
							if (shown >= cap) {
								break;
							}
							String line;
							switch (ch.type == null ? "" : ch.type) {
								case "joined":
									line = ch.rsn + " joined the clan.";
									break;
								case "left":
									line = ch.rsn + " left the clan.";
									break;
								case "returned":
									line = ch.rsn + " returned to the clan.";
									break;
								case "renamed":
									line = (ch.oldRsn == null ? "?" : ch.oldRsn) + " is now known as " + ch.rsn + ".";
									break;
								case "rank_changed":
									line = ch.rsn + " is now " + (ch.newRank == null ? "ranked" : ch.newRank)
											+ (ch.oldRank != null ? " (was " + ch.oldRank + ")" : "") + ".";
									break;
								default:
									continue;
							}
							sendChatMessage(line);
							shown++;
						}
						if (r.changes.size() > cap) {
							sendChatMessage("...and " + (r.changes.size() - cap) + " more changes (see Discord audit feed).");
						}
					}
					// Plan limit. The admin running the sync is the one person who can act on this,
					// and they're right here — so say it in-game rather than leaving it to a banner
					// they'd have to open the site to see. Names come first because "6 members were
					// not added" is only useful if you know WHICH six.
					if (r.refusedNewMembers != null && !r.refusedNewMembers.isEmpty()) {
						int refusedCap = 6;
						String names = String.join(", ",
								r.refusedNewMembers.subList(0, Math.min(refusedCap, r.refusedNewMembers.size())));
						String more = r.refusedNewMembers.size() > refusedCap
								? " and " + (r.refusedNewMembers.size() - refusedCap) + " more"
								: "";
						sendChatMessage("Not added (plan limit): " + names + more + ".");
					}
					if (r.capNotice != null && !r.capNotice.isEmpty()) {
						sendChatMessage(r.capNotice);
					}
					cb.onResult(true, lastSyncSummary);
				} catch (AdminUnauthorizedException e) {
					// Token isn't (or is no longer) an admin — hide the button until the next login probe.
					isAdmin = false;
					syncFailed(cb, true, null, "Your account token isn't an admin (or was revoked).");
				} catch (ClanMismatchException e) {
					String server = e.serverClanName == null ? "(not set)" : e.serverClanName;
					syncFailed(cb, true, null, "Clan name doesn't match site config (" + server + ").");
				} catch (RateLimitedException e) {
					// The site said when. Hold exactly that long rather than guessing at it.
					rosterPushAllowedAt = now() + Math.max(e.retryAfterMs, 1_000L);
					log.debug("Clan sync rate-limited for {}ms", e.retryAfterMs);
					syncFailed(cb, !automatic, "The site is limiting roster syncs — try again in "
							+ secs(e.retryAfterMs) + "s.", "Rate limited by the site.");
				} catch (IOException e) {
					// Might clear on its own (site down, network gone), so wait longer each time
					// instead of letting a button turn into a retry loop against a dead host.
					rosterBackoff.onFailure(now());
					log.warn("Clan sync failed: {}", e.getMessage());
					syncFailed(cb, !automatic, "Clan sync failed: " + e.getMessage(), "Sync failed: " + e.getMessage());
				} catch (RuntimeException e) {
					// Anything unexpected still has to release the button, or it says "Already
					// syncing" until the next login.
					log.warn("Clan sync failed unexpectedly", e);
					syncFailed(cb, !automatic, "Clan sync failed — try again in a moment.", "Sync failed unexpectedly.");
				}
			});
		});
	}

	/**
	 * A roster sync that didn't happen: say why in chat when {@code say} — by default "Clan sync
	 * failed: " and the reason — and hand the reason to the button.
	 */
	private void syncFailed(AdminActionCallback cb, boolean say, String chat, String why) {
		if (say) {
			sendChatMessage(chat != null ? chat : "Clan sync failed: " + Character.toLowerCase(why.charAt(0)) + why.substring(1));
		}
		cb.onResult(false, why);
	}

	/** Whole seconds for a wait in chat — rounded up, never "0s". */
	private static long secs(long ms) {
		return Math.max(1, (ms + 999) / 1000);
	}

	// Team-level tile completions (drops, stats, manual — any tile type, completed by any member).
	// Fire a banner once per newly-completed tile. Seeded silently on the first refresh per event so
	// tiles completed before this session (or a relog) don't re-pop.
	private final Set<Integer> notifiedCompletedTiles = new HashSet<>();
	private Integer completionBaselineEventId;
	// Tiles this client already showed a banner for via the player's own drop. Their completion is
	// skipped here so the contributor doesn't see it twice; teammates still get the team banner.
	private final Set<Integer> locallyShownTiles = new HashSet<>();

	// Ladder missions board: mission tiles we've already alerted "new mission" for, and claim tiles
	// we've already announced. Seeded on the first poll of an event (no backlog dump), cleared on change.
	private final Set<Integer> notifiedMissionTiles = new HashSet<>();
	private final Set<Integer> notifiedClaimTiles = new HashSet<>();
	private Integer ladderBaselineEventId;

	/** Forget which tiles were seen done, so the next poll silently absorbs whatever already is. */
	private void resetCompletionBaseline() {
		notifiedCompletedTiles.clear();
		locallyShownTiles.clear();
		completionBaselineEventId = null;
	}

	private void checkTileCompletions(PluginConfigResponse cfg) {
		if (cfg == null || cfg.event == null || cfg.completedTiles == null) {
			return;
		}
		boolean seeding = completionBaselineEventId == null || completionBaselineEventId != cfg.event.id;
		if (seeding) {
			resetCompletionBaseline();
			completionBaselineEventId = cfg.event.id;
		}
		// Collect this poll's newly-completed tiles. add() still marks every tile seen even when the
		// popup is toggled off, so flipping it on later won't dump a backlog.
		List<CompletedTile> newlyDone = new ArrayList<>();
		boolean anyDone = false;
		for (CompletedTile t : cfg.completedTiles) {
			if (notifiedCompletedTiles.add(t.tileId) && !seeding) {
				anyDone = true;
				onTileConfirmedDone(t.tileId);
				if (!locallyShownTiles.contains(t.tileId)) {
					newlyDone.add(t);
				}
			}
		}
		if (anyDone && sidebarPanel != null) {
			SwingUtilities.invokeLater(sidebarPanel::tileCompleted);
		}
		if (newlyDone.isEmpty() || !config.teamCompletionBanner()) {
			return;
		}
		// Banner only the hardest (most points) tile this poll to avoid a burst of banners.
		CompletedTile hardest = Collections.max(newlyDone, Comparator.comparingInt(t -> t.points));
		clogBanner.show("Anvil Bingo", "Tile complete!", hardest.label);
		playBannerSound();
		// A persistent chat line for EVERY newly-completed tile (including the bannered one) — the
		// banner is easy to miss, so leave a record naming who finished it. Stat/manual completions
		// carry no crediting player, so those just say "Tile complete: <label>!".
		for (CompletedTile t : newlyDone) {
			String by = (t.completedBy != null && !t.completedBy.trim().isEmpty())
					? " — by " + t.completedBy.trim() : "";
			sendChatMessage("Tile complete: " + t.label + by + "!");
		}
	}

	/**
	 * The site just confirmed a tile done. A pinned one shows "Done" now and comes down after its
	 * linger, rather than waiting out two of the tracker's 30s polls.
	 */
	private void onTileConfirmedDone(int tileId) {
		if (!tileTracker.tracks(tileId)) {
			return;
		}
		submit(() -> safely("tileTracker", () -> tileTracker.refresh(tileId)));
		later(() -> safely("tileTracker", () -> tileTracker.refresh(tileId)), TileTracker.DONE_LINGER_MS + 1_000);
	}

	/**
	 * Missions board alerts, diffed across config polls like {@link #checkTileCompletions}: a banner +
	 * chat when a NEW mission drops, and when ANOTHER player claims a lock-out one (own claims skipped).
	 * Both pulse the sidebar card. Seeded on the first poll so opening the board doesn't dump the
	 * backlog. Fires for a ladder OR a classic bingo carrying missions — NOT for a reveal-policy board
	 * (showdown/rotating/bounty), whose reveals keep their existing sidebar-note behaviour.
	 */
	private void checkMissionAlerts(PluginConfigResponse cfg) {
		if (cfg == null || cfg.event == null) {
			return;
		}
		boolean revealBoard = cfg.event.revealPolicy != null && !cfg.event.revealPolicy.isEmpty();
		boolean surface = "ladder".equalsIgnoreCase(cfg.event.format)
			|| (!revealBoard && cfg.serverSupports("bingo-missions"));
		if (!surface) {
			return;
		}
		String tag = "ladder".equalsIgnoreCase(cfg.event.format) ? "Anvil Ladder" : "Anvil";
		boolean seeding = ladderBaselineEventId == null || ladderBaselineEventId != cfg.event.id;
		if (seeding) {
			notifiedMissionTiles.clear();
			notifiedClaimTiles.clear();
			ladderBaselineEventId = cfg.event.id;
		}

		// --- new missions (revealed + open) ---
		List<Mission> fresh = new ArrayList<>();
		if (cfg.event.missions != null) {
			for (Mission m : cfg.event.missions) {
				if (m != null && notifiedMissionTiles.add(m.tileId) && !seeding) {
					fresh.add(m);
				}
			}
		}
		if (!fresh.isEmpty()) {
			Mission top = Collections.max(fresh, Comparator.comparingInt(m -> m.points));
			clogBanner.show(tag, "New mission!", top.label);
			playMissionSound(false);
			for (Mission m : fresh) {
				sendChatMessage("New mission: " + m.label + " - " + m.points + " pts!");
			}
		}

		// --- lock-out claims by OTHER players ---
		String me = Rsn.normalize(getLocalPlayerName());
		List<Claim> claims = new ArrayList<>();
		if (cfg.event.recentClaims != null) {
			for (Claim c : cfg.event.recentClaims) {
				if (c == null || !notifiedClaimTiles.add(c.tileId) || seeding) {
					continue;
				}
				boolean mine = c.rsn != null && !me.isEmpty() && me.equals(Rsn.normalize(c.rsn));
				if (!mine) {
					claims.add(c);
				}
			}
		}
		if (!claims.isEmpty()) {
			Claim latest = claims.get(0);
			String who = latest.rsn != null && !latest.rsn.trim().isEmpty() ? latest.rsn.trim() : "Someone";
			clogBanner.show(tag, "Mission claimed", who + ": " + latest.label);
			playMissionSound(true);
			for (Claim c : claims) {
				String by = c.rsn != null && !c.rsn.trim().isEmpty() ? c.rsn.trim() : "Someone";
				sendChatMessage(by + " claimed " + c.label + " - " + c.points + " pts!");
			}
		}
	}

	/**
	 * Take the clan the site says it answered for, so everything AFTER this call is addressed.
	 *
	 * On Auto the config poll deliberately names no clan, which lets the site keep deciding — a member
	 * whose live board moves to their other clan follows it without touching anything. But the answer
	 * names the clan it is about, and repeating that back on the next request is strictly better than
	 * making the server guess again: it pins a member on two live boards to ONE of them for the whole
	 * exchange, and it is what makes filing a submission work on an address that names no clan at all.
	 *
	 * A site too old to send the field leaves us exactly where we were.
	 */
	private void adoptResolvedClan(PluginConfigResponse fresh) {
		if (fresh == null) {
			return;
		}
		String slug = fresh.activeClanSlug();
		if (slug != null) {
			apiClient.setResolvedClan(slug);
		}
		forgetAClanTheyAreNoLongerIn(fresh);
		forgetAdminAnswerOnClanChange();
	}

	/**
	 * Drop a cached "you are an admin" the moment we start addressing a different clan.
	 *
	 * The probe is answered once per session and a yes is never re-checked, which was right when a
	 * deployment WAS a clan. It is not right now: the same token is an owner in one clan and a plain
	 * member in the next, so an answer carried across a switch shows a button that cannot work.
	 * Clearing it makes the ordinary re-probe ask again, against the clan we are actually addressing.
	 */
	private void forgetAdminAnswerOnClanChange() {
		String now = apiClient.getActiveClan();
		if (now.equals(adminAnswerFor)) {
			return;
		}
		adminAnswerFor = now;
		isAdmin = false;
		adminProbeAttempted = false;
		lastAdminProbeAt = 0L; // ask immediately rather than waiting out the re-probe interval
	}

	/**
	 * Drop a pick for a clan the member no longer has a seat in.
	 *
	 * Leaving a clan is the one way a stored choice becomes permanently wrong: the dropdown stops
	 * offering it, so there is nothing to click to undo it, and the plugin would go on addressing a
	 * clan that answers nothing while a live board runs somewhere they can still reach. Falling back
	 * to Auto puts the decision back with the site, which is where it was before they chose.
	 *
	 * Only acts on a site that actually sends the list — an older one sends nothing, and "no clans" is
	 * then a fact about the site rather than about the member.
	 */
	private void forgetAClanTheyAreNoLongerIn(PluginConfigResponse fresh) {
		String chosen = getChosenClan();
		if (chosen.isEmpty() || fresh.clans == null || fresh.clans.isEmpty()) {
			return;
		}
		for (ClanRef c : fresh.clans) {
			if (c != null && chosen.equalsIgnoreCase(c.slug)) {
				return;
			}
		}
		log.info("No seat in '{}' any more — back to Auto", chosen);
		cfgSet(CFG_ACTIVE_CLAN, "");
		apiClient.setChosenClan("");
	}

	/**
	 * The member picked a clan in the sidebar (or picked Auto, which is a blank slug).
	 *
	 * Persisted, because a pick that evaporated on restart would be worse than no pick at all — the
	 * plugin would quietly go back to guessing and the member would have no reason to look.
	 */
	void setChosenClan(String slug) {
		String clean = slug == null ? "" : slug.trim();
		cfgSet(CFG_ACTIVE_CLAN, clean);
		apiClient.setChosenClan(clean);
		// Re-ask immediately rather than waiting out the poll: the member just told us they wanted a
		// different board, and showing them the old one for another thirty seconds reads as a no-op.
		//
		// Order matters, and it is the whole reason this does not just call the panel's own refresh.
		// The sidebar renders from the config THIS class holds, so refreshing it before the new clan's
		// config has landed re-renders the clan they just switched away from — a click that visibly
		// does nothing, then quietly works fifteen seconds later. Fetch first, repaint second.
		forgetAdminAnswerOnClanChange();
		if (executor != null) {
			executor.execute(() -> {
				refreshConfig();
				repaintSidebar();
			});
		} else {
			// No executor means startUp hasn't run, so there is no panel waiting on a fetch either.
			repaintSidebar();
		}
	}

	/** Something only this client shows on the panel changed (a pin, the starting shot): redraw it. Any thread. */
	private void redrawSidebarLocal() {
		repaintSidebar();
	}

	/** Ask the sidebar to re-read, from the EDT — it is Swing, and callers here are on worker threads. */
	private void repaintSidebar() {
		AnvilSidebarPanel panel = sidebarPanel;
		if (panel != null) {
			SwingUtilities.invokeLater(panel::refresh);
		}
	}

	/** The member's clan pick, or "" when they are on Auto. */
	String getChosenClan() {
		String stored = cfgGet(CFG_ACTIVE_CLAN);
		return stored == null ? "" : stored.trim();
	}

	/**
	 * The sidebar's visible refresh cadence is tighter than the always-on tracker poll. A manual
	 * click always re-reads; background sidebar paints only do so when the last config is genuinely
	 * stale, avoiding two requests landing together around the regular 30-second poll.
	 */
	void refreshConfigForSidebar(boolean force) {
		// The provider smoke test deliberately invokes the sidebar graph on an uninjected plugin;
		// the source must remain usable in that state just as it was before this freshness hook.
		if (apiClient == null) {
			return;
		}
		if (!force) {
			// NEVER WAIT FOR A FETCH TO DRAW. A background paint that finds one in flight (the 30s poll,
			// the login greet) draws from the config already held and picks up the new one next tick —
			// queueing behind it left "Loading…" up for as long as the site took, up to the read timeout.
			// The plugin's own poll keeps the config fresh; this only covers a gap in it.
			if (now() - lastConfigAttemptAt >= (pushLive() ? PUSH_FALLBACK_MS : 25_000L) && configFetchLock.tryLock()) {
				fetchConfigAndUnlock();
			}
			return;
		}
		// A clicked Refresh wants the newest answer. If a fetch is already running, its answer is that —
		// wait for it rather than sending a second one behind it.
		long asked = now();
		configFetchLock.lock();
		if (lastConfigAttemptAt < asked) {
			fetchConfigAndUnlock();
		} else {
			configFetchLock.unlock();
		}
	}

	/**
	 * Serializes config fetches on a lock of their own. NOT the plugin monitor: the fetch is a
	 * blocking HTTP call (90s read timeout), and the client thread takes the plugin monitor via
	 * onConfigChanged → scheduleRefresh whenever it writes a config key — every banked play minute,
	 * new biggest hit, death. Sharing it froze the game for as long as the site took to answer,
	 * most visibly right after a proof upload.
	 */
	private final ReentrantLock configFetchLock = new ReentrantLock();

	/** When a config fetch last FINISHED, success or not — so a failing site isn't asked again on every paint. */
	private volatile long lastConfigAttemptAt;

	/** Signed in, and no config fetch has finished yet — the sidebar shows "Loading", not "no clans". */
	boolean awaitingFirstConfig() {
		return apiClient != null && apiClient.isConfigured() && pluginConfig == null && lastConfigAttemptAt == 0;
	}

	// Site-served re-wordings of chat lines (see ChatPatterns). The last good answer is saved with the
	// config, so a fix survives a restart before the site answers — applied only while the site still
	// advertises the capability.
	private boolean chatPatternsSeeded;
	private long chatPatternsFetchedAt;
	private ChatPatterns.OverridesResponse chatPatternsApplied;
	private static final long CHAT_PATTERNS_EVERY_MS = 30 * 60_000L;

	/** Config-poll thread only — never the client thread: it may hit disk and the network. */
	private void maybeRefreshChatPatterns(PluginConfigResponse cfg) {
		if (cfg == null || !cfg.serverSupports("chat-patterns")) {
			return;
		}
		ResponseDiskCache rc = responseCache;
		if (!chatPatternsSeeded && rc != null) {
			chatPatternsSeeded = true;
			adoptChatPatterns(apiClient.seedFromDisk(rc.load(ResponseDiskCache.CHAT_PATTERNS),
					ChatPatterns.OverridesResponse.class));
		}
		long at = now();
		if (at - chatPatternsFetchedAt < CHAT_PATTERNS_EVERY_MS) {
			return;
		}
		chatPatternsFetchedAt = at;
		adoptChatPatterns(apiClient.fetchChatPatterns());
	}

	/** Apply a fresh override set. A 304 hands back the same object, which is already live. */
	private void adoptChatPatterns(ChatPatterns.OverridesResponse res) {
		if (res == null || res == chatPatternsApplied) {
			return;
		}
		chatPatternsApplied = res;
		for (String why : ChatPatterns.applyOverrides(res.overrides)) {
			log.warn("Chat pattern override rejected — {}", why);
		}
	}

	private void refreshConfig() {
		configFetchLock.lock();
		fetchConfigAndUnlock();
	}

	private boolean pushLive() {
		PushSocket p = pushSocket;
		return p != null && p.live();
	}

	/**
	 * Live push on, off, or re-ticketed: it listens for the board (and team) this config answers for,
	 * so a new one of either needs a new ticket. Off where the site doesn't run it.
	 */
	private void syncPush() {
		PushSocket p = pushSocket;
		PluginConfigResponse cfg = pluginConfig;
		int eventId = cfg == null ? 0 : cfg.event != null ? cfg.event.id : cfg.homeBoard != null ? cfg.homeBoard.eventId : 0;
		if (p != null) {
			p.scope(eventId > 0 && apiClient.isConfigured() && serverSupportsCap("push-ws")
					? eventId + ":" + (cfg.team != null ? cfg.team.id : 0) : null);
		}
	}

	/** A view from the live push (docs/PLUGIN_WIRE.md), applied off the socket's thread. */
	private void onPush(JsonObject m) {
		if (execLive()) {
			executor.execute(() -> safely("push", () -> applyPush(m)));
		}
	}

	/**
	 * "tile": a pinned tile's numbers for every team. "team": our team's share of the config, its
	 * board, and each member's own numbers — laid over the config we hold (PushMerge) and adopted the
	 * way a fetched one is, so tile completions and missions announce exactly as they do on a poll.
	 */
	private void applyPush(JsonObject m) {
		PluginConfigResponse cfg = pluginConfig;
		int eventId = m.get("eventId").getAsInt();
		int myTeam = cfg != null && cfg.team != null ? cfg.team.id : 0;
		int me = cfg != null && cfg.player != null ? cfg.player.id : 0;
		if ("tile".equals(m.get("t").getAsString())) {
			tileTracker.pushed(eventId, m.get("tileId").getAsInt(),
					gson.fromJson(m.get("progress"), TileTracker.Progress.class), myTeam, me);
			return;
		}
		String kind = m.get("t").getAsString();
		boolean ours = cfg != null && cfg.event != null && cfg.event.id == eventId && myTeam == m.get("teamId").getAsInt();
		AnvilSidebarPanel panel = sidebarPanel;
		if ("counts".equals(kind)) {
			// Only counts moved: the team's by tile in c, ours over them, laid on what we hold. The
			// panel's live counts follow at once; the rest of it (who's on what) catches up lazily.
			if (ours) {
				JsonObject members = m.has("m") ? m.getAsJsonObject("m") : new JsonObject();
				JsonObject own = members.has(String.valueOf(me)) ? members.getAsJsonObject(String.valueOf(me)) : new JsonObject();
				JsonObject counts = m.has("c") ? m.getAsJsonObject("c").deepCopy() : new JsonObject();
				if (own.has("c")) {
					own.getAsJsonObject("c").entrySet().forEach(e -> counts.add(e.getKey(), e.getValue()));
				}
				JsonObject mine = new JsonObject();
				mine.add("c", counts);
				if (own.has("y")) {
					mine.add("y", own.get("y"));
				}
				adoptPushed(cfg, PushMerge.merge(gson.toJsonTree(cfg).getAsJsonObject(), new JsonObject(), mine));
			}
			if (panel != null) {
				panel.countsChanged();
			}
			return;
		}
		// A whole view for a different team of the event we hold: the site moved us (it re-scopes the
		// socket on a team change). Fetch the config now instead of tracking the old team until the
		// slow while-live poll.
		if ("team".equals(kind) && cfg != null && cfg.event != null && cfg.event.id == eventId
				&& m.get("teamId").getAsInt() != myTeam) {
			refreshConfig();
		}
		if (ours && m.has("config")) {
			JsonObject members = m.has("members") ? m.getAsJsonObject("members") : new JsonObject();
			JsonObject mine = members.has(String.valueOf(me)) ? members.getAsJsonObject(String.valueOf(me)) : null;
			adoptPushed(cfg, PushMerge.merge(gson.toJsonTree(cfg).getAsJsonObject(), m.getAsJsonObject("config"), mine));
		}
		// A whole view (something other than counts changed) or "moved" (the board did, not our team).
		if (panel != null) {
			panel.boardChanged();
		}
	}

	/** A config built from a push, taken up like a fetched one — unless a fetch landed meanwhile. */
	private void adoptPushed(PluginConfigResponse held, JsonObject merged) {
		PluginConfigResponse fresh = gson.fromJson(merged, PluginConfigResponse.class);
		configFetchLock.lock();
		try {
			// A fetch that landed meanwhile is at least as new: keep it.
			if (pluginConfig == held) {
				adoptTracking(fresh);
				if (apiClient.getCurrentRsn() != null) {
					checkTileCompletions(fresh);
					checkMissionAlerts(fresh);
				}
			}
		} finally {
			configFetchLock.unlock();
		}
	}

	private static boolean sameTeam(PluginConfigResponse a, PluginConfigResponse b) {
		return a != null && b != null && a.event != null && b.event != null && a.event.id == b.event.id
				&& (a.team == null ? 0 : a.team.id) == (b.team == null ? 0 : b.team.id);
	}

	/**
	 * A newer config takes over tracking, fetched or pushed. Locally-counted gain and kill progress is
	 * kept: the server's copy lags while gathering (flushes coalesce up to GAIN_MAX_HOLD_MS), so
	 * wholesale-replacing would snap an in-progress tile's live count backward (the reported
	 * karambwan/impling flakiness). Each fresh count is floored at what we've already counted.
	 */
	private void adoptTracking(PluginConfigResponse fresh) {
		PluginConfigResponse held = pluginConfig;
		// Another team's (or event's) counts are no floor for this one: a team move, or an alt on the
		// other side, would otherwise build on the old team's numbers.
		PluginConfigResponse prior = sameTeam(held, fresh) ? held : null;
		if (prior == null) {
			optimistic.reset();
		}
		pluginConfig = fresh;
		rebuildItemDropIndex();
		keepLocalFloor(prior == null ? null : prior.trackedGains, fresh.trackedGains, g -> g.tileId,
				g -> g.currentAmount, g -> g.requiredAmount, (g, v) -> g.currentAmount = v);
		keepLocalFloor(prior == null ? null : prior.trackedKills, fresh.trackedKills, k -> k.tileId,
				k -> k.currentAmount, k -> k.requiredAmount, (k, v) -> k.currentAmount = v);
		tileCountsFor = null; // the floors above changed it in place
		liveCountsMoved();
	}

	/** The fetch, by a caller already holding {@link #configFetchLock}, which this releases. */
	private void fetchConfigAndUnlock() {
		try {
			refreshConfigLocked();
			syncPush();
		} finally {
			lastConfigAttemptAt = now();
			configFetchLock.unlock();
		}
	}

	private void refreshConfigLocked() {
		if (!apiClient.isConfigured()) {
			return;
		}
		try {
			PluginConfigResponse fresh = apiClient.fetchConfig();
			lastConfigRefreshAt = now();
			liveConfigAnswered = true;
			forgetSavedResponses();
			if (siteUnreachable) {
				siteUnreachable = false;
				onSiteRecovered();
			}
			// A refresh that returned (HTTP 200/304, no throw) proves the token is good — clear any
			// connection-failure streak and announce recovery if we'd nagged.
			noteConnectionOk();
			adoptResolvedClan(fresh);
			maybeRefreshChatPatterns(fresh);

			// Token validated but the caller has no active event right now (server
			// returns event: null + noActiveEvent: true). Clear local state so tracking
			// reflects no active event rather than a stale one.
			if (fresh != null && fresh.event == null) {
				pluginConfig = fresh;
				rebuildItemDropIndex();
				if (fresh.unlinkedActiveEvent != null && !fresh.unlinkedActiveEvent.isEmpty()) {
					// The diagnostic "money line" for debug exports: the token is valid AND this RSN
					// IS a player in a live bingo — but the account/token isn't linked to it, so
					// tracking is silently OFF. Distinct from a genuine "not enrolled anywhere" below.
					log.warn("RSN '{}' plays in '{}' but isn't linked to this token — tracking is OFF",
							getLocalPlayerName(), fresh.unlinkedActiveEvent);
				} else {
					log.info("Token valid, no active event");
				}
				warnUnlinkedRsn(fresh.unlinkedActiveEvent);
				return;
			}
			// If the linked event has ended, drop it so tracking stops for the stale event.
			if (fresh != null && fresh.event != null && eventIsOver(fresh.event)) {
				log.info("Event '{}' ended — clearing player binding",
						fresh.event.name);
				pluginConfig = null;
				rebuildItemDropIndex();
				cfgSet("playerToken", "");
				return;
			}
			adoptTracking(fresh);
			// One tracking-state summary, logged only when it CHANGES (the refresh runs every
			// ~30s) — the first thing to read in a client.log when "nothing tracked": it says
			// what the plugin believed it was tracking, and when that belief changed.
			String summary = String.format(Locale.ROOT,
					"event='%s' team='%s' drops=%d kills=%d pvp=%d gains=%d timed=%d"
							+ " deathless=%d lms=%d values=%d diaries=%d combatTasks=%d completed=%d",
					pluginConfig.event.name, pluginConfig.team.name,
					sizeOf(pluginConfig.trackedDrops), sizeOf(pluginConfig.trackedKills),
					sizeOf(pluginConfig.trackedPvp),
					sizeOf(pluginConfig.trackedGains), sizeOf(pluginConfig.trackedTimed),
					sizeOf(pluginConfig.trackedDeathless), sizeOf(pluginConfig.trackedLms),
					sizeOf(pluginConfig.trackedValues), sizeOf(pluginConfig.trackedDiaries),
					sizeOf(pluginConfig.trackedCombatTasks), sizeOf(pluginConfig.completedTiles));
			if (!summary.equals(lastTrackingFingerprint)) {
				lastTrackingFingerprint = summary;
				log.info("Tracking: {}", summary);
			}

			// Before login stamps an RSN, the event can only have come off the launcher hint. Everything
			// below speaks in chat or seeds the completion baseline, and each latches once per login —
			// run now, the line would go nowhere and the latch would eat the real one. The refresh
			// stampIdentityAndGreet makes after login does it for real.
			if (apiClient.getCurrentRsn() == null) {
				return;
			}
			checkTileCompletions(pluginConfig);
			checkMissionAlerts(pluginConfig);
			// Covers login (stampIdentityAndGreet calls refreshConfig) AND an event with CA
			// tiles going live mid-session via the periodic refresh. No-ops once sent.
			maybeNudgeCaRepeatSetting();
			maybeNudgeLootNotifications();
			maybeNudgeClogNotifications();
			maybeNudgeStartProof();
			maybeReprobeAdmin();

		} catch (IOException e) {
			log.warn("Failed to refresh Anvil config: {}", e.getMessage());
			// A definite refusal (no clan, bad token) is an answer too: the saved copy goes. A site
			// that is down or slow is not — keep showing it until one does answer.
			int code = e instanceof HttpStatusException ? ((HttpStatusException) e).code : 0;
			if (code >= 400 && code < 500 && code != 408 && code != 429) {
				liveConfigAnswered = true;
				forgetSavedResponses();
			} else {
				siteUnreachable = true; // down, slow or 5xx: the next answer is a recovery
			}
			noteConnectionProblem(e);
		}
	}

	/**
	 * One chat nudge per login when this account still owes a STARTING SHOT — the event is live, the
	 * location is drawn, and nothing has been filed. Says where to stand and that the panel button
	 * does the rest; repeating it every 30s refresh would just be noise, so it latches.
	 */
	private void maybeNudgeStartProof() {
		if (startProofNudged || !needsStartProof()) {
			return;
		}
		StartProof sp = pluginConfig.startProof;
		startProofNudged = true;
		String left = StartProofRules.describeWindow(sp, now());
		sendChatMessage("Starting shot needed before you play"
				+ (sp.location != null && !sp.location.isEmpty() ? " — go to " + sp.location : "")
				+ (sp.spot != null && config.autoStartShot()
						? ". Stand there and it's taken and sent for you (or press \"Take starting shot\" in the Anvil side panel)."
						: ". Open the Anvil side panel and press \"Take starting shot\".")
				+ (sp.maxSessionMinutes > 0
						? " Take it within " + sp.maxSessionMinutes + " min of logging in — hiscores only save"
						+ " on logout, so that's what sets your starting totals."
						: "")
				// The consequence, which the nudge never spelled out: a player told only that
				// something is "needed" has no reason to do it before their next drop.
				+ " Until it's filed your drops are held for review"
				+ (left != null ? ", and it's only asked for another " + left : "")
				+ ".");
	}

	/**
	 * Say it once, at the moment it starts costing them something: a credit is going up while this
	 * account still owes a STARTING SHOT, so the site will hold it for review.
	 *
	 * The login nudge fires before anyone has done anything, which is the easiest message in the
	 * world to scroll past. This one lands on the drop itself. Once per login — the point is to be
	 * noticed, and a line per kill is how a plugin gets turned off.
	 */
	private void warnStartProofBeforeCredit() {
		if (startProofCreditWarned || !needsStartProof()) {
			return;
		}
		startProofCreditWarned = true;
		sendChatMessage("That's recorded, but your starting shot is still missing — it stays held for"
				+ " review until you take it. Anvil side panel → \"Take starting shot\".");
	}

	/**
	 * Ask again whether this account is an admin, while the answer is still no.
	 *
	 * <p>The probe used to be strictly once per login, and it latched its "attempted" flag BEFORE the
	 * request — so a site that was restarting at the three-second mark cost an admin their
	 * "Sync clan roster" button for the entire session, with nothing in chat to say why. Re-asking
	 * every few minutes costs one tiny request and heals that by itself. A yes is never re-checked;
	 * losing admin mid-session is a logout-shaped problem, not a poll-shaped one.
	 */
	private void maybeReprobeAdmin() {
		if (isAdmin || !apiClient.isConfigured()) {
			return;
		}
		long now = now();
		if (now - lastAdminProbeAt < ADMIN_REPROBE_MS) {
			return;
		}
		lastAdminProbeAt = now;
		boolean admin = apiClient.fetchIsAdmin(config.playerToken());
		if (admin) {
			isAdmin = true;
			log.info("Admin confirmed on retry");
		}
	}

	/**
	 * Ask whether this account is an admin right now, skipping the re-probe interval — for the
	 * sidebar's Refresh button. Off the EDT (the panel's worker calls it). Unlike the timed re-probe
	 * it also takes a no: a member who clicks Refresh gets the site's current answer either way.
	 */
	void reprobeAdminNow() {
		if (!apiClient.isConfigured()) {
			return;
		}
		lastAdminProbeAt = now();
		adminProbeAttempted = true;
		boolean admin = apiClient.fetchIsAdmin(config.playerToken());
		if (admin != isAdmin) {
			log.info("Admin re-checked on Refresh — now {}", admin ? "admin" : "not admin");
		}
		isAdmin = admin;
	}

	private static boolean eventIsOver(EventInfo ev) {
		if (ev == null) {
			return false;
		}
		if (ev.forceEndedAt != null && !ev.forceEndedAt.isEmpty()) {
			return true;
		}
		if (ev.endDate == null || ev.endDate.isEmpty()) {
			return false;
		}
		try {
			return Instant.parse(ev.endDate).isBefore(Instant.now());
		} catch (Exception ignored) {
			return false;
		}
	}

	/**
	 * Rebuild the itemId → TrackedDrop index for O(1) loot lookups.
	 */
	private void rebuildItemDropIndex() {
		PluginConfigResponse cfg = pluginConfig;
		boolean has = cfg != null;
		itemDropIndex = indexBy(has ? cfg.trackedDrops : null, d -> d.itemIds, id -> id);
		Set<Integer> notable = has && cfg.alwaysNotifyItemIds != null ? new HashSet<>(cfg.alwaysNotifyItemIds) : new HashSet<>();
		notable.remove(null);
		notableItemIds = notable;
		// Lowercased NPC name → kill tiles, and itemId → gain tiles, for O(1) matching.
		// Keyed by the in-game name: wiki variants ("Armoured zombie (Zemouregal's Fort)") report bare.
		killNpcIndex = indexBy(has ? cfg.trackedKills : null, k -> k.targetNpcs,
				n -> n.isEmpty() ? null : DropSource.inGameNpcName(n).toLowerCase());
		gainItemIndex = indexBy(has ? cfg.trackedGains : null, g -> g.itemIds, id -> id);
		rebuildPvpRosterIndex();
		// The in-game KC-line boss names and the skill names to push real-time counts for.
		trackedKcNames = names(has ? cfg.trackedKcNames : null, n -> n.isEmpty() ? null : normalizeBossName(n));
		trackedSkillNames = names(has ? cfg.trackedSkillNames : null, n -> n.isEmpty() ? null : n.toLowerCase(Locale.ROOT).trim());
		Map<String, List<TrackedStat>> stats = new HashMap<>();
		Map<String, Integer> byName = new HashMap<>();
		for (TrackedStat t : has && cfg.trackedStats != null ? cfg.trackedStats : Collections.<TrackedStat>emptyList()) {
			if (t != null && t.statName != null) {
				byName.putIfAbsent(t.statName.toLowerCase(Locale.ROOT).trim(), t.tileId);
				// A composite tile listing one name twice is still bumped once.
				for (String key : t.statType == null ? new String[0] : t.statName.split(",")) {
					List<TrackedStat> l = stats.computeIfAbsent(statKey(t.statType, key), x -> new ArrayList<>());
					if (!l.contains(t)) {
						l.add(t);
					}
				}
			}
		}
		statTileIndex = stats;
		statTileByName = byName;
		alwaysNotifyLower = names(has ? cfg.alwaysNotifyItems : null, n -> n.isEmpty() ? null : n.toLowerCase());
		rebuildTrackedActivityKeys();
	}

	/** Skill tiles and boss/KC tiles keyed apart, each by {@link #compactStat}. */
	private static String statKey(String kind, String name) {
		return ("skill".equals(kind) ? "s:" : "b:") + compactStat(name);
	}

	/**
	 * Rebuild the set of activity keys to push counts for; refreshed with the drop index.
	 *
	 * <p>Filtered down to what {@link ActivityStats} can actually read, so a tile tracking an LMS or
	 * Bounty Hunter RANK — which the client has no counter for — never enters the push path and
	 * quietly keeps its hiscores-sweep behaviour.
	 */
	private void rebuildTrackedActivityKeys() {
		PluginConfigResponse cfg = pluginConfig;
		trackedActivityKeys = names(cfg != null && cfg.serverSupports("activity-stats") ? cfg.trackedActivityKeys : null,
				k -> ActivityStats.isReadable(k.trim()) ? k.trim() : null);
		if (trackedActivityKeys.isEmpty()) {
			activityPush.reset();
		}
	}

	/** {@code norm} of each name, skipping nulls and anything {@code norm} turns into null. */
	private static Set<String> names(List<String> raw, Function<String, String> norm) {
		Set<String> out = new HashSet<>();
		if (raw != null) {
			for (String r : raw) {
				String n = r == null ? null : norm.apply(r);
				if (n != null) {
					out.add(n);
				}
			}
		}
		return out;
	}

	/** {@code key → tiles} over the keys each tile lists, as {@code norm} spells them; null keys are skipped. */
	private static <T, R, K> Map<K, List<T>> indexBy(List<T> tiles, Function<T, List<R>> keys, Function<R, K> norm) {
		Map<K, List<T>> index = new HashMap<>();
		if (tiles != null) {
			for (T t : tiles) {
				List<R> raw = keys.apply(t);
				for (R r : raw == null ? Collections.<R>emptyList() : raw) {
					K k = r == null ? null : norm.apply(r);
					if (k != null) {
						index.computeIfAbsent(k, x -> new ArrayList<>()).add(t);
					}
				}
			}
		}
		return index;
	}


	/** A stat name reduced to letters and digits, so "Kree'Arra", "kreeArra" and "kree arra" meet. */
	static String compactStat(String s) {
		return s == null ? "" : NON_ALNUM.matcher(s.toLowerCase(Locale.ROOT)).replaceAll("");
	}

	/**
	 * Move every KC / XP tile watching {@code name} up by {@code delta} locally, ahead of the push, and
	 * say whether that took one to its goal — the push then goes now, not after the streak settles, so
	 * the site can complete the tile while the member is still looking at it. A
	 * composite tile ("CoX + CoX: CM") matches on any of its keys; a name that matches no key the way
	 * the site spells it simply isn't bumped, and the tile moves when the push lands, as before.
	 */
	private boolean bumpStatTiles(String kind, String name, int delta) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg == null || cfg.trackedStats == null) {
			return false;
		}
		boolean finishes = false;
		for (TrackedStat s : statTileIndex.getOrDefault(statKey(kind, name), Collections.emptyList())) {
			optimistic.add(s.tileId, s.currentAmount, delta, now());
			liveCountsMoved();
			finishes |= s.goalAmount > 0 && s.currentAmount < s.goalAmount
					&& optimistic.floor(s.tileId, now()) >= s.goalAmount;
		}
		return finishes;
	}

	/** This client just bumped a tile to {@code current}: hold that count and show it now. */
	private void raiseLocal(int tileId, long current, long at) {
		optimistic.raise(tileId, current, at);
		liveCountsMoved();
	}

	/** tileId → the held config's count (fetched or pushed), rebuilt when the config is replaced. */
	private volatile Map<Integer, Long> tileCounts = Collections.emptyMap();
	private volatile PluginConfigResponse tileCountsFor;

	/**
	 * The newest count this client has for a tile: the held config's, or its own unconfirmed one when
	 * higher; -1 when it tracks no such tile. What the panel's live counts move to (UiView.tickLive).
	 */
	long tileCount(int tileId) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg != tileCountsFor) {
			Map<Integer, Long> counts = new HashMap<>();
			if (cfg != null) {
				for (Map.Entry<String, JsonElement> e : gson.toJsonTree(cfg).getAsJsonObject().entrySet()) {
					if (!e.getKey().startsWith("tracked") || !e.getValue().isJsonArray()) {
						continue;
					}
					for (JsonElement row : e.getValue().getAsJsonArray()) {
						JsonObject r = row.isJsonObject() ? row.getAsJsonObject() : null;
						if (r == null || !r.has("tileId") || !r.has("currentAmount")) {
							continue;
						}
						int tile = r.get("tileId").getAsInt();
						// A set or collection tile counts pieces here, but the panel shows the best
						// set (10 pieces vs "2 / 4"): not the same number, so it doesn't move live.
						JsonElement reqs = r.get("itemRequirements");
						if (reqs != null && reqs.isJsonArray() && reqs.getAsJsonArray().size() > 0) {
							counts.put(tile, -1L);
						} else if (counts.getOrDefault(tile, 0L) >= 0) {
							counts.merge(tile, r.get("currentAmount").getAsLong(), Math::max);
						}
					}
				}
			}
			tileCounts = counts;
			tileCountsFor = cfg;
		}
		Long site = tileCounts.get(tileId);
		if (site != null && site < 0) {
			return -1; // a set tile: see above
		}
		if (site != null) {
			optimistic.seen(tileId, site);
		}
		long floor = optimistic.floor(tileId, now());
		return site == null ? (floor > 0 ? floor : -1) : Math.max(site, floor);
	}

	/** Counts moved here (own progress, a pushed or fetched config): the panel redraws its live ones. */
	private void liveCountsMoved() {
		AnvilSidebarPanel panel = sidebarPanel;
		if (panel != null) {
			panel.liveCountsMoved();
		}
	}

	/** This client's unconfirmed count for a tile (0 when none) — read-only, see OptimisticProgress.floor. */
	long optimisticFloor(int tileId) {
		return optimistic.floor(tileId, now());
	}

	/** What to show for a tile the site last put at {@code siteCurrent}: that, or this client's newer count. */
	long shownProgress(int tileId, long siteCurrent) {
		return optimistic.apply(tileId, siteCurrent, now());
	}

	/**
	 * The local player just gained on the tracked stat tile whose {@code statName} matches {@code name}
	 * (skill name or boss KC name, case-insensitive); a name that maps to no stat tile is ignored.
	 * Called from the XP/KC push path, so it only fires on the local account's own gains.
	 */
	private void noteLocalStatProgress(String name) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg == null || cfg.trackedStats == null || name == null) {
			return;
		}
		Integer tileId = statTileByName.get(name.toLowerCase(Locale.ROOT).trim());
		if (tileId != null) {
			noteLocalProgress(tileId);
		}
	}

	/**
	 * THIS account just progressed {@code tileId} — any tile kind. A pinned tile then shows it a few
	 * seconds later rather than on the next 30s poll — long enough for the push that carries it to land
	 * on the site first.
	 */
	private void noteLocalProgress(int tileId) {
		if (tileId > 0 && tileTracker.tracks(tileId)) {
			later(() -> safely("tileTracker", () -> tileTracker.refresh(tileId)), 4_000);
		}
	}

	/**
	 * Whether the real-time stat push paths (skill XP + boss KC) may send right now.
	 *
	 * THE TRACKED-NAME SETS ARE THE FILTER. The server tells the plugin exactly which bosses and
	 * skills anything is watching — a bingo tile, a live SOTW, a live BOTW — and with nothing
	 * watching they are empty and nothing queues. That is the whole gate, and it is the server's to
	 * decide because only the server knows what is running.
	 *
	 * IT USED TO ALSO DEMAND AN ACTIVE BINGO, and that quietly turned the weekly off. Being drafted
	 * into a board that starts in six weeks is enough to make cfg.event non-null and not active, so
	 * a member grinding Kalphite Queen for the Boss of the Week pushed nothing at all: the server
	 * was asking for `kalphite queen` in trackedKcNames and the plugin refused to send it, because
	 * of a bingo neither of them was playing yet. The competition then moved only on the hiscores
	 * sweep, which lags by design — seven kills, +0 kc, and nothing wrong anywhere to point at.
	 *
	 * Sending during an inactive event is safe on the other side: lib/completionGate refuses any
	 * completion before a board starts, and stat baselines re-anchor at the start, so a pre-event
	 * push cannot score. Withholding it was the only thing that could go wrong, and did.
	 *
	 * NO SETTING SITS IN FRONT OF THIS. It briefly had its own, and before that it rode on "Auto
	 * Submit Drops" — a switch about screenshotting a drop, which said nothing about stats and yet
	 * stopped SOTW and BOTW moving while you played. Both failed the same way: silently. The member
	 * sees a leaderboard that never updates, and the site sees an account gaining XP with no client
	 * attached, because the only trace a missing push leaves is an absence. Moving the board you are
	 * on is what this plugin is FOR.
	 */
	static boolean statPushAllowed(PluginConfigResponse cfg) {
		return cfg != null;
	}

	/**
	 * Also when signed in with no clan: the site keeps a person's stats on their own account with or
	 * without one (the stats route's account-only path), and it alone decides whether the character
	 * is theirs — an unclaimed or someone else's character is simply not stored.
	 */
	static boolean statPushAllowed(PluginConfigResponse cfg, boolean signedInWithoutClan) {
		return statPushAllowed(cfg) || signedInWithoutClan;
	}

	private boolean statPushAllowed() {
		return statPushAllowed(pluginConfig, apiClient != null && apiClient.signedInWithoutClan());
	}

	/**
	 * Buffers a skill's absolute XP for a debounced push. Absolute XP is idempotent, so the latest
	 * value overwrites and a training burst becomes one push. Runs on the client thread
	 * (onStatChanged); the network send happens on the executor.
	 *
	 * EVERYTHING, NOT JUST WHAT IS BEING WATCHED. This asked trackedSkillNames first, which made the
	 * client's report a function of what happened to be running: a skill nobody had a tile for went
	 * unreported, and the number only appeared when the hiscores sweep caught up — hours later, and
	 * only if the account had logged out. The plugin is the one thing that sees a gain the moment it
	 * happens, so it is the primary source and the sweep is the fallback that fills what it missed.
	 * The server already keeps max(hiscores, pushed) per key, so an extra key costs one map entry
	 * and can never lower anything.
	 */
	private void maybeQueueSkillXpPush(String skillName, int xp, boolean realGain) {
		if (skillName == null || !statPushAllowed()) {
			return;
		}
		// "Active now" stays about TILES — it means "this account is grinding the thing your board
		// is watching", and saying it for every skill would make the signal meaningless.
		if (realGain && trackedSkillNames.contains(skillName.toLowerCase(Locale.ROOT).trim())) {
			noteLocalStatProgress(skillName);
		}
		Integer prevXp = lastSeenXp.put(compactStat(skillName), xp);
		boolean finishes = realGain && prevXp != null && xp > prevXp && bumpStatTiles("skill", skillName, xp - prevXp);
		skillXpPush.queue(skillName, xp);
		if (finishes) {
			skillXpPush.sendNow();
		}
	}


	/**
	 * Normalize a boss name for matching: lowercase, non-alphanumeric → space, collapse. Mirrors the
	 * server's lib/pluginStats so a KC line's boss name lines up with the config's watch-list
	 * regardless of punctuation — e.g. "Tombs of Amascut: Expert Mode" ↔ "tombs of amascut expert mode".
	 */
	private static String normalizeBossName(String s) {
		return SearchAliases.fold(s);
	}

	/**
	 * Push the killcount an unlock just happened at, bypassing the tracked-boss gate.
	 *
	 * {@link #maybeQueueKcPush} only pushes bosses some tile tracks, which is right for board
	 * scoring and wrong here: a clog unlock is worth dating whatever the board happens to be about,
	 * and the boss it came from usually isn't on it. The kill line always precedes the loot, so the
	 * most recent one is the kill that produced this unlock — with a window on it, so an unlock that
	 * arrives with no recent kill (a shop-bought minigame reward, a gamble pet) pushes nothing
	 * rather than attributing itself to whatever was killed an hour ago.
	 */
	private void pushKcForUnlock() {
		if (!statPushAllowed() || lastKcName == null) {
			return;
		}
		if (now() - lastKcAtMs > KC_ATTRIBUTION_WINDOW_MS) {
			return;
		}
		kcPush.queue(lastKcName, lastKcValue);
	}

	/**
	 * Buffers a boss's absolute kill count for a debounced push.
	 *
	 * Same reasoning as the skill push above: reported whether or not anything is watching, because
	 * the client is the only place a kill is known immediately. A KC line is rare enough that the
	 * volume is nothing, and the value is absolute, so a repeat is a no-op server-side.
	 */
	private void maybeQueueKcPush(String bossName, int kc) {
		if (!statPushAllowed()) {
			return;
		}
		if (trackedKcNames.contains(normalizeBossName(bossName))) {
			noteLocalStatProgress(bossName); // "Active now": grinding the thing a board is watching
		}
		// A KC line is one kill (one clear, one chest), so the first one after login still moves the
		// tile by one; after that the absolute count says how many, in case a line was missed.
		Integer prevKc = lastSeenKc.put(compactStat(bossName), kc);
		boolean finishes = (prevKc == null || kc > prevKc)
				&& bumpStatTiles("boss", bossName, prevKc == null ? 1 : kc - prevKc);
		kcPush.queue(bossName, kc);
		if (finishes) {
			kcPush.sendNow();
		}
	}

	/**
	 * Read the tracked activity counters and buffer any that have risen since the last push.
	 *
	 * <p>Runs on the client thread (varbit change / game tick), which is where the varps have to be
	 * read; the network send happens on the executor. Diffing against what was last sent is what
	 * keeps this quiet — these counters move a handful of times a session, so the common case is a
	 * read, no change, and no request.
	 */
	private void maybeQueueActivityPush() {
		// EVERY COUNTER THIS CAN READ, not only the ones something is watching — the same rule the
		// skill and KC pushes now follow, so one client report covers all three and the sweep is the
		// fallback for whatever the client was not running to see. Reading them is a handful of
		// varbit lookups against client memory; the send is debounced and carries absolute values,
		// so an unchanged counter costs nothing.
		Set<String> wanted = ActivityStats.readableKeys();
		if (wanted.isEmpty() || !statPushAllowed() || !execLive()) {
			return;
		}
		activityPush.queue(ActivityStats.read(wanted, client::getVarbitValue, client::getVarpValue));
	}

	/* -------------------------------------------------------------- */
	/* Recap "fun stat" counters — deaths, total loot value, PvP     */
	/* kills. Cosmetic superlatives only; never touch scoring.        */
	/* -------------------------------------------------------------- */

	/**
	 * Make sure the in-memory counters belong to the CURRENT active event, loading the persisted values
	 * on first use (so a restart mid-event resumes counting) and zeroing them when the active event
	 * changes. Returns false — counting is skipped — when tracking is off (no config, or the event
	 * isn't active), mirroring every other auto-tracking gate. Call under
	 * {@link #counterLock}.
	 */
	private boolean ensureCounterEvent() {
		if (!countersLoaded) {
			counterEventId = (int) cfgLong(CFG_COUNTER_EVENT);
			eventDeaths = (int) cfgLong(CFG_COUNTER_DEATHS);
			eventLootGp = cfgLong(CFG_COUNTER_LOOTGP);
			eventPvpKills = (int) cfgLong(CFG_COUNTER_PVP);
			eventBiggestHit = (int) cfgLong(CFG_COUNTER_BIGHIT);
			eventMinutes = (int) cfgLong(CFG_COUNTER_MINUTES);
			eventCaTasks = (int) cfgLong(CFG_COUNTER_CATASKS);
			countersLoaded = true;
		}
		if (trackingGateReason() != null) {
			return false;
		}
		int active = (pluginConfig != null && pluginConfig.event != null) ? pluginConfig.event.id : 0;
		if (active <= 0) {
			return false;
		}
		if (active != counterEventId) {
			counterEventId = active;
			eventDeaths = 0;
			eventLootGp = 0;
			eventPvpKills = 0;
			eventBiggestHit = 0;
			eventCaTasks = 0;
			eventMinutes = 0;
			eventTickAccumulator = 0;
			persistCounters();
		}
		return true;
	}

	/**
	 * A combat task the player just completed for the FIRST time (the caller has already checked the
	 * points varbit rose, so a "Repeat completion" echo never reaches here).
	 *
	 * Two jobs, neither of them a notification: queue it for the highlight feed, and count it for
	 * the event's Task Master award. The site decides which tiers are worth showing on which board —
	 * a floor that lives here would need a release to change, and it can't know that the clan is
	 * running a Zulrah week.
	 */
	private void noteCombatTaskMoment(CombatAchievementTier tier, String task) {
		if (task == null || task.isEmpty()) {
			return;
		}
		// The tier is never absent: the completion line names it, and the parse above stands down
		// when that word isn't a tier we recognise — so nothing reaches here without one. The site
		// relies on that (a `ca` moment with no rankable tier is rejected at its ingest route).
		moments.record(AnvilMoments.Moment.combatTask(
				task, tier.getDisplayName(), now()));
		scheduleMomentPush();

		// No live event of ours: the feed still took it, the counter has nowhere to go.
		bumpEventCounter(() -> eventCaTasks++);
	}

	/** Bump a per-event counter (only during an event of ours), save it and push it soon. */
	private void bumpEventCounter(Runnable bump) {
		synchronized (counterLock) {
			if (!ensureCounterEvent()) {
				return;
			}
			bump.run();
			persistCounters();
		}
		scheduleCounterPush();
	}

	/** Our own death happened during an active event → bump the per-event death counter and push. */
	private void recordEventDeath() {
		bumpEventCounter(() -> eventDeaths++);
	}

	/**
	 * A hitsplat we landed → the per-event "hardest hit" high-water mark. Called from every one of
	 * our hitsplats, so it stays a cheap compare-and-return in the common case: only a genuine new
	 * record touches the lock, persists, or schedules a push.
	 */
	private void recordEventHit(int damage) {
		synchronized (counterLock) {
			if (damage <= eventBiggestHit) {
				return;
			}
		}
		bumpEventCounter(() -> eventBiggestHit = Math.max(eventBiggestHit, damage));
	}

	/**
	 * Bank a minute of play. Driven from the game tick, so it measures time actually logged in
	 * during the event — the number that turns every other counter into a rate ("most kills" is
	 * usually just "played most"). Ticks are ~600ms; 100 of them make a minute.
	 */
	private void recordEventTick() {
		boolean bankedMinute;
		synchronized (counterLock) {
			if (!ensureCounterEvent()) {
				// Not in a tracked event — don't let stale ticks bank into the next one.
				eventTickAccumulator = 0;
				return;
			}
			if (++eventTickAccumulator < TICKS_PER_MINUTE) {
				return;
			}
			eventTickAccumulator = 0;
			eventMinutes++;
			persistCounters();
			// Push on a slow cadence: a minute ticking over isn't worth a request every time.
			bankedMinute = eventMinutes % MINUTES_PER_PLAYTIME_PUSH == 0;
		}
		if (bankedMinute) {
			scheduleCounterPush();
		}
	}

	/** One attributed dangerous-PvP kill (see onActorDeath) → the per-event PKer counter. */
	private void recordEventPvpKill() {
		bumpEventCounter(() -> eventPvpKills++);
	}

	/**
	 * Price a whole loot haul and add its GE value to the per-event loot total. Called from the same
	 * loot events as {@link #processValueTiles} (which price only when a value tile exists) so EVERY
	 * haul counts, value tile or not. A short fingerprint dedup absorbs the known NpcLootReceived +
	 * LootReceived double-fire for the same haul. Client thread only (itemManager.getItemPrice).
	 */
	private void recordEventLoot(String source, Collection<ItemStack> items, String sourceKind) {
		// Note the haul for the clog notifier BEFORE the event gate: a collection-log unlock is worth
		// announcing whether or not a bingo is running, so its sprite/source lookup can't be gated on
		// one. Cheap — a few map writes that expire on their own.
		rememberLootForClog(source, sourceKind, items);
		// For the clan's highlight feed: a competition week has no bingo to gate on, and a
		// near-miss during one that DOES have a bingo is worth as much as a hit.
		recordLootMoments(source, sourceKind, items);
		if (items == null || items.isEmpty() || trackingGateReason() != null) {
			return;
		}
		long haulGp = haulValue(items);
		long count = items.stream().filter(it -> it != null && it.getId() > 0).count();
		if (haulGp <= 0) {
			return;
		}
		// Dedup identical hauls arriving on two loot events back-to-back (source + value + item count).
		String fp = sourceKind + "|" + source + "|" + haulGp + "|" + count;
		long now = now();
		synchronized (lastLootValueAt) {
			lastLootValueAt.values().removeIf(t -> now - t > DEDUP_WINDOW_MS);
		}
		if (!claim(lastLootValueAt, fp, now, DEDUP_WINDOW_MS)) {
			return;
		}
		synchronized (counterLock) {
			if (!ensureCounterEvent()) {
				return;
			}
			eventLootGp += haulGp;
		}
		scheduleCounterPush();
	}

	/** Debounce a counter push onto the executor — a burst of loot/deaths collapses to one absolute push. */
	private void scheduleCounterPush() {
		synchronized (counterLock) {
			counterPushTask = reschedule(counterPushTask, this::flushCounterPush, COUNTER_PUSH_COALESCE_MS);
		}
	}

	/** Push the current absolute per-event counters. Absolute + server max-merge → a failure just retries. */
	private void flushCounterPush() {
		int deaths;
		long lootGp;
		int pvpKills;
		int biggestHit;
		int minutes;
		int caTasks;
		synchronized (counterLock) {
			persistCounters();
			deaths = eventDeaths;
			lootGp = eventLootGp;
			pvpKills = eventPvpKills;
			biggestHit = eventBiggestHit;
			minutes = eventMinutes;
			caTasks = eventCaTasks;
		}
		PluginConfigResponse cfg = pluginConfig;
		if (cfg == null || cfg.event == null || !AnvilOverlay.isEventActive(cfg.event)) {
			return; // event ended between schedule and flush — drop; nothing feeds scoring off this.
		}
		try {
			apiClient.submitEventCounters(deaths, lootGp, pvpKills, biggestHit, minutes, caTasks);
		} catch (IOException e) {
			log.warn("Counter push failed (deaths={}, lootGp={}, pvpKills={}) — retrying: {}", deaths, lootGp, pvpKills, e.getMessage());
			scheduleCounterPush();
		}
	}

	// ── Highlight feed ────────────────────────────────────────────────────────────────────────────
	//
	// Everything below reports; nothing below decides. Which competition week or board a moment
	// belongs to, whether an item counts as a unique, and which pets belong to which skill are all
	// the site's business (src/lib/moments.ts) — so this sends generously and expects most of it to
	// be discarded, and a clan changing any of those rules costs no plugin release.

	/** True when this member wants a feed and the site has one to put it on. */
	private boolean momentsEnabled() {
		PluginConfigResponse cfg = pluginConfig;
		return config.shareMoments() && apiClient.isConfigured()
				&& cfg != null && cfg.serverSupports("moments");
	}

	/**
	 * Note a drop worth a line on the feed.
	 *
	 * <p>The value floor is the client's only filter and it is deliberately loose — the site knows
	 * what the board and the week care about, this only knows what would be silly to send (every
	 * rune from every kill). An item the site can't place costs one discarded row.
	 */
	private void recordDropMoment(String source, String sourceKind, Integer itemId, String itemName, int quantity, long valueGp) {
		if (!momentsEnabled() || (itemId == null && (itemName == null || itemName.isEmpty()))) {
			return;
		}
		long now = now();
		moments.record(new AnvilMoments.Moment("drop", itemId, itemName, quantity, valueGp,
				source, sourceKind, killCountFor(source), now,
				AnvilMoments.keyFor("drop", source, itemId, now)));
		scheduleMomentPush();
	}

	/**
	 * Pick what to report out of one kill's loot.
	 *
	 * <p>Two ways in, because they catch different things. PRICE catches the drop everyone in the
	 * clan would want to hear about, whatever dropped it. The BOARD's own item list catches the one
	 * worth nothing on the GE and everything to the people playing — an untradeable unique, or the
	 * piece a tile wanted that credited nothing because the tile was already finished or the source
	 * was wrong. That near-miss is half of what a highlight feed is for.
	 *
	 * <p>Capped at a few per haul, dearest first: a raid chest is not a reason to send twenty rows.
	 */
	private void recordLootMoments(String source, String sourceKind, Collection<ItemStack> items) {
		if (items == null || items.isEmpty() || !momentsEnabled()) {
			return;
		}
		Map<Integer, List<TrackedDrop>> boardItems = itemDropIndex;
		PluginConfigResponse cfg = pluginConfig;
		Set<Integer> luckItems = cfg != null && cfg.luckItemIds != null && cfg.serverSupports("luck-drops")
				? new HashSet<>(cfg.luckItemIds) : Collections.emptySet();
		// Merge stacks first — a kill that drops coins twice is one line, not two.
		Map<Integer, Integer> merged = new LinkedHashMap<>();
		for (ItemStack item : items) {
			if (item == null || item.getId() <= 0) {
				continue;
			}
			merged.merge(item.getId(), Math.max(1, item.getQuantity()), Integer::sum);
		}

		List<int[]> candidates = new ArrayList<>(); // {itemId, quantity, value}
		for (Map.Entry<Integer, Integer> entry : merged.entrySet()) {
			int itemId = entry.getKey();
			int quantity = entry.getValue();
			long price = itemManager.getItemPrice(itemId);
			long value = (long) Math.max(0, price) * quantity;
			// A luck item goes up whatever it sells for: an untradeable vestige is worth 0 here.
			boolean wanted = (boardItems != null && boardItems.containsKey(itemId)) || luckItems.contains(itemId);
			if (!wanted && value < AnvilMoments.MIN_REPORTABLE_GP) {
				continue;
			}
			candidates.add(new int[]{itemId, quantity, (int) Math.min(Integer.MAX_VALUE, value)});
		}
		// Luck items first, then by value: the three-per-kill cap must never cut the vestige for a
		// stack of runes worth more on the GE.
		candidates.sort((a, b) -> {
			int luck = Boolean.compare(luckItems.contains(b[0]), luckItems.contains(a[0]));
			return luck != 0 ? luck : Integer.compare(b[2], a[2]);
		});

		int sent = 0;
		for (int[] c : candidates) {
			if (sent++ >= 3) {
				break;
			}
			recordDropMoment(source, sourceKind, c[0], itemName(c[0]), c[1], c[2]);
		}
	}

	/**
	 * Note a collection-log unlock for the feed.
	 *
	 * <p>This is the route for the unlocks the loot path can't see: an untradeable worth nothing on
	 * the GE will never clear a price floor, and some rewards are handed over with no loot event at
	 * all. It fires on the ungated chat line, so a member with every notification off still lands
	 * on the clan's feed.
	 *
	 * <p>Skips anything a real loot event just reported — that is the SAME acquisition arriving
	 * twice (the chest, then the pickup), and the loot copy already carries the price and stack.
	 */
	private void recordClogUnlockMoment(String itemName) {
		if (itemName == null || itemName.isEmpty() || !momentsEnabled()) {
			return;
		}
		Integer itemId = resolveItemIdByName(itemName);
		long now = now();
		if (itemId != null) {
			synchronized (recentLootItemIds) {
				recentLootItemIds.values().removeIf(t -> now - t > CLOG_LOOT_DEDUP_MS);
				if (recentLootItemIds.containsKey(itemId)) {
					return;
				}
			}
		}
		String source;
		String sourceKind;
		synchronized (recentLootIds) {
			boolean fresh = lastLootSource != null && now - lastLootSourceAt <= CLOG_LOOT_DEDUP_MS;
			source = fresh ? lastLootSource : null;
			sourceKind = fresh ? lastLootSourceKind : null;
		}
		long value = itemId != null ? Math.max(0, itemManager.getItemPrice(itemId)) : 0;
		recordDropMoment(source, sourceKind, itemId, itemName, 1, value);
	}

	/**
	 * Note a pet. Called from the chat line itself, NOT from the notifier — a member with the drops
	 * channel switched off still got the pet, and the clan's feed is a different thing from their
	 * Discord settings.
	 *
	 * @return the queue key, so the collection-log line that names the pet can fill it in
	 */
	private String recordPetMoment(String source, String sourceKind, Integer kc) {
		if (!momentsEnabled()) {
			return null;
		}
		long now = now();
		// Keyed WITHOUT an item id, because at this point nobody knows which pet it was — the name
		// lands a tick or two later and nameQueued() fills it into this same entry.
		String key = AnvilMoments.keyFor("pet", source, null, now);
		moments.record(new AnvilMoments.Moment("pet", null, null, 1, null, source, sourceKind, kc, now, key));
		scheduleMomentPush();
		return key;
	}

	/** Name a pet already queued, once the collection-log line says which one it was. */
	private void namePetMoment(String key, String itemName, String source, Integer kc) {
		if (key == null || !momentsEnabled()) {
			return;
		}
		moments.nameQueued(key, itemName, resolveItemIdByName(itemName), source, kc);
	}

	/**
	 * Note a death, and what killed us.
	 *
	 * <p>The killer is inferred from what had us TARGETED when we last took damage, not from what we
	 * were hitting — see DeathAttribution for why the client cannot simply be asked, and for what
	 * the difference looked like in the feed ("died to Jug"). What we were fighting is still used,
	 * but only to break a tie between several things attacking us at once.
	 *
	 * <p>Null when nothing had us targeted, which is a mechanic or a fall, and the feed then says
	 * only that someone died. A death with no killer is a smaller story than one with the wrong.
	 */
	private void recordDeathMoment() {
		if (!momentsEnabled()) {
			return;
		}
		long now = now();
		String fighting = (lastCombatTarget != null && now - lastCombatTargetAt <= DEATH_ATTRIBUTION_MS)
				? lastCombatTarget : null;
		String killer = deathAttribution.killer(fighting, now);
		// Breadcrumb so client.log can explain an attribution that looks odd: how many things had us
		// and which one we picked, next to what we were hitting.
		log.debug("Death: killer='{}' (attackers={}, we were fighting '{}')",
				killer, deathAttribution.attackerCount(), fighting);
		moments.record(new AnvilMoments.Moment("death", null, null, 1, null, killer, "npc",
				killCountFor(killer), now, AnvilMoments.keyFor("death", killer, null, now)));
		scheduleMomentPush();
		// The fight is over: whatever had us targeted has no claim on the next one. Cleared here
		// rather than waiting for each attacker to drop us, which an instance tear-down never
		// reports — a stale attacker would otherwise be the prime suspect for the next death.
		deathAttribution.clear();
	}

	/**
	 * Note a level worth remembering: a 99, a high total, or a max.
	 *
	 * <p>Called from the DETECTION, deliberately not from the announcer. Whether the clan has a
	 * Discord channel for level posts is a question about Discord; whether a 99 belongs on the clan's
	 * feed is a question about the feed, and answering the second with the first is how a member with
	 * notifications off vanishes from their own clan's history.</p>
	 *
	 * <p>Sent generously, like everything else here: the site decides whether a running board or
	 * competition week wants it, and drops it when nothing does.</p>
	 */
	private void recordLevelMoment(String skill, int level, String scope) {
		if (!momentsEnabled() || statsAreArtificial()) {
			return;
		}
		moments.record(AnvilMoments.Moment.level(skill, level, scope, now()));
		scheduleMomentPush();
	}

	/** Debounce a moment push — a kill's two loot events and a pet's chat lines collapse into one request. */
	private void scheduleMomentPush() {
		synchronized (moments) {
			// While backing off, a new moment rides the retry already waiting instead of pulling it forward.
			if (momentFailures > 0 && momentPushTask != null && !momentPushTask.isDone()) {
				return;
			}
			momentPushTask = reschedule(momentPushTask, this::flushMomentPush, MOMENT_PUSH_COALESCE_MS);
		}
	}

	/**
	 * Send the queued moments.
	 *
	 * <p>The batch stays queued until the site confirms it, so a failed push retries with nothing
	 * lost — and since every entry is keyed, a push that succeeded but whose reply we never saw
	 * stores nothing the second time.
	 */
	private void flushMomentPush() {
		if (!momentsEnabled() || moments.isEmpty()) {
			return;
		}
		List<AnvilMoments.Moment> batch = moments.nextBatch();
		if (batch.isEmpty()) {
			return;
		}
		try {
			apiClient.submitMoments(batch);
		} catch (PermanentSubmissionException e) {
			// The site will never take this batch; drop it rather than resend it forever.
			log.warn("Moment push refused — dropping {}: {}", batch.size(), e.getMessage());
			moments.onSent(batch);
			return;
		} catch (IOException e) {
			long wait;
			synchronized (moments) {
				momentFailures++;
				wait = RetryPolicy.backoffMs(momentFailures, MOMENT_PUSH_COALESCE_MS, CoalescedPush.RETRY_CAP_MS, Math.random());
				momentPushTask = reschedule(momentPushTask, this::flushMomentPush, wait);
			}
			log.debug("Moment push failed ({} queued) — retrying in {}s: {}", moments.size(), wait / 1000, e.getMessage());
			return;
		}
		synchronized (moments) {
			momentFailures = 0;
		}
		moments.onSent(batch);
		// More than one batch's worth waiting (a long offline stretch) — keep going.
		if (!moments.isEmpty()) {
			scheduleMomentPush();
		}
	}

	/** Persist the per-event counters to the config store so a restart resumes them. Call under counterLock. */
	private void persistCounters() {
		cfgSet(CFG_COUNTER_EVENT, Integer.toString(counterEventId));
		cfgSet(CFG_COUNTER_DEATHS, Integer.toString(eventDeaths));
		cfgSet(CFG_COUNTER_LOOTGP, Long.toString(eventLootGp));
		cfgSet(CFG_COUNTER_PVP, Integer.toString(eventPvpKills));
		cfgSet(CFG_COUNTER_BIGHIT, Integer.toString(eventBiggestHit));
		cfgSet(CFG_COUNTER_MINUTES, Integer.toString(eventMinutes));
		cfgSet(CFG_COUNTER_CATASKS, Integer.toString(eventCaTasks));
	}

	/**
	 * Fold a kill's loot into the vestige rotation of whichever boss dropped it, and say where the
	 * player now stands. Independent of bingo: the cycle is account state, so it keeps counting with
	 * no event running, and it never gates on tracking being enabled.
	 */
	private void trackVestigeRolls(String source, Collection<ItemStack> items) {
		if (pluginConfig == null || pluginConfig.rollTables == null || items == null || items.isEmpty()) {
			return;
		}
		RollTable table = null;
		for (RollTable t : pluginConfig.rollTables) {
			if (t != null && t.boss != null && t.boss.equalsIgnoreCase(source)) {
				table = t;
				break;
			}
		}
		if (table == null) {
			return;
		}
		String rsn = getLocalPlayerName();
		String rsnKey = rsn == null ? "" : rsn.trim().toLowerCase(Locale.ROOT);
		if (vestigeRolls == null || !rsnKey.equals(vestigeRollsRsn)) {
			vestigeRolls = VestigeRolls.parse(cfgGet(accountKey(CFG_VESTIGE_ROLLS, rsnKey)));
			vestigeRollsRsn = rsnKey;
		}
		for (ItemStack item : items) {
			// Each unique in the loot is its own roll — a kill that somehow hands you two advances
			// the cycle twice, which is what the table did.
			VestigeRolls.Result r = vestigeRolls.record(table, item.getId());
			if (r == null) {
				continue;
			}
			cfgSet(accountKey(CFG_VESTIGE_ROLLS, rsnKey), vestigeRolls.serialise());
			sendChatMessage(table.boss + ": " + r.line);
			// Remembered for the drop post, which is built moments later off the same loot event.
			lastVestigeLine = r.line;
			lastVestigeLineAt = now();
		}
	}

	/**
	 * What this client can see of its company right now: roster teammates in the instance, and the
	 * party headcount. Deliberately two signals — names are reliable for a single-arena boss and
	 * useless inside a raid (the party splits across rooms), while the raid party varbits are
	 * reliable exactly there. The server decides what to do with them; a client never suppresses
	 * its own submission, because two clients that can't see each other would both stay quiet.
	 */
	private CoopFingerprint coopFingerprint() {
		List<String> teammates = new ArrayList<>();
		Set<String> mine = myTeamRoster();
		if (!mine.isEmpty()) {
			String me = Rsn.normalize(getLocalPlayerName());
			// Copy before iterating: the set is written from the game tick, and this runs off a
			// kill credit on the same thread today — but a snapshot costs nothing and can't throw.
			for (String seen : new ArrayList<>(instancePlayersSeen)) {
				String n = Rsn.normalize(seen);
				if (!n.isEmpty() && !n.equals(me) && mine.contains(n)) {
					teammates.add(n);
				}
			}
		}
		int party = partySize();
		CoopFingerprint fp = new CoopFingerprint(teammates, party);
		return fp.isEmpty() ? null : fp;
	}

	/** A number this plugin stored in config; 0 when it's missing or corrupt. */
	private long cfgLong(String key) {
		try {
			String v = cfgGet(key);
			return v == null || v.isEmpty() ? 0 : Long.parseLong(v.trim());
		} catch (RuntimeException e) {
			return 0;
		}
	}

	/**
	 * Rebuild the normalised-RSN → teamId roster index used by PvP-kill tiles'
	 * "team:other" selectors; refreshed together with the drop index. Empty
	 * unless the event has a pvp tile (the server only ships the roster then).
	 */
	private void rebuildPvpRosterIndex() {
		Map<String, Integer> index = new HashMap<>();
		if (pluginConfig != null && pluginConfig.pvpRoster != null) {
			for (RosterEntry entry : pluginConfig.pvpRoster) {
				if (entry != null && entry.name != null && !entry.name.isEmpty()) {
					index.put(Rsn.normalize(entry.name), entry.teamId);
				}
			}
		}
		pvpRosterIndex = index;
	}

	/**
	 * Keep locally-counted progress across a config refresh: raise each fresh tile's count to at
	 * least what we'd already tallied (and not yet flushed), capped at the requirement.
	 *
	 * <p>Gain and kill tiles both count locally and flush on a debounce, so between the count and the
	 * flush the server's copy is behind. Replacing the tracked tiles wholesale snapped an in-progress
	 * tile back to the server's stale number: ten chickens read 1,2,3,4,5 and then 1,2,3 again as
	 * the refresh landed mid-streak, before jumping to 6,7,10 once the earlier flushes were counted
	 * (and the karambwan/impling flakiness on gathers, whose flushes coalesce up to GAIN_MAX_HOLD_MS).
	 * Nothing was lost — the server's total was right the whole time — but the player is watching
	 * the wrong number and cannot tell those apart. Trade-off: an admin who deletes a submission
	 * won't see the count drop until the player re-logs, the much better of the two surprises.
	 */
	private static <T> void keepLocalFloor(List<T> old, List<T> fresh, ToIntFunction<T> tileId,
			ToIntFunction<T> current, ToIntFunction<T> required, ObjIntConsumer<T> setCurrent) {
		if (old == null || fresh == null) {
			return;
		}
		Map<Integer, Integer> local = new HashMap<>();
		for (T t : old) {
			if (t != null) {
				local.put(tileId.applyAsInt(t), current.applyAsInt(t));
			}
		}
		for (T t : fresh) {
			Integer prior = t == null ? null : local.get(tileId.applyAsInt(t));
			if (prior != null && prior > current.applyAsInt(t)) {
				setCurrent.accept(t, Math.min(prior, required.applyAsInt(t)));
			}
		}
	}

	/** Flush every pending gain aggregate now (e.g. on logout/hop) so trickle catches still
	 *  coalescing aren't lost — they only live in memory until submitted. */
	private void flushAllPendingGains() {
		List<Integer> tileIds;
		synchronized (pendingGainAggregates) {
			tileIds = new ArrayList<>(pendingGainAggregates.keySet());
		}
		for (int tileId : tileIds) {
			flushGains(tileId);
		}
	}



	/** True when the team has already completed this tile (per the last config refresh). */
	private boolean isTileCompleted(int tileId) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg == null || cfg.completedTiles == null) {
			return false;
		}
		for (CompletedTile c : cfg.completedTiles) {
			if (c != null && c.tileId == tileId) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Logs a tracking-suppression reason once per session at INFO. The gates this guards run
	 * for every loot/kill/chat signal, so unconditional logging would flood client.log —
	 * once per reason keeps the log diagnostic ("send me your client.log") without the spam.
	 */
	private void logTrackingSuppressed(String reason) {
		if (loggedSuppressions.add(reason)) {
			log.info("Tracking suppressed — {} (logged once per session)", reason);
		}
	}

	private static int sizeOf(Map<?, ?> map) {
		return map == null ? 0 : map.size();
	}

	private static int sizeOf(List<?> list) {
		return list == null ? 0 : list.size();
	}

	/** True — with the reason logged, once a session — when tracking is off (see trackingGateReason). */
	private boolean trackingOff() {
		String gate = trackingGateReason();
		if (gate != null) {
			logTrackingSuppressed(gate);
		}
		return gate != null;
	}

	/** The suppression reason for the shared config gates, or null when tracking is live. */
	private String trackingGateReason() {
		if (pluginConfig == null) {
			return "no event config loaded (not enrolled, or token/RSN not resolved)";
		}
		if (!AnvilOverlay.isEventActive(pluginConfig.event)) {
			return "event not currently active";
		}
		return null;
	}

	private boolean isBlackout() {
		if (pluginConfig == null || pluginConfig.trackedDrops == null || pluginConfig.trackedDrops.isEmpty()) {
			return false;
		}
		for (TrackedDrop drop : pluginConfig.trackedDrops) {
			if (drop.currentAmount < drop.requiredAmount) {
				return false;
			}
		}
		return true;
	}

	/* -------------------------------------------------------------- */
 /* Clan notifications — deaths, rare drops, pets (posted to Discord */
 /* via the site, independent of bingo state).                     */
 /* -------------------------------------------------------------- */
	@Subscribe
	public void onActorDeath(ActorDeath event) {
		// Runs on the client thread — keep this cheap: a reference check + (optionally) a frame
		// request. Encoding and the network send happen off-thread.
		Actor actor = event.getActor();

		// Remember the last NPC that died near us so a timed "Duration:" line can attribute itself
		// to the boss we just killed without a hardcoded activity table.
		if (actor instanceof NPC) {
			String npcName = actor.getName();
			if (npcName != null && !npcName.isEmpty()) {
				lastNpcDeathName = npcName;
				lastNpcDeathAt = now();
			}
		}

		// Deathless raids: any player dying while we're inside an instance counts against the
		// current run (raid instances are private, so any player here is a party member).
		if (actor instanceof Player && wasInInstance) {
			instancePlayerDeaths++;
		}

		// Our own death → deaths channel.
		if (actor == client.getLocalPlayer()) {
			// LMS: dying while the BR HUD reads N survivors means we placed Nth. Record before
			// the notification gates — placement tracking is independent of death notifications.
			// A counter never read (0) is an unknown place, not 2nd: guessing 2nd credited top-2
			// tiles for deaths that could have been anywhere in the game.
			if (lmsInGame && !lmsPlacementRecorded && lmsSurvivors > 0) {
				recordLmsPlacement(Math.max(lmsSurvivors, 2));
			}
			// Recap counter — count the death for the "Wipe Magnet" superlative even if death
			// notifications are off (still gated on an active event inside).
			recordEventDeath();
			// Clan feed — WHAT killed us, which is the half the recap counter throws away. Dying to
			// the boss everyone is racing that week is the story; dying in general is a number.
			// Recorded here rather than beside the post below, so the drops channel being off can't
			// erase it.
			recordDeathMoment();
			if (!config.notifyDeaths()) {
				return;
			}
			if (!notifyEnabled("deaths")) {
				return;
			}
			String message = buildDeathMessage(getLocalPlayerName());
			captureFrameAsync(png -> apiClient.postNotification("deaths", message, null, png, "anvil-death.png"));
			return;
		}

		// A player we damaged dying → our PvP kill. ActorDeath fires on the tick the death
		// animation starts (target at 0 HP) — the moment we want the screenshot, and a reliable
		// signal even for loot-key kills (which produce no ground loot and only a random taunt
		// message). Damage attribution (a hitsplat we dealt within the window) says the kill is
		// ours; the Player gives the victim name for the roster / RSN-bounty match. Consumed once
		// so a single death credits once. Caveat: if two attackers both damaged the victim, both
		// credit — the baked screenshot is the audit trail.
		if (actor instanceof Player) {
			String vname = actor.getName();
			if (vname != null && !vname.isEmpty()) {
				long now = now();
				boolean ours;
				synchronized (lastDamagedPlayerAt) {
					lastDamagedPlayerAt.values().removeIf(t -> (now - t) > PVP_KILL_ATTRIBUTION_MS);
					Long last = lastDamagedPlayerAt.remove(vname.toLowerCase());
					ours = last != null && (now - last) <= PVP_KILL_ATTRIBUTION_MS;
				}
				if (ours) {
					// Recap counter first: ANY dangerous-PvP kill feeds the PKer superlative,
					// pvp tiles on the board or not. Tile credit + notify keep their own gates.
					if (inDangerousPvp()) {
						recordEventPvpKill();
					}
					creditPvpKillTiles(vname);
					if (config.notifyPvpKills()) {
						notifyPvpKill(vname);
					}
				}
			}
		}
	}

	/** True when the current event config carries any PvP-kill tiles. */
	private boolean hasPvpTiles() {
		PluginConfigResponse cfg = pluginConfig;
		return cfg != null && cfg.trackedPvp != null && !cfg.trackedPvp.isEmpty();
	}

	/**
	 * True when the recap PvP-kill counter alone wants damage→death attribution: an active event
	 * with auto-tracking on. Kept to cheap reference checks — this runs per hitsplat; the full
	 * tracking gate applies later inside ensureCounterEvent().
	 */
	private boolean pvpCounterActive() {
		PluginConfigResponse cfg = pluginConfig;
		return cfg != null && cfg.event != null && AnvilOverlay.isEventActive(cfg.event);
	}

	/** Dangerous PvP only — the Wilderness or a PvP world. Safe minigames (LMS, Soul Wars,
	 *  Castle Wars, PvP Arena) and DMM never count as PKs. Client thread (varbit read). */
	private boolean inDangerousPvp() {
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1
				|| client.getWorldType().contains(WorldType.PVP);
	}

	/**
	 * Posts a PvP kill to the kills channel. Called from onActorDeath once the kill is already
	 * attributed to us (damage within the window), so this just applies the channel toggle and
	 * posts. Runs on the client thread; screenshot + network send are deferred.
	 */
	private void notifyPvpKill(String name) {
		if (!notifyEnabled("pvpKills")) {
			return;
		}
		String message = buildKillMessage(getLocalPlayerName(), name);
		captureFrameAsync(png -> apiClient.postNotification("pvpKills", message, null, png, "anvil-pvp-kill.png"));
	}

	/**
	 * Credits PvP-kill bingo tiles for a kill attributed to us — called from onActorDeath when a
	 * player we damaged (within the attribution window) dies. Using the death (not a chat line)
	 * makes it work for loot-key kills, which produce only a random taunt message and no ground
	 * loot. Only dangerous PvP counts — the Wilderness or a PvP world — so safe minigames (LMS,
	 * Soul Wars, Castle Wars, PvP Arena) and DMM can't farm the tile. Selector semantics:
	 * "team:other" matches any event participant on a different team (via the pvpRoster index —
	 * so the victim must be enrolled on a team with a matching RSN); "rsn:&lt;name&gt;" matches
	 * that exact player, enrolled or not. Amount 1 per kill through the shared proof pipeline (the
	 * death fires on the kill tick — the frame still shows the fight).
	 */
	private void creditPvpKillTiles(String victimName) {
		if (trackingOff() || pluginConfig.trackedPvp == null || pluginConfig.trackedPvp.isEmpty()) {
			return;
		}
		if (!inDangerousPvp()) {
			logTrackingSuppressed("PvP kill outside dangerous PvP (Wilderness / PvP world) — not counted");
			return;
		}
		String victim = Rsn.normalize(victimName);
		Integer myTeam = pluginConfig.team != null ? pluginConfig.team.id : null;
		boolean anyDeferred = false;
		for (TrackedPvp tile : pluginConfig.trackedPvp) {
			if (tile == null || tile.targets == null || tile.currentAmount >= tile.requiredAmount
					|| isTileCompleted(tile.tileId) || !pvpVictimMatchesTile(tile, victim, myTeam)) {
				continue;
			}
			// A min-loot floor is checked against the kill's LOOT, which only arrives in a later
			// PlayerLootReceived — park the kill and let that event credit it. Every other PvP tile
			// credits off the death now (still works for loot-key kills, which drop no ground loot).
			if (tile.minLootValue > 0) {
				anyDeferred = true;
				continue;
			}
			creditOnePvpTile(tile, victimName);
		}
		if (anyDeferred) {
			long now = now();
			synchronized (pendingMinLootKillAt) {
				pendingMinLootKillAt.values().removeIf(t -> (now - t) > PVP_MINLOOT_LOOT_WINDOW_MS);
				pendingMinLootKillAt.put(victim, now);
			}
		}
	}

	/** Selector match for a PvP tile against a normalised victim RSN ('any' / 'team:other' / 'rsn:&lt;name&gt;'). */
	private boolean pvpVictimMatchesTile(TrackedPvp tile, String victimNorm, Integer myTeam) {
		if (tile.targets == null) {
			return false;
		}
		Integer victimTeam = pvpRosterIndex.get(victimNorm);
		for (String sel : tile.targets) {
			if (sel == null) {
				continue;
			}
			String s = sel.trim();
			if (s.equalsIgnoreCase("any")) {
				// Any player kill counts — no team/bounty restriction (the caller already gated on
				// dangerous-PvP, so safe minigames don't reach here).
				return true;
			} else if (s.equalsIgnoreCase("team:other")) {
				if (victimTeam != null && myTeam != null && !victimTeam.equals(myTeam)) {
					return true;
				}
			} else if (s.regionMatches(true, 0, "rsn:", 0, 4)) {
				if (Rsn.normalize(s.substring(4)).equals(victimNorm)) {
					return true;
				}
			}
		}
		return false;
	}

	/** Optimistically bump a PvP tile and submit a baked kill screenshot (rollback reverts on failure). */
	private void creditOnePvpTile(TrackedPvp tile, String victimName) {
		tile.currentAmount += 1;
		raiseLocal(tile.tileId, tile.currentAmount, now());
		log.debug("Tracked PvP kill: {} → tile '{}' ({}/{})",
				victimName, tile.label, tile.currentAmount, tile.requiredAmount);
		String detail = "Killed " + victimName + "  (" + tile.currentAmount + "/" + tile.requiredAmount + ")";
		captureAndSubmitProof(tile.tileId, tile.label, 1, null,
				"BINGO PVP KILL", detail,
				"[Auto] PvP kill on " + victimName + " — detected by RuneLite plugin",
				() -> tile.currentAmount = Math.max(0, tile.currentAmount - 1));
	}

	/**
	 * Credits PvP min-loot tiles from a kill's loot — called from onPlayerLootReceived. If we parked a
	 * matching kill on this victim at death (pendingMinLootKillAt) and the loot prices at/above a
	 * tile's floor, credit it. The loot is priced once and every qualifying min-loot tile for this
	 * victim is credited; the parked entry is consumed so one kill credits at most once per tile.
	 */
	private void creditPvpMinLootKillTiles(String victimName, Collection<ItemStack> items) {
		if (pluginConfig == null || pluginConfig.trackedPvp == null || pluginConfig.trackedPvp.isEmpty()
				|| items == null || items.isEmpty() || victimName == null) {
			return;
		}
		String victim = Rsn.normalize(victimName);
		long now = now();
		synchronized (pendingMinLootKillAt) {
			Long parkedAt = pendingMinLootKillAt.remove(victim); // consume — one credit per parked kill
			if (parkedAt == null || (now - parkedAt) > PVP_MINLOOT_LOOT_WINDOW_MS) {
				return;
			}
		}
		if (trackingGateReason() != null) {
			return;
		}
		long haulGp = haulValue(items);
		Integer myTeam = pluginConfig.team != null ? pluginConfig.team.id : null;
		for (TrackedPvp tile : pluginConfig.trackedPvp) {
			if (tile == null || tile.minLootValue <= 0 || tile.currentAmount >= tile.requiredAmount
					|| isTileCompleted(tile.tileId) || !pvpVictimMatchesTile(tile, victim, myTeam)) {
				continue;
			}
			if (haulGp < tile.minLootValue) {
				log.info("PvP kill on {} worth {} gp is below tile '{}' floor {} gp — not counted",
						victimName, haulGp, tile.label, tile.minLootValue);
				continue;
			}
			creditOnePvpTile(tile, victimName);
		}
	}

	private String buildKillMessage(String killer, String victim) {
		String who = (killer == null || killer.isEmpty()) ? "Someone" : killer;
		return "**" + who + "** just killed **" + victim + "**!";
	}

	/**
	 * Reports loot to the rare-drops channel. Loot keys and regular drops are
	 * kept separate: - A loot key (the "Loot Chest" open) is reported as ONE
	 * unit, gated only by "Loot key value" (the contents' combined total).
	 * Per-item value / rarity don't apply. - Any other drop (NPC / raid chest /
	 * clue / pickpocket / PvP floor loot) posts its standout items — worth at
	 * least "Min drop value", OR rarer than the rarity threshold (NPC /
	 * pickpocket only, e.g. a cheap-but-rare unique) — bundled into a single
	 * post. The loot key item itself is skipped everywhere (its contents fire
	 * their own LootReceived on open). Runs on the client thread (loot fires
	 * there), so item-value and rarity lookups are safe; screenshots + network
	 * sends are deferred off-thread.
	 */
	private void maybeNotifyRareDrop(String source, Collection<ItemStack> items, String sourceKind) {
		if (!config.notifyRareDrops() || items == null || items.isEmpty()) {
			return;
		}
		if (!notifyEnabled("rareDrops")) {
			return;
		}
		long now = now();

		// ---- Loot keys: one post for the whole key, gated only by its total value. ----
		if (isLootKeyEvent(source)) {
			long total = 0;
			List<RareItem> contents = new ArrayList<>();
			for (ItemStack item : items) {
				int itemId = item.getId();
				if (isLootKey(itemName(itemId))) {
					continue;
				}
				int qty = Math.max(1, item.getQuantity());
				long itemValue = itemUnitValue(itemId) * qty;
				total += itemValue;
				contents.add(new RareItem(itemId, qty, itemValue, null));
			}
			int keyThreshold = Math.max(0, config.lootKeyMinValue());
			if (contents.isEmpty() || keyThreshold <= 0 || total < keyThreshold) {
				return;
			}
			if (!claim(lastAggregateNotifyAt, source == null ? "" : source, now, RARE_DEDUP_WINDOW_MS)) {
				return;
			}
			postRare(source, sourceKind, contents);
			return;
		}

		// ---- Regular drops: per-item value + rarity trigger. ----
		// Enforced floors so a member can't spam the clan channel: drops must be worth at least
		// 1m, and rarity posts must be rarer than 1/1000. 0 still means "disabled".
		int rawValue = config.rareDropMinValue();
		long valueThreshold = rawValue <= 0 ? 0 : Math.max(1_000_000, rawValue);
		int rarityThreshold = effectiveRarityFloor();
		AbstractRarityService rarity = raritySource(sourceKind);

		// Standout items get bundled into one post so a single kill never produces a surge.
		List<RareItem> qualifying = new ArrayList<>();

		for (ItemStack item : items) {
			int itemId = item.getId();
			String iname = itemName(itemId);
			if (isLootKey(iname)) {
				continue;
			}
			int qty = Math.max(1, item.getQuantity());
			long itemValue = itemUnitValue(itemId) * qty;

			// Prestige items always post, bypassing the value/rarity gates. Posted on their own so
			// an untradeable like an Infernal cape never shows a misleading "0 gp" alongside others.
			// An allowlist item NEVER also fires the value/rarity path — always continue, even when
			// its own dedup suppresses this fire. Otherwise a second loot event for the same kill
			// (NpcLootReceived + LootReceived) finds the allowlist already claimed, falls through,
			// and posts a duplicate "Rare drop" for a high-value allowlist item (e.g. a Blood shard).
			// Match by item ID (server-resolved) first — reliable for untradeables like a ToA Cursed phalanx
			// that have no value to gate on — then fall back to the name allowlist for back-compat.
			if (notableItemIds.contains(itemId) || isAlwaysNotifyItem(iname)) {
				if (claimAllowlistNotify(iname, now)) {
					postSpecialDrop(source, sourceKind, itemId, iname, qty, itemValue);
				}
				continue;
			}

			boolean valueQualifies = valueThreshold > 0 && itemValue >= valueThreshold;

			Double dropRate = null; // probability (1/N) when rare enough to report
			if (rarityThreshold > 0 && rarity != null && source != null && !source.isEmpty()) {
				OptionalDouble r = rarity.getRarity(source, itemId, qty);
				if (r.isPresent()) {
					double p = r.getAsDouble();
					if (p > 0 && MathUtils.lessThanOrEqual(p, 1.0 / rarityThreshold)) {
						dropRate = p;
					}
				}
			}

			if (!valueQualifies && dropRate == null) {
				continue;
			}

			// Per-item dedup also suppresses the duplicate fire when a kill and a follow-up loot
			// event both report the same item within the window.
			if (claim(lastRareNotifyAt, itemId, now, RARE_DEDUP_WINDOW_MS)) {
				qualifying.add(new RareItem(itemId, qty, itemValue, dropRate));
			}
		}

		postRare(source, sourceKind, qualifying);
	}

	/** One item posts on its own; several are bundled into one post, so a single kill never produces a surge. */
	private void postRare(String source, String sourceKind, List<RareItem> items) {
		if (items.size() == 1) {
			RareItem it = items.get(0);
			postRareDrop(source, sourceKind, it.itemId, it.qty, it.value, it.dropRate);
		} else if (items.size() > 1) {
			postCombinedRareDrop(source, sourceKind, items, items.stream().mapToLong(it -> it.value).sum());
		}
	}

	/**
	 * True when the item is on the always-notify allowlist (baked-in defaults +
	 * server list).
	 */
	private boolean isAlwaysNotifyItem(String name) {
		if (name == null || name.isEmpty()) {
			return false;
		}
		String n = name.toLowerCase();
		for (String pattern : text.alwaysNotify) {
			if (n.contains(pattern)) {
				return true;
			}
		}
		if (pluginConfig != null) {
			for (String pattern : alwaysNotifyLower) {
				if (n.contains(pattern)) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Reserves the right to post a prestige item, returning false if it was
	 * already posted within the dedup window. Keyed by name so the loot event
	 * and the collection-log unlock message can't both fire for the same item.
	 */
	private boolean claimAllowlistNotify(String name, long now) {
		return claim(lastAllowlistNotifyAt, name.toLowerCase(), now, RARE_DEDUP_WINDOW_MS);
	}

	/**
	 * Record {@code key} as seen at {@code now} — unless it was already seen within {@code windowMs},
	 * in which case this is the duplicate and nothing changes. True when this one counts.
	 */
	private static <K> boolean claim(Map<K, Long> seen, K key, long now, long windowMs) {
		synchronized (seen) {
			Long last = seen.get(key);
			if (last != null && now - last < windowMs) {
				return false;
			}
			seen.put(key, now);
			return true;
		}
	}

	/**
	 * Posts a notable collection-log unlock (a prestige item) when it lands via
	 * a loot event.
	 */
	private void postSpecialDrop(String source, String sourceKind, int itemId, String name, int qty, long value) {
		// value can be 0 for untradeables — the post then shows no value.
		postNotable(name, "loot", source, sourceKind, itemId, qty, value, killCountFor(source));
	}

	/**
	 * Posts a prestige item unlocked via the collection log — the reliable
	 * signal for awarded items (Infernal cape, Dizana's quiver, …) that don't
	 * fire a loot event. Only allowlisted items post; shared name-dedup with
	 * the loot path stops a double post.
	 */
	private void maybeNotifyCollectionUnlock(String itemName) {
		if (!config.notifyRareDrops() || itemName == null || itemName.isEmpty() || !isAlwaysNotifyItem(itemName)
				|| !notifyEnabled("rareDrops") || !claimAllowlistNotify(itemName, now())) {
			return;
		}
		// No source came with this line — the collection log says what, never from where — so only a
		// clan override that named no sources ("guaranteed wherever it drops") can answer the
		// guaranteed question. No item id either (the message gives only a name), so no value.
		postNotable(itemName, "unlock", null, null, -1, 1, 0, null);
	}

	/**
	 * A notable item's drop post.
	 *
	 * <p>Two kinds of drop the lucky-drop line insults rather than celebrates. An EARNED award
	 * (Infernal cape, Dizana's quiver…) is the reward for finishing the content, so calling a
	 * hard-won clear "spooned" reads as a jab. A GUARANTEED drop was never rolled for at all —
	 * the boss owed it — so "someone drier deserved that" reads as not knowing the game. Notable
	 * items reach this path with no drop rate at all, which is why the line used to be
	 * unconditional: nothing here could tell the difference until the server started saying.
	 */
	private void postNotable(String name, String via, String source, String sourceKind, int itemId, int qty,
			long value, Integer kc) {
		boolean earned = DropLuck.isEarnedAward(name);
		boolean guaranteed = DropSource.isGuaranteed(dropFacts(), name, source);
		postDrop(dropPost(source, sourceKind, kc).item(itemId, name, qty, value).put("notable", via)
				.flag("earned", earned).flag("guaranteed", guaranteed).flag("spoon", !earned && !guaranteed));
	}

	/**
	 * Posts a NEW collection-log slot to the clan achievements channel.
	 *
	 * The unlock line is already parsed here to credit bingo tiles; this turns the same signal into
	 * the post other notifiers have had for years. Deliberately separate from
	 * {@link #maybeNotifyCollectionUnlock}: that one is the prestige allowlist shouting at the drops
	 * channel, this is every other slot filling in quietly next to diaries and combat tasks. An
	 * allowlisted item is skipped here so the two never double-post the same unlock.
	 *
	 * Carries the log's own completion count ("548/1712 (32.0%)") when the client can answer for it,
	 * which it can't until the collection log has synced this session — the field is dropped in that
	 * case rather than guessed at.
	 */
	private void maybeNotifyClogSlot(String itemName) {
		if (!config.notifyClogSlots() || itemName == null || itemName.isEmpty()) {
			return;
		}
		// The prestige path already posted this one to the drops channel. And the unlock line can echo
		// on more than one chat channel; the shared name dedup keeps this to one post per item.
		if (!notifyEnabled("collectionLog") || isAlwaysNotifyItem(itemName)
				|| !claimAllowlistNotify(itemName, now())) {
			return;
		}

		// How much of the log this fills in (0 until the log has synced this session; the site then
		// leaves the count and rank out rather than guessing).
		NotifyFacts f = new NotifyFacts("clogSlot", getLocalPlayerName()).put("item", itemName)
				.put("itemId", resolveItemIdByName(itemName))
				.put("slots", ActivityStats.clogSlots(client::getVarpValue))
				.put("slotsMax", ActivityStats.clogSlotsMax(client::getVarpValue));
		// This item's own source first. The fallback still answers for an unlock with no loot event
		// behind it at all — a skilling pet, a quest reward — where "the last thing that dropped"
		// is the only signal there is.
		String source = sourceForLootedItem(itemName);
		if (source == null) {
			source = freshLootSource();
		}
		if (source != null) {
			// The kill count when it finally dropped. Absent when the source keeps none we can read.
			f.put("source", source).put("kc", killCountFor(source));
		}
		postWithScreenshot("collectionLog", f, "anvil-clog.png");
	}

	/**
	 * Item id for a name we only know as text (the collection-log line gives no id). Prefers ids seen
	 * in a recent loot event — that covers untradeables the GE search will never return — and falls
	 * back to an exact-name GE lookup. Null when neither knows it; the post simply loses its sprite.
	 */
	private Integer resolveItemIdByName(String name) {
		String key = name.toLowerCase(Locale.ROOT);
		long now = now();
		synchronized (recentLootIds) {
			recentLootIds.values().removeIf(e -> now - e.at > CLOG_LOOT_DEDUP_MS);
			RecentItem hit = recentLootIds.get(key);
			if (hit != null) {
				return hit.itemId;
			}
		}
		return findTradeableItemId(name);
	}

	/**
	 * What this specific item fell out of.
	 *
	 * THE BUG THIS FIXES. The source used to be "whatever loot event happened most recently", which
	 * is right for a drop announced the instant it lands and wrong for anything that arrives on its
	 * own schedule. A clue reward is the clean example: kill a Saradomin wizard, open the casket it
	 * eventually led to, and the collection-log line for Enchanted top was stamped `Saradomin
	 * wizard` — the thing the player last hit, not the thing the item came out of.
	 *
	 * The per-item memory was already being kept for the sprite lookup; it simply did not record
	 * where each item came from. Now it does, so the answer is about the item rather than the clock.
	 */
	private String sourceForLootedItem(String itemName) {
		if (itemName == null || itemName.isEmpty()) {
			return null;
		}
		long now = now();
		synchronized (recentLootIds) {
			recentLootIds.values().removeIf(e -> now - e.at > CLOG_LOOT_DEDUP_MS);
			return sourceOf(recentLootIds, itemName, now, CLOG_LOOT_DEDUP_MS);
		}
	}

	/** The lookup itself, free of plugin state so the attribution can be tested directly. */
	static String sourceOf(
			Map<String, RecentItem> seen, String itemName, long now, long windowMs) {
		if (itemName == null || itemName.isEmpty()) {
			return null;
		}
		RecentItem hit = seen.get(itemName.toLowerCase(Locale.ROOT));
		if (hit == null || now - hit.at > windowMs) {
			return null;
		}
		return hit.source != null && !hit.source.isEmpty() ? hit.source : null;
	}

	/**
	 * Remember the items (and where they came from) in a loot event, so a collection-log line landing
	 * moments later can name the source and draw the right sprite. Bounded by the same window the
	 * clog/loot dedup already uses; entries expire rather than accumulating.
	 */
	private void rememberLootForClog(String source, String sourceKind, Collection<ItemStack> items) {
		if (items == null || items.isEmpty()) {
			return;
		}
		long now = now();
		synchronized (recentLootIds) {
			recentLootIds.values().removeIf(e -> now - e.at > CLOG_LOOT_DEDUP_MS);
			for (ItemStack it : items) {
				if (it == null || it.getId() <= 0) {
					continue;
				}
				String name = itemName(it.getId());
				if (name != null && !name.isEmpty()) {
					recentLootIds.put(
							name.toLowerCase(Locale.ROOT),
							new RecentItem(it.getId(), now, source));
				}
			}
			if (source != null && !source.isEmpty()) {
				lastLootSource = source;
				lastLootSourceKind = sourceKind;
				lastLootSourceAt = now;
			}
		}
	}

	/** An item id seen in a recent loot event, with the time it landed and what it fell out of. */
	static final class RecentItem {

		final int itemId;
		final long at;
		/** The loot event this item was actually in — not merely the latest one. */
		final String source;

		RecentItem(int itemId, long at, String source) {
			this.itemId = itemId;
			this.at = at;
			this.source = source;
		}
	}

	/**
	 * True when this loot event is an opened loot key ("Loot Chest"), not a
	 * regular drop.
	 */
	private boolean isLootKeyEvent(String source) {
		if (source == null) {
			return false;
		}
		String s = source.toLowerCase();
		return s.equals("loot chest") || s.contains("loot key");
	}

	/**
	 * Rarity dataset for a loot source kind, or null when rarity doesn't apply
	 * (pvp / events).
	 */
	private AbstractRarityService raritySource(String sourceKind) {
		if ("npc".equals(sourceKind)) {
			return rarityService;
		}
		if ("pickpocket".equals(sourceKind)) {
			return thievingService;
		}
		return null;
	}

	/**
	 * True when the item (by name) is a loot key — its contents fire a separate
	 * LootReceived when opened.
	 */
	private static boolean isLootKey(String name) {
		return name != null && name.toLowerCase().contains("loot key");
	}

	/**
	 * Item display name, or "Item {id}" as a fallback. Safe on the client
	 * thread.
	 */
	private String itemName(int itemId) {
		try {
			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp != null && comp.getName() != null) {
				return comp.getName();
			}
		} catch (Exception ignored) {
		}
		return "Item " + itemId;
	}

	/**
	 * Move stale shipped defaults forward, once per install.
	 *
	 * v1: the rare-drop rarity floor went 1/5000 → 1/10000, because 1/5000 posts herb and seed
	 * rolls off an ordinary slayer task. Only rewrites a value still sitting on the OLD default —
	 * anyone who deliberately picked a number keeps it. A clan that wants a floor for everyone sets
	 * it on the site instead (see effectiveRarityFloor).
	 */
	private void migrateConfigDefaults() {
		try {
			Integer stored = configManager.getConfiguration("osrsbingo", CFG_DEFAULTS_VERSION, int.class);
			int version = stored == null ? 0 : stored;
			if (version >= CURRENT_DEFAULTS_VERSION) {
				return;
			}
			if (version < 1 && config.rareDropMinRarity() == LEGACY_RARITY_DEFAULT) {
				configManager.setConfiguration("osrsbingo", "rareDropMinRarity", 10_000);
				log.info("Raised rare-drop rarity floor to 1/10000 (was the old 1/5000 default)");
			}
			configManager.setConfiguration("osrsbingo", CFG_DEFAULTS_VERSION, CURRENT_DEFAULTS_VERSION);
		} catch (Exception e) {
			// A migration hiccup must never stop the plugin loading.
			log.debug("Config-defaults migration skipped: {}", e.getMessage());
		}
	}

	/**
	 * The rarity gate actually in force: rarer than 1-in-N, or 0 when rarity posts are off.
	 *
	 * Two inputs. The member's own setting is a preference; the clan's {@code dropRarityFloor} (from
	 * /api/plugin/config) is a floor the member can tighten but not loosen. That's what stops one
	 * person's 1/2000 setting from filling a shared channel with herb rolls, and it lets an admin
	 * fix the whole clan from the site instead of asking everyone to edit their config.
	 */
	private int effectiveRarityFloor() {
		int raw = config.rareDropMinRarity();
		if (raw <= 0) {
			return 0; // member disabled rarity posts entirely — the clan floor doesn't re-enable them
		}
		PluginConfigResponse cfg = pluginConfig;
		int clanFloor = cfg != null && cfg.dropRarityFloor > 0 ? cfg.dropRarityFloor : 0;
		return Math.max(Math.max(1000, raw), clanFloor);
	}

	/**
	 * The raid modes the game appends to a base name. A CLOSED SET, deliberately.
	 *
	 * The first attempt at this accepted any extra words after the base, on the reasoning that "a
	 * mode always adds words". It does — but so does a longer unrelated name once punctuation is
	 * stripped for matching: "Kree'Arra" normalises to "kree arra", so the apostrophe manufactures
	 * exactly the word boundary the check was leaning on, and "Kree" would have matched it. There
	 * are four of these in the game and they never change without a raid release, so naming them is
	 * both safer and more honest than a shape test.
	 */
	private static final Set<String> RAID_MODE_SUFFIXES = Collections.unmodifiableSet(
			new HashSet<>(Arrays.asList(
					"challenge mode", "entry mode", "expert mode", "hard mode")));

	/**
	 * Does a kill-count line for {@code kcName} describe a kill of {@code source}?
	 *
	 * True for the same activity, and for any MODE of it — "Tombs of Amascut" is credited by
	 * "Tombs of Amascut: Expert Mode", because RuneLite's loot event and the game's chat line are
	 * naming the same raid.
	 */
	static boolean kcLineBelongsTo(String source, String kcName) {
		if (source == null || kcName == null) {
			return false;
		}
		String want = normalizeBossName(source);
		String seen = normalizeBossName(kcName);
		if (want.isEmpty() || seen.isEmpty()) {
			return false;
		}
		if (seen.equals(want)) {
			return true;
		}
		if (!seen.startsWith(want + " ")) {
			return false;
		}
		return RAID_MODE_SUFFIXES.contains(seen.substring(want.length() + 1));
	}

	/**
	 * The server's drop knowledge, or null against a site that doesn't serve it. Read through a
	 * method rather than the field so every caller sees the same null-safety and the capability
	 * gate lives in one place.
	 */
	private DropFacts dropFacts() {
		PluginConfigResponse cfg = pluginConfig;
		return cfg != null && cfg.serverSupports("drop-facts") ? cfg.dropFacts : null;
	}

	/**
	 * The kill count to stamp on a drop from {@code source}.
	 *
	 * A RAID REPORTS ITS LOOT UNDER THE BASE NAME. RuneLite's loot event says "Tombs of Amascut"
	 * whichever mode you ran, while the game's kill-count line names the mode — "Your completed Tombs
	 * of Amascut: Expert Mode count is: 220". Those are different keys, so looking the base name up
	 * answered with whatever the NORMAL-mode count happened to be, and an Expert drop at 220 was
	 * posted to Discord as "KC 54". Same shape for CoX Challenge Mode and ToB Hard Mode.
	 *
	 * The kill line always precedes the loot, so a recent line naming this source — or any mode of it
	 * — is the one this drop belongs to. Outside that window nothing recent is claimed and the
	 * per-name map answers as before, which is what a drop with no kill line (a clue casket, an
	 * impling) still wants.
	 */
	private Integer killCountFor(String source) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg != null && !cfg.showKillCount) {
			return null;
		}
		if (source == null) {
			return null;
		}
		if (lastKcName != null
				&& now() - lastKcAtMs <= KC_ATTRIBUTION_WINDOW_MS
				&& kcLineBelongsTo(source, lastKcName)) {
			return lastKcValue;
		}
		return killCounts.get(source.toLowerCase());
	}

	private void postRareDrop(String source, String sourceKind, int itemId, int qty, long value, Double dropRate) {
		String name = itemName(itemId);
		Integer kc = killCountFor(source);
		boolean guaranteed = DropSource.isGuaranteed(dropFacts(), name, source);
		// A rare roll on something worthless is a punchline, not a prize — say so instead of
		// dressing a Dragon spear up as treasure. A guaranteed drop is neither.
		boolean troll = !guaranteed && DropLuck.isTrollDrop(dropRate, value, effectiveRarityFloor());
		NotifyFacts f = dropPost(source, sourceKind, kc).item(itemId, name, qty, value).put("dropRate", dropRate)
				.flag("guaranteed", guaranteed).flag("troll", troll)
				// The reaction line is about beating the odds. There were none to beat.
				.flag("spoon", !guaranteed && DropLuck.deservesSpoonLine(name, value, dropRate, kc, SPOON_VALUE));
		// Where this leaves their vestige rotation, when the drop was a roll of one (set moments
		// ago by trackVestigeRolls off the same loot event).
		String rollLine = lastVestigeLine;
		if (rollLine != null && now() - lastVestigeLineAt < VESTIGE_LINE_WINDOW_MS) {
			f.put("note", rollLine);
			lastVestigeLine = null;
		}
		postDrop(f);
	}

	/**
	 * One post for a whole drop / loot key that contained multiple items:
	 * highlights the single most valuable item, plus the combined total and
	 * item count — instead of a post per item or a huge per-item list.
	 */
	private void postCombinedRareDrop(String source, String sourceKind, List<RareItem> items, long total) {
		NotifyFacts f = dropPost(source, sourceKind, killCountFor(source));
		for (RareItem it : items) {
			f.item(it.itemId, itemName(it.itemId), it.qty, it.value);
		}
		// No single rate to judge a mixed haul by, so the combined value decides.
		postDrop(f.flag("spoon", total >= SPOON_VALUE));
	}

	/**
	 * A standout item collected for a combined rare-drop post.
	 */
	@RequiredArgsConstructor
	private static final class RareItem {

		final int itemId;
		final int qty;
		final long value;
		final Double dropRate;

	}

	/**
	 * A pet drop waiting on its name before it posts.
	 *
	 * <p>The chat line that announces a pet doesn't say WHICH pet — it's the same sentence for a
	 * Baby mole and a Tangleroot. The only line that names it is the collection-log unlock, which
	 * follows a tick or two later, so the post waits for it rather than going out as "a pet".
	 *
	 * <p>This assumes the pet line lands FIRST, which is the order the game sends them. If it ever
	 * arrived second the pet would post unnamed and the unlock would post separately — the same two
	 * posts this code replaces, so the failure mode is the old behaviour rather than a broken one.
	 */
	private static final class PendingPet {

		final boolean duplicate;
		/** When the pet line landed — the name is only looked for inside {@link #PET_NAME_WINDOW_MS}. */
		final long at = System.currentTimeMillis();
		/** Captured on the client thread when the pet line arrives. */
		final String rsn;
		final String source;
		final String sourceKind;
		final Integer killCount;
		/**
		 * Whether this pet will actually be POSTED. The wait for the name happens either way — the
		 * clan's site feed wants it too — so this is what tells the collection-log line whether
		 * standing down would leave the pet unannounced.
		 */
		final boolean announce;
		/** The queued feed entry waiting for the same name, if any. */
		final String momentKey;
		String name;
		/**
		 * Where it really came from, and the count there — resolvable only once the name is known
		 * (see DropSource.resolvePetSource). Null until then, and null afterwards for a pet nothing
		 * can place, which is what makes the post fall back to {@link #source}.
		 */
		String resolvedSource;
		Integer resolvedKc;
		/** Resolved on the client thread with the collection-log name. */
		Integer itemId;
		Double dropRate;

		PendingPet(boolean duplicate, String rsn, String source, String sourceKind, Integer killCount,
				   boolean announce, String momentKey) {
			this.duplicate = duplicate;
			this.rsn = rsn;
			this.source = source;
			this.sourceKind = sourceKind;
			this.killCount = killCount;
			this.announce = announce;
			this.momentKey = momentKey;
		}
	}

	private final Object petLock = new Object();
	private PendingPet pendingPet;
	/**
	 * How long the pet post waits for its collection-log line. Long enough to cover the unlock
	 * landing a tick or two later, short enough that the post still reads as immediate — and short
	 * enough that it can't swallow an unrelated unlock from the next kill.
	 *
	 * <p>Six seconds, not two: with the player's own collection-log line switched off, the clan's copy is
	 * the one that names it, and it can land a few ticks after the pet line — after a two-second wait
	 * the pet had already posted as just "pet" and the name went out as a separate unlock.
	 */
	private static final long PET_NAME_WINDOW_MS = 6_000;
	/** How long a named pet still claims a line repeating its name (see claimPetName). */
	private static final long PET_RECLAIM_MS = 60_000;
	private PendingPet lastNamedPet;

	// ---- Naming a pet with no chat line to say which ------------------------------------------
	// The game also shows WHICH pet the moment it lands: a new follower ("being followed"), or a new
	// pet item in the pack ("sneaking into your backpack"). What was there BEFORE the line is noted, so
	// a pet already out or already in the bag is never taken for the new one. With a pet out AND a full
	// pack the new one goes to Probita instead — nothing appears, and the name has to come from a line.
	private int petFollowerBefore = -1;
	private Set<Integer> petPackBefore = Collections.emptySet();

	/** Client thread, at the pet line. */
	private void notePetSurroundings() {
		NPC follower = client.getFollower();
		petFollowerBefore = follower == null ? -1 : follower.getIndex();
		Set<Integer> pack = new HashSet<>();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv != null) {
			for (Item it : inv.getItems()) {
				if (it != null && it.getId() > 0) {
					pack.add(it.getId());
				}
			}
		}
		petPackBefore = pack;
	}

	/** Client thread, each tick while a pet waits unnamed: name it off a new follower or a new pet item. */
	private void namePetFromSurroundings() {
		PendingPet pet;
		synchronized (petLock) {
			pet = pendingPet;
		}
		if (pet == null || pet.name != null || System.currentTimeMillis() - pet.at > PET_NAME_WINDOW_MS) {
			return;
		}
		NPC follower = client.getFollower();
		if (follower != null && follower.getIndex() != petFollowerBefore && follower.getName() != null) {
			log.debug("Pet named off its new follower: {}", follower.getName());
			claimPetName(follower.getName());
			return;
		}
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv == null) {
			return;
		}
		for (Item it : inv.getItems()) {
			if (it == null || it.getId() <= 0 || petPackBefore.contains(it.getId())) {
				continue;
			}
			String name = itemManager.getItemComposition(it.getId()).getName();
			// The pack takes all sorts mid-fight; only a name the pet catalogue knows is the pet.
			if (name != null && DropSource.petEntry(dropFacts(), name) != null) {
				log.debug("Pet named off its new pack item: {}", name);
				claimPetName(name);
				return;
			}
		}
	}

	/**
	 * Claim a collection-log unlock as the name of the pet we just noticed.
	 *
	 * <p>Returns the pet when this line was its name — which tells the caller two different things
	 * it must not confuse: the unlock is already accounted for (so it is not ALSO a drop), and, if
	 * that pet is going to be posted, the ordinary collection-log posts should stand down or the
	 * same pet lands twice, once as 🐾 and once as 📕. A member who only wanted the site feed still
	 * gets their normal clog post, because for them nothing else is going to mention it.
	 */
	private PendingPet claimPetName(String itemName) {
		if (itemName == null || itemName.isEmpty()) {
			return null;
		}
		PendingPet pet;
		synchronized (petLock) {
			// Already named — by the clan's broadcast, a follower, or the other copy of the log line —
			// or posted a moment ago: a later line naming the SAME pet is that pet, not a new unlock
			// to post again (the "Pet drop!" + separate "Dom" pair this used to produce).
			PendingPet named = pendingPet != null && pendingPet.name != null ? pendingPet : lastNamedPet;
			if (named != null && itemName.equalsIgnoreCase(named.name)
					&& System.currentTimeMillis() - named.at <= PET_RECLAIM_MS) {
				return named;
			}
			if (pendingPet == null || pendingPet.name != null) {
				return null;
			}
			pendingPet.name = itemName;
			pet = pendingPet;
			lastNamedPet = pet;
		}
		// Naming it is also what makes its SOURCE knowable: until now the only candidate was the
		// last loot the client saw. Resolve once, here, so the clan feed and the Discord post can
		// never disagree about which boss it came from.
		String resolved = DropSource.resolvePetSource(dropFacts(), itemName, pet.source, killCounts);
		synchronized (petLock) {
			pet.resolvedSource = resolved;
			pet.resolvedKc = resolved == null ? null
					: (resolved.equalsIgnoreCase(pet.source) ? pet.killCount : killCountFor(resolved));
			// ItemManager and the rarity services ultimately read game/cache state. Resolve those
			// here, on the chat-event client thread, rather than two seconds later on our executor.
			pet.itemId = resolveItemIdByName(itemName);
			pet.dropRate = petRarity(pet.itemId, resolved, pet.sourceKind);
		}
		namePetMoment(pet.momentKey, itemName, resolved, pet.resolvedKc);
		return pet;
	}

	/**
	 * Note a pet drop. The source and kill count are captured NOW — by the time anything is sent the
	 * player may have moved on, and "from Callisto at 1,204 KC" is the whole story of the drop.
	 *
	 * <p>The clan's feed is recorded unconditionally; only the Discord post is gated. They are
	 * different things: switching off the drops channel is a statement about a channel, not about
	 * whether the pet happened.
	 */
	private void handlePetDrop(boolean duplicate) {
		String source;
		String sourceKind;
		synchronized (recentLootIds) {
			boolean fresh = lastLootSource != null
					&& now() - lastLootSourceAt <= CLOG_LOOT_DEDUP_MS;
			source = fresh ? lastLootSource : null;
			sourceKind = fresh ? lastLootSourceKind : null;
		}
		Integer kc = killCountFor(source);
		String momentKey = recordPetMoment(source, sourceKind, kc);
		// The server is the authority on whether a clan or personal destination exists. The cached
		// notify flag can be stale (or only describe clan hooks while the player has a personal
		// hook), and a pet is far too rare to discard because that snapshot said "none". Keep the
		// player's own switch, then let /api/plugin/notify make the live routing decision.
		boolean announce = petAnnouncementEnabled(config.notifyPets(), apiClient.isConfigured(), pluginConfig);

		// Nothing is waiting on the name — no post to make and no feed entry to fill in — so don't
		// park a pet nothing will ever collect: the next collection-log line would claim it.
		if (!announce && momentKey == null) {
			return;
		}
		PendingPet pet = new PendingPet(duplicate, getLocalPlayerName(), source, sourceKind, kc,
				announce, momentKey);
		notePetSurroundings();
		synchronized (petLock) {
			pendingPet = pet;
		}
		Runnable flush = () -> safely("petNotification", () -> flushPetNotification(pet));
		if (later(flush, PET_NAME_WINDOW_MS) == null) {
			flush.run();
		}
	}

	/**
	 * Whether to attempt the rare pet post. The site, not its last config snapshot, owns the live
	 * destination decision; this gate only answers whether the player asked and the endpoint exists.
	 */
	static boolean petAnnouncementEnabled(boolean playerEnabled, boolean apiConfigured,
										  PluginConfigResponse cfg) {
		return playerEnabled && apiConfigured && cfg != null && cfg.serverSupports("notify");
	}

	/**
	 * Post the pet, with whatever the wait turned up.
	 *
	 * <p>Every field here is omitted rather than guessed when it isn't known: a skilling pet fires no
	 * loot event, so it has no source, no KC and no drop rate, and inventing any of those for a clan
	 * channel would be worse than a shorter post.
	 */
	private void flushPetNotification(PendingPet pet) {
		synchronized (petLock) {
			if (pendingPet == pet) {
				pendingPet = null;
			}
		}
		// The wait may have been for the site feed alone (drops channel off) — the name has been
		// filled in by now either way, and there is nothing here to post.
		if (!pet.announce) {
			return;
		}
		// Where it ACTUALLY came from, settled in claimPetName the moment the name arrived (the feed
		// took the same answer). A pet that never got named, or one nothing can place, falls back to
		// the observed loot source — which is all this ever had.
		String petName = pet.name;
		NotifyFacts f = new NotifyFacts("pet", pet.rsn).put("name", petName).flag("duplicate", pet.duplicate);
		synchronized (petLock) {
			f.put("source", petName == null ? pet.source : pet.resolvedSource)
					.put("kc", petName == null ? pet.killCount : pet.resolvedKc);
		}
		if (petName != null) {
			// Real rarity or none: asked of the same service the rare-drop posts price against.
			f.put("itemId", pet.itemId).put("dropRate", pet.dropRate);
			// A skilling pet has no monster; its skill is the only true thing to say about where from.
			DropFacts.Pet entry = DropSource.petEntry(dropFacts(), petName);
			if (entry != null) {
				f.put("skill", entry.skill);
			}
		}
		postWithScreenshot("pets", f, "anvil-pet.png");
	}

	/** This pet's drop rate from the rarity table its source uses, or null when nothing can price it. */
	private Double petRarity(Integer itemId, String source, String sourceKind) {
		if (itemId == null || itemId <= 0 || source == null || source.isEmpty()) {
			return null;
		}
		// The resolved source may be a monster the client never saw loot from, in which case there
		// is no observed KIND either — but a pet the server files under a killable monster is by
		// definition an npc drop, so the npc table is the right one to ask.
		AbstractRarityService service = raritySource(sourceKind == null ? "npc" : sourceKind);
		if (service == null) {
			return null;
		}
		OptionalDouble r = service.getRarity(source, itemId, 1);
		return r.isPresent() && r.getAsDouble() > 0 ? r.getAsDouble() : null;
	}

	/**
	 * Handles a parsed combat-task completion (run a tick after the chat line
	 * so the CA points varbit has settled). Posts the individual task if it
	 * clears the configured min tier, and a separate tier-clear post when this
	 * task pushed total points across a tier threshold.
	 */
	private void handleCombatAchievements(List<PendingCaTask> batch) {
		// Off in the dropdown silences every CA post, tier clears too; tile credit happened upstream.
		CaAnnounceTier floor = config.caMinTaskTier();
		boolean announce = floor != CaAnnounceTier.OFF && notifyEnabled("combatAchievements");

		int total = client.getVarbitValue(VarbitID.CA_POINTS);
		// Points before this batch — only used to detect a tier-threshold crossing. With no baseline
		// yet, fall back to the current total so we never post a phantom tier clear.
		int before = caPointsInitialized ? lastCaPoints : total;

		// Tier clear: did the cumulative total cross any tier threshold across this batch?
		CombatAchievementTier cleared = null;
		for (CombatAchievementTier t : CombatAchievementTier.values()) {
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && before < threshold && threshold <= total) {
				cleared = t; // values() ascend, so the last match is the highest tier crossed
			}
		}
		if (cleared != null && announce) {
			postCaTierClear(cleared);
		}

		// Individual tasks: post each FIRST-seen task at/above the configured floor, but only when
		// this tick's completions actually raised the CA point total. Already-owned tasks re-fire the
		// same chat line via the in-game "Repeat completion" setting — which we rely on so CA *tiles*
		// can count tasks cleared before the event — without changing points, so gating on the delta
		// keeps those recompletions out of the achievements channel. (A mixed tick containing both a
		// genuine new task and a recompletion still posts the recompletion; the aggregate varbit can't
		// attribute a per-task delta. That's rare — real spam is pure-recompletion ticks.) Dedup by
		// task NAME so every genuinely new task in a multi-task tick still posts exactly once.
		boolean pointsRose = total > before;
		for (PendingCaTask pending : batch) {
			String key = pending.task == null ? "" : pending.task.toLowerCase();
			if (key.isEmpty() || !notifiedCaTasks.add(key)) {
				continue; // unparseable, or already announced this session
			}
			if (!pointsRose) {
				continue; // a recompletion: it changed nothing, so it is not news
			}
			// The feed and the counter take every genuinely new task and let the SITE decide which
			// are worth showing — a tier floor belongs where the clan can change it without a
			// plugin release. The chat announcement keeps its own local floor.
			noteCombatTaskMoment(pending.tier, pending.task);
			if (announce && floor.posts(pending.tier)) {
				postCombatTask(pending.tier, pending.task, total);
			}
		}

		lastCaPoints = total;
	}

	/**
	 * Posts one completed combat task with what it was worth, the running total, and the next tier
	 * unlock threshold — read from the same varbits the tier-clear check uses.
	 *
	 * Client thread (varbit reads happen here); the screenshot + send are deferred.
	 */
	private void postCombatTask(CombatAchievementTier tier, String task, int totalPoints) {
		// The next unlock is the lowest cumulative threshold still above the total; 0 once all are.
		int next = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values()) {
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > totalPoints && (next == 0 || threshold < next)) {
				next = threshold;
			}
		}
		postWithScreenshot("combatAchievements", new NotifyFacts("caTask", getLocalPlayerName()).put("task", task)
				.put("tier", tier.getDisplayName()).put("totalPoints", totalPoints).put("nextThreshold", next),
				"anvil-ca.png");
	}

	private void postCaTierClear(CombatAchievementTier tier) {
		// Message-only — no screenshot.
		apiClient.postNotification("combatAchievements", null,
				new NotifyFacts("caTier", getLocalPlayerName()).put("tier", tier.getDisplayName()), null, null);
	}

	/**
	 * Posts an achievement-diary tier completion to the clan achievements
	 * channel with a screenshot of the moment, like a combat task.
	 */
	private void maybeNotifyDiaryCompletion(String area, String tier) {
		if (!config.notifyDiaries() || !notifyEnabled("diaries")) {
			return;
		}
		postWithScreenshot("diaries", new NotifyFacts("diary", getLocalPlayerName()).put("area", area)
				.put("tier", tier), "anvil-diary.png");
	}

	/** One "&lt;Area&gt; &lt;Tier&gt;" selector against a completion; "Any" is a wildcard on either side. */
	private static boolean diarySelectorMatches(String sel, String areaLower, String tierLower) {
		if (sel == null) {
			return false;
		}
		String s = sel.trim();
		int cut = s.lastIndexOf(' ');
		if (cut <= 0) {
			return false;
		}
		String selArea = s.substring(0, cut).trim().toLowerCase();
		String selTier = s.substring(cut + 1).trim().toLowerCase();
		return (selArea.equals("any") || areaLower.equals(selArea) || areaLower.contains(selArea))
				&& (selTier.equals("any") || tierLower.equals(selTier));
	}

	/**
	 * Credits diary bingo tiles whose selector list matches this completion.
	 * Selectors are "&lt;Area&gt; &lt;Tier&gt;" with "Any" as a wildcard on
	 * either side ("Any Elite", "Wilderness Any"); area matching is
	 * contains-based so "Lumbridge Any" matches the "Lumbridge &amp; Draynor"
	 * area. One completion == amount 1 through the shared proof pipeline
	 * (banner + screenshot + retry store).
	 */
	private void creditDiaryTiles(String area, String tier) {
		if (trackingOff() || pluginConfig.trackedDiaries == null) {
			return;
		}
		String areaLower = area.toLowerCase();
		String tierLower = tier.toLowerCase();
		for (TrackedDiary d : pluginConfig.trackedDiaries) {
			if (d == null || d.diaries == null || d.currentAmount >= d.requiredAmount) {
				continue;
			}
			if (d.diaries.stream().noneMatch(sel -> diarySelectorMatches(sel, areaLower, tierLower))) {
				continue;
			}
			d.currentAmount += 1;
			raiseLocal(d.tileId, d.currentAmount, now());
			log.debug("Tracked diary completion: {} {} → tile '{}' ({}/{})",
					area, tier, d.label, d.currentAmount, d.requiredAmount);
			captureAndSubmitProof(d.tileId, d.label, 1, null,
					"DIARY COMPLETE", area + " " + tier + " Diary",
					"[Auto] " + area + " " + tier + " diary completed — detected by RuneLite plugin",
					() -> d.currentAmount = Math.max(0, d.currentAmount - 1));
		}
	}

	/**
	 * Credits Combat Achievement bingo tiles whose selector list matches this completion.
	 * Selectors are exact task names ("Whack-a-Mole") or "Any &lt;Tier&gt;" wildcards
	 * ("Any Master"), matched case-insensitively. One completion == amount 1 through the
	 * shared proof pipeline (banner + screenshot + retry store). A given task credits a
	 * given tile at most once per session (creditedCaTaskTiles), so re-meeting the same
	 * task's conditions repeatedly can't farm a multi-count wildcard tile.
	 */
	private void creditCombatTaskTiles(CombatAchievementTier tier, String task) {
		if (trackingOff() || pluginConfig.trackedCombatTasks == null) {
			return;
		}
		String taskLower = task.toLowerCase();
		String anyTier = "any " + tier.getDisplayName().toLowerCase();
		for (TrackedCombatTask t : pluginConfig.trackedCombatTasks) {
			if (t == null || t.tasks == null || t.currentAmount >= t.requiredAmount) {
				continue;
			}
			final String dedupKey = t.tileId + "|" + taskLower;
			if (t.tasks.stream().noneMatch(sel -> sel != null
					&& (sel.trim().toLowerCase().equals(taskLower) || sel.trim().toLowerCase().equals(anyTier)))) {
				continue;
			}
			if (!creditedCaTaskTiles.add(dedupKey)) {
				log.debug("Combat task '{}' already credited '{}' this session", task, t.label);
				continue;
			}
			t.currentAmount += 1;
			raiseLocal(t.tileId, t.currentAmount, now());
			log.debug("Tracked combat task: {} '{}' → tile '{}' ({}/{})",
					tier.getDisplayName(), task, t.label, t.currentAmount, t.requiredAmount);
			captureAndSubmitProof(t.tileId, t.label, 1, null,
					"COMBAT TASK", tier.getDisplayName() + ": " + task,
					"[Auto] " + tier.getDisplayName() + " combat task \"" + task + "\" completed — detected by RuneLite plugin",
					() -> {
						t.currentAmount = Math.max(0, t.currentAmount - 1);
						// Un-remember the pair so a failed capture can credit on a later re-fire.
						creditedCaTaskTiles.remove(dedupKey);
					});
		}
	}

	/**
	 * Does this board have tiles that can only credit off the in-game drop-notification line?
	 *
	 * <p>Drop and value tiles both do, for the corpse-looted bosses whose loot bypasses every loot
	 * event the client raises (see {@link #creditDropFromChat}). The rest of the board does not care,
	 * but the plugin cannot tell in advance which boss a tile's drop will come from, and the cost of
	 * asking is one chat line against a silent 50m fang.</p>
	 */
	static boolean eventNeedsDropLines(PluginConfigResponse cfg) {
		if (cfg == null || !AnvilOverlay.isEventActive(cfg.event)) {
			return false;
		}
		return (cfg.trackedDrops != null && !cfg.trackedDrops.isEmpty())
				|| (cfg.trackedValues != null && !cfg.trackedValues.isEmpty());
	}

	/** On the client thread, and only while logged in — the nudges read settings varbits. */
	private void whenLoggedIn(Runnable r) {
		clientThread.invokeLater(() -> {
			if (loggedIn()) {
				r.run();
			}
		});
	}

	/**
	 * One-time (per session) reminder to enable the in-game "Repeat completion" Combat
	 * Achievement setting when the active event has incomplete CA tiles — without it, tasks
	 * the player already owns never re-fire the completion line, so those tiles can never
	 * track for them. Reads the setting's varbit, so the check runs on the client thread.
	 */
	private void maybeNudgeCaRepeatSetting() {
		if (caRepeatNudgeSent || pluginConfig == null || pluginConfig.trackedCombatTasks == null
				|| pluginConfig.trackedCombatTasks.isEmpty() || !AnvilOverlay.isEventActive(pluginConfig.event)) {
			return;
		}
		boolean anyIncomplete = false;
		for (TrackedCombatTask t : pluginConfig.trackedCombatTasks) {
			if (t != null && t.currentAmount < t.requiredAmount) {
				anyIncomplete = true;
				break;
			}
		}
		if (!anyIncomplete) {
			return;
		}
		whenLoggedIn(() -> {
			if (client.getVarbitValue(VarbitID.CA_TASK_RECOMPLETION_NOTIFICATIONS) == 1) {
				return; // setting already on — nothing to remind about
			}
			caRepeatNudgeSent = true;
			sendChatMessage("This event has Combat Achievement tiles — enable Settings > Combat Achievements"
					+ " > \"Repeat completion\" so tasks you've already done can still count.");
		});
	}

	/**
	 * The in-game collection-log notification, which is what prints the line the plugin reads.
	 *
	 * <p>With it off, an unlock is invisible here: no achievements post, no tile credit, no
	 * kill-count stamp. The clan broadcast covers it for anyone in a clan that announces slots —
	 * that is the fallback in {@link #handleClogUnlock} — but a solo player, or a clan that doesn't
	 * broadcast them, has nothing at all. Worth one line per account, since the cost of not saying
	 * it is a log that silently never fills in.</p>
	 *
	 * <p>Only when the setting is OFF outright. The option has more than two values and the others
	 * are not worth guessing at: a nudge that fires for a correctly-configured client is the kind
	 * that teaches people to ignore the next one.</p>
	 */
	private void maybeNudgeClogNotifications() {
		if (clogNotifyNudgeSent || !config.notifyClogSlots() || !notifyEnabled("collectionLog")) {
			return;
		}
		whenLoggedIn(() -> {
			if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 0) {
				return;
			}
			clogNotifyNudgeSent = true;
			sendChatMessage("Your collection log notifications are off in game (Settings > All settings > Chat"
					+ " > \"Collection log - New addition notification\") — new slots won't post to the clan"
					+ " unless your clan broadcasts them.");
		});
	}

	/**
	 * One-time (per session) reminder to enable the in-game loot drop notifications when clan
	 * rare-drop posts are on. The "&lt;player&gt; received a drop: …" chat line those posts key
	 * off for corpse-boss spill loot (Maggot King uniques — see creditDropFromChat) is Jagex's
	 * opt-in loot notification: with the setting off, or its value threshold above the drop's
	 * price, the line never prints and the plugin has nothing to parse — a 50m fang can pass
	 * completely silently. Varbit read requires the client thread.
	 */
	private void maybeNudgeLootNotifications() {
		if (lootNotifyNudgeSent) {
			return;
		}
		// TWO REASONS TO CARE, and only one of them used to be asked about. Clan rare-drop posts
		// need the line, and so does a BOARD with drop or value tiles on it: the same corpse-boss
		// loot that never posts also never credits (creditDropFromChat is what feeds both). Gating
		// the reminder on the clan-post toggle meant a member who had turned posts off — or whose
		// clan doesn't run them — played a bingo whose spill-loot tiles could not fire, and was
		// never told why.
		boolean forPosts = config.notifyRareDrops() && notifyEnabled("rareDrops");
		boolean forTiles = eventNeedsDropLines(pluginConfig);
		if (!forPosts && !forTiles) {
			return;
		}
		whenLoggedIn(() -> {
			boolean settingOn = client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_ON) == 1;
			// The plugin's own posting floor (enforced minimum 1m) — an in-game threshold above
			// it would swallow lines for drops the clan channel wants to see.
			long plugFloor = Math.max(1_000_000, Math.max(0, config.rareDropMinValue()));
			long gameThreshold = client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_VALUE);
			// The threshold half is a CLAN-POST concern only: it is measured against the posting
			// floor, and there is no equivalent number for a tile — a tile wants whatever the drop
			// happens to be worth. So a board-driven reminder ends at "the setting is off".
			if (settingOn && (!forPosts || gameThreshold <= plugFloor)) {
				return; // configured fine — the attribution line will fire for qualifying drops
			}
			lootNotifyNudgeSent = true;
			if (!settingOn) {
				sendChatMessage(forTiles
						? "Enable Settings > Chat > \"Loot drop notifications\" — this board has drop tiles, and"
						+ " bosses that spill their loot (Maggot King, Araxxor) only announce it on that line."
						: "Enable Settings > Chat > \"Loot drop notifications\" — clan rare-drop posts for corpse-boss"
						+ " loot (Maggot King uniques) rely on that chat line.");
			} else {
				sendChatMessage("Your in-game loot notification threshold is above the clan rare-drop floor — lower it"
						+ " (Settings > Chat > Loot drop notifications) or drops like Maggot King uniques won't post.");
			}
		});
	}

	/**
	 * Reads the quest-completed scroll and posts the completion, gated by the
	 * configured difficulty threshold (default Master &amp; up). Runs a tick
	 * after the widget loads so the text child is populated; retries a couple
	 * of ticks if the text lands late.
	 */
	private void scheduleQuestScrollRead(int attemptsLeft) {
		clientThread.invokeLater(() -> {
			Widget text = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
			String raw = text != null ? text.getText() : null;
			if (raw == null || raw.isEmpty()) {
				if (attemptsLeft > 0) {
					scheduleQuestScrollRead(attemptsLeft - 1);
				}
				return;
			}
			// A widget, so the angle-bracket form is what appears here — but it costs nothing to
			// take the @ codes too, and the quest scroll is styled by the same game.
			String plain = CHAT_TAG.matcher(raw).replaceAll(" ").replaceAll("\\s+", " ").trim();
			String quest = parseQuestScroll(plain);
			if (quest == null || quest.contains("partial completion")) {
				return; // unparseable, or Hazeel Cult's "kind of completed" — not a completion
			}
			if (!announcedQuests.add(quest.toLowerCase())) {
				return; // widget re-loaded for a quest already posted this session
			}
			postQuestCompletion(quest);
		});
	}

	/**
	 * Parses the quest-completed scroll text into the quest name. Ported from
	 * RuneLite's ScreenshotPlugin (BSD-2) so all the scroll's text variants
	 * resolve correctly — RFD subquests become "Recipe for Disaster - X",
	 * "completely completed Rag and Bone Man" becomes "Rag and Bone Man II",
	 * and names genuinely containing "Quest" (Legends' Quest, Doric's Quest)
	 * keep the word. Returns null when nothing matches. Package-private for
	 * the unit test.
	 */
	static String parseQuestScroll(String text) {
		Matcher m1 = QUEST_PATTERN_1.matcher(text);
		Matcher m2 = QUEST_PATTERN_2.matcher(text);
		Matcher m = m1.matches() ? m1 : m2;
		if (!m.matches()) {
			return null;
		}
		String quest = m.group("quest");
		String verb = m.group("verb") != null ? m.group("verb") : "";
		if (verb.contains("kind of")) {
			quest += " partial completion";
		} else if (verb.contains("completely")) {
			quest += " II";
		}
		final String questAndVerb = quest + verb;
		if (RFD_TAGS.stream().anyMatch(questAndVerb::contains)) {
			quest = "Recipe for Disaster - " + quest;
		}
		final String questName = quest;
		if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(questName::contains)) {
			quest += " Quest";
		}
		return quest;
	}

	/**
	 * Posts a quest completion to the clan achievements channel when its difficulty (questTiers in
	 * anvil_text.json) clears the setting; an unlisted quest only posts on "All". Message-only.
	 */
	private void postQuestCompletion(String questName) {
		QuestAnnounceTier setting = config.questAnnounce();
		String difficulty = text.questTiers.get(questName.toLowerCase());
		if (!setting.posts(difficulty) || !notifyEnabled("quests")) {
			return;
		}
		// Message-only, like a tier clear. Difficulty goes as its display form ("Experienced").
		apiClient.postNotification("quests", null, new NotifyFacts("quest", getLocalPlayerName())
				.put("quest", questName).put("difficulty", difficulty == null ? null
						: difficulty.charAt(0) + difficulty.substring(1).toLowerCase()), null, null);
	}

	/**
	 * True when the current world's stats aren't the player's real main-game progression, so level-up
	 * and total-level milestones must be suppressed. PvP Arena hands out a preset max-stat account;
	 * Leagues (SEASONAL) / Deadman / Tournament / Beta / Fresh Start / Quest Speedrunning / LMS / no-save
	 * worlds are separate saves or preset loadouts. Hopping onto one otherwise spams "level 99!" for
	 * stats the player never trained.
	 */
	private boolean statsAreArtificial() {
		Set<WorldType> w = client.getWorldType();
		return w != null && !Collections.disjoint(w, ARTIFICIAL_WORLDS);
	}

	private static final Set<WorldType> ARTIFICIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.SEASONAL,
			WorldType.DEADMAN, WorldType.TOURNAMENT_WORLD, WorldType.BETA_WORLD, WorldType.FRESH_START_WORLD,
			WorldType.QUEST_SPEEDRUNNING, WorldType.LAST_MAN_STANDING, WorldType.NOSAVE_MODE);

	/** Which level-ups the clan and the player's own webhooks want; the clan's dropped without a channel. */
	private LevelRules.Sets levelRules() {
		return LevelRules.resolve(pluginConfig, notifyEnabled("levels"));
	}

	private void handleLevelMilestone(String skill, int prev, int level) {
		// A 99 happens once per skill per account, so when one does not reach Discord there has to be
		// something in the log saying which step dropped it. postNotification's own failure paths are
		// log.debug — invisible at RuneLite's default level.
		if (skill == null) {
			return;
		}
		if (statsAreArtificial()) {
			if (level >= 99 && prev < 99) {
				log.info("99 {} not announced — not real progression on this world", skill);
			}
			return;
		}
		int at = LevelRules.skillMilestone(prev, level, levelRules());
		if (at == 0) {
			if (level >= 99 && prev < 99) {
				log.info("99 {} not announced — no destination for level posts", skill);
			}
			return;
		}
		// Post a given skill's level once per session — the same level can arrive from StatChanged
		// and the level-up chat line, and levels already held at login are pre-seeded.
		String key = skill.toLowerCase();
		if (at <= announcedLevel.getOrDefault(key, 0)) {
			return;
		}
		announcedLevel.put(key, at);
		log.info("Announcing {} {}.", skill, at);
		// How far along they are. A level post is about skills rather than total, so it counts those —
		// and a build not chasing max still gets it, because "12 of 23 skills at 99" is a fact about
		// what they have done rather than a distance from somebody else's goal.
		// Skill.OVERALL is a null tombstone, never in values().
		int at99 = 0;
		int of = Skill.values().length;
		for (Skill sk : Skill.values()) {
			at99 += client.getRealSkillLevel(sk) >= 99 ? 1 : 0;
		}
		// An older site knows only 99s (all its fixed rules can match) under the old kind.
		boolean rules = pluginConfig != null && pluginConfig.serverSupports("level-rules");
		postAchievement(new NotifyFacts(rules ? "level" : "level99", getLocalPlayerName()).put("skill", skill)
				.put("level", rules ? (Integer) at : null).put("at99", at99).put("skills", of));
	}

	/**
	 * Called on every skill level-up. Announces the highest round total this gain crossed that the
	 * level rules want, or maxing. Uses the baselined total so we only fire on genuine crossings,
	 * and skips the round post when this gain maxed.
	 */
	private void handleTotalMilestone() {
		// NOT gated on the Discord channel here. The gate moved down to the post itself, because this
		// method also advances lastTotalLevel and feeds the clan's highlight feed — returning early
		// for want of a webhook froze the baseline and lost the milestone from both.
		if (statsAreArtificial() || statsUnsettled) {
			return;
		}
		int total = client.getTotalLevel();
		if (!totalLevelInitialized) {
			// Login baseline missed (e.g. levelled before the first tick settled) — seed and skip.
			lastTotalLevel = total;
			totalLevelInitialized = true;
			return;
		}
		if (total <= lastTotalLevel) {
			return;
		}
		int prev = lastTotalLevel;
		lastTotalLevel = total;

		LevelRules.Sets rules = levelRules();
		int max = maxTotalLevel();
		if (prev < max && max <= total) {
			recordLevelMoment(null, total, "max");
			if (LevelRules.wantsMax(rules)) {
				postTotalMilestone(total, true);
			}
			return; // maxing is the headline — don't also post the round total it passed
		}
		// The highlight feed keeps the fixed 1800, 1900, … whatever the Discord rules say.
		int feed = LevelRules.totalMilestone(prev, total, new LevelRules.Sets(LevelRules.LEGACY_CLAN, null));
		if (feed > 0) {
			recordLevelMoment(null, feed, "total");
		}
		int milestone = LevelRules.totalMilestone(prev, total, rules);
		if (milestone > 0) {
			postTotalMilestone(milestone, false);
		}
	}

	/**
	 * Maximum possible total level, summed from the live Skill enum (adapts as
	 * skills are added).
	 */
	private int maxTotalLevel() {
		return 99 * Skill.values().length;
	}

	/**
	 * Is this account plainly not chasing 2277?
	 *
	 * THERE IS NO "PURE" ACCOUNT TYPE. RuneLite's AccountType knows Normal and the Ironman variants
	 * and nothing else, because a pure is a BUILD rather than a flag — the game does not record the
	 * intention, only the stats it produced. So this asks the one question the stats answer without
	 * ambiguity: Defence 1. Nobody arrives at 99 Strength with Defence 1 by accident, and a level-3
	 * skiller is the same answer for the same reason.
	 *
	 * It is used only to SUPPRESS a line, never to claim anything. Telling somebody who has chosen a
	 * build that they are "435 levels from max" measures them against a goal they rejected, and the
	 * cost of guessing wrong is a missing line rather than a wrong one.
	 */
	private boolean buildIsNotChasingMax() {
		return client.getRealSkillLevel(Skill.DEFENCE) == 1;
	}


	private void postTotalMilestone(int total, boolean maxed) {
		NotifyFacts f = new NotifyFacts("totalLevel", getLocalPlayerName()).put("total", total).flag("maxed", maxed)
				.put("milestone", maxed ? null : (Integer) total);
		// Where this leaves them — from the LIVE total, not the milestone above: somebody who crossed
		// 1800 on a level that took them to 1803 is 474 from max, not 477. Left out on a build not
		// chasing max (the site also drops it on a max, where "0 to go" is noise).
		if (!maxed && !buildIsNotChasingMax()) {
			f.put("current", client.getTotalLevel()).put("max", maxTotalLevel());
		}
		postAchievement(f);
	}

	/** A drop's facts, before its items. */
	private NotifyFacts dropPost(String source, String sourceKind, Integer kc) {
		return new NotifyFacts("drop", getLocalPlayerName()).put("source", source).put("sourceKind", sourceKind)
				.put("kc", kc);
	}

	/** A drop post to the drops channel, with its screenshot. */
	private void postDrop(NotifyFacts f) {
		postWithScreenshot("rareDrops", f, DROP_SHOT);
	}

	/**
	 * Higher of GE price and high-alch value for a single item. Safe to call on
	 * the client thread.
	 */
	private long itemUnitValue(int itemId) {
		long ge = 0;
		long ha = 0;
		try {
			ge = Math.max(0, itemManager.getItemPrice(itemId));
		} catch (Exception ignored) {
		}
		try {
			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp != null) {
				ha = Math.max(0, comp.getHaPrice());
			}
		} catch (Exception ignored) {
		}
		return Math.max(ge, ha);
	}

	/**
	 * Builds the death message: a 1/100 chance of a random fun line
	 * (server-served pool, with a baked-in fallback), otherwise the player's
	 * own configured message. {name} → RSN.
	 */
	private String buildDeathMessage(String rsn) {
		String name = (rsn == null || rsn.isEmpty()) ? "Someone" : rsn;
		String base;
		boolean fun = ThreadLocalRandom.current().nextInt(100) == 0;
		if (fun) {
			List<String> pool = text.funDeaths;
			PluginConfigResponse cfg = pluginConfig;
			if (cfg != null && cfg.funDeathMessages != null && !cfg.funDeathMessages.isEmpty()) {
				pool = cfg.funDeathMessages;
			}
			base = pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
		} else {
			base = config.deathMessage();
			if (base == null || base.isEmpty()) {
				base = "{name} just died!";
			}
		}
		base = base.replace("{name}", name);
		// Funny lines are always on — a cheeky reaction line on every death.
		base += "\n" + randomDeathTaunt();
		return base;
	}

	private static String randomLine(List<String> pool) {
		return pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
	}

	/**
	 * A death reaction line — the server pool when the clan has set one, else
	 * the baked-in list.
	 */
	private String randomDeathTaunt() {
		PluginConfigResponse cfg = pluginConfig;
		List<String> pool = (cfg != null && cfg.deathTaunts != null && !cfg.deathTaunts.isEmpty())
				? cfg.deathTaunts : text.deathTaunts;
		return randomLine(pool);
	}


	/**
	 * Whether the clan has somewhere to put this kind of post.
	 *
	 * <p>Five kinds -- pets, levels, quests, diaries, collection-log slots -- used to be announced
	 * under the name of the channel they shared. Each has its own name now, and a site that predates
	 * that split sends no flag for it; a boxed null there means "ask the channel it came from"
	 * rather than "off", so an older site keeps posting 99s exactly where it always did.</p>
	 *
	 * <p>Unknown names return false. The old default arm answered {@code rareDrops} for anything it
	 * didn't recognise, which would have quietly routed every new channel through the drop flag.</p>
	 */
	private boolean notifyEnabled(String channel) {
		PluginConfigResponse cfg = pluginConfig;
		if (cfg == null || cfg.notify == null) {
			return false;
		}
		return channelEnabled(cfg.notify, channel);
	}

	/** The resolution itself, free of plugin state so the inheritance can be tested directly. */
	static boolean channelEnabled(NotifyChannels n, String channel) {
		if (n == null) {
			return false;
		}
		switch (channel) {
			case "rareDrops":
				return n.rareDrops;
			case "deaths":
				return n.deaths;
			case "combatAchievements":
				return n.combatAchievements;
			case "pvpKills":
				return n.pvpKills;
			case "pets":
				return n.pets != null ? n.pets : n.rareDrops;
			case "levels":
				return n.levels != null ? n.levels : n.combatAchievements;
			case "quests":
				return n.quests != null ? n.quests : n.combatAchievements;
			case "diaries":
				return n.diaries != null ? n.diaries : n.combatAchievements;
			case "collectionLog":
				return n.collectionLog != null ? n.collectionLog : n.combatAchievements;
			default:
				return false;
		}
	}

	// A stalled capture must not stall the notification: frames normally arrive within ~50ms,
	// so a few seconds of grace is already generous before posting without the screenshot.
	private static final long FRAME_CAPTURE_TIMEOUT_MS = 4000;

	/**
	 * Captures the next rendered frame and hands the PNG bytes to
	 * {@code consumer} OFF the client thread. The frame listener fires on the
	 * client/AWT thread, so we immediately defer encoding to the executor; the
	 * consumer then sends via OkHttp async. The game loop never waits on
	 * either.
	 *
	 * <p>The consumer is guaranteed to run exactly once — with {@code null} when no frame
	 * arrives in time (a minimized client can stop rendering, and the next-frame listener
	 * then never fires) or the PNG encode fails. Callers post without the screenshot in
	 * that case; before this guarantee, a stalled capture silently dropped the whole
	 * notification (a Maggot King fang post vanished this way).
	 */
	private void captureFrameAsync(Consumer<byte[]> consumer) {
		AtomicBoolean delivered = new AtomicBoolean(false);
		onNextFrame(image -> {
			byte[] png = null;
			try {
				png = png(image);
			} catch (Exception e) {
				log.debug("Frame capture failed: {}", e.getMessage());
			}
			if (delivered.compareAndSet(false, true)) {
				consumer.accept(png);
			}
		}, null);
		later(() -> {
			if (delivered.compareAndSet(false, true)) {
				log.info("No frame within {}ms — notifying without a screenshot", FRAME_CAPTURE_TIMEOUT_MS);
				consumer.accept(null);
			}
		}, FRAME_CAPTURE_TIMEOUT_MS);
	}

	/**
	 * The next rendered frame, handed to {@code work} on the executor. The frame listener fires on
	 * the client/AWT thread, so encoding and sending never hold up the game loop. {@code dead} runs
	 * instead when the executor has gone away in the meantime.
	 */
	/**
	 * The next frame drawn with our overlays hidden (they skip drawing while {@link #capturing}). Asked
	 * for from the client thread, between frames: from the executor the request could land mid-draw and
	 * return a frame our overlays were already painted into. The flag is cleared however the request
	 * ends, so a plugin stopped in between can't leave every overlay hidden.
	 */
	private void onCleanFrame(Consumer<BufferedImage> work) {
		clientThread.invokeLater(() -> {
			capturing = true;
			drawManager.requestNextFrameListener(image -> {
				capturing = false;
				if (!execLive()) {
					return;
				}
				try {
					executor.submit(() -> work.accept((BufferedImage) image));
				} catch (RejectedExecutionException e) {
					log.debug("Proof frame dropped: plugin stopping");
				}
			});
		});
	}

	private void onNextFrame(Consumer<BufferedImage> work, Runnable dead) {
		drawManager.requestNextFrameListener(image -> {
			if (!execLive()) {
				if (dead != null) {
					dead.run();
				}
				return;
			}
			executor.submit(() -> work.accept((BufferedImage) image));
		});
	}

	private static byte[] png(BufferedImage img) throws IOException {
		ByteArrayOutputStream baos = new ByteArrayOutputStream();
		ImageIO.write(img, "png", baos);
		return baos.toByteArray();
	}

	private static BufferedImage copyFrame(BufferedImage src) {
		BufferedImage copy = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = copy.createGraphics();
		g.drawImage(src, 0, 0, null);
		g.dispose();
		return copy;
	}

	/** Copy the shared frame — never mutate the draw manager's buffer — burn the proof banner on, encode. */
	private byte[] bakeCopy(BufferedImage src, String title, String detail, String rsn) throws IOException {
		BufferedImage copy = copyFrame(src);
		annotateProofBanner(copy, title, detail, rsn);
		return png(copy);
	}

	/** Post a 99 / total-level milestone with a screenshot, a beat after the moment. */
	private void postAchievement(NotifyFacts f) {
		Runnable capture = () -> postWithScreenshot("levels", f, "anvil-achievement.png");

		// Let the room react before the shutter.
		//
		// The instant a 99 lands the screen holds the fireworks and nothing else; the congratulations
		// that make the screenshot worth keeping are still being typed. A beat's pause catches the
		// clan chat with the moment instead of an empty chatbox beneath it.
		//
		// Scheduled, never slept: a sleep here would park a shared RuneLite worker for a second and a
		// half, and the hub rejects Thread.sleep on sight. Without a usable executor -- shutting down
		// mid-level-up -- we capture now, because a slightly emptier screenshot beats none.
		if (later(capture, ACHIEVEMENT_SHOT_DELAY_MS) == null) {
			capture.run();
		}
	}

	/** Pause between the achievement and its screenshot, long enough for clanmates' replies. */
	private static final long ACHIEVEMENT_SHOT_DELAY_MS = 1500;

	/**
	 * Capture, then post to {@code channel}; a failed capture posts without the image (the site only
	 * references a screenshot that was actually attached).
	 */
	private void postWithScreenshot(String channel, NotifyFacts f, String shotName) {
		captureFrameAsync(png -> apiClient.postNotification(channel, null, f, png, shotName));
	}

	// Gold prefix flags the line as Anvil; white body stays readable on any background (OSRS text
	// has a built-in shadow). Both are the player's to change (Chat messages in the config).
	private static String hexOf(Color c, String fallback) {
		return c == null ? fallback : String.format("%06x", c.getRGB() & 0xFFFFFF);
	}

	private void sendChatMessage(String message) {
		if (message == null || message.isEmpty()) {
			return;
		}
		// A raw '|' in a chat line gets mangled by the chat pipeline (an event named
		// "The AFK Spot | July Bingo" printed as a bare "July Bingo."). Interpolated names are
		// admin-authored, so swap in the visually-identical broken bar instead.
		String safe = message.replace('|', '\u00A6');
		String line = "<col=" + hexOf(config.chatPrefixColor(), "ffd700") + ">[Anvil]</col> <col="
				+ hexOf(config.chatTextColor(), "ffffff") + ">" + safe + "</col>";
		clientThread.invokeLater(() -> {
			// addChatMessage posts to every plugin's ChatMessage subscriber. During startup/logout
			// RuneLite has neither a local player nor its varbit array yet, and a surprising number
			// of third-party subscribers assume both exist. Never inject an Anvil line into that
			// half-initialised state: doing so can cascade into unrelated plugin exceptions and an
			// injected-client crash.
			if (!loggedIn() || client.getLocalPlayer() == null) {
				log.debug("Chat message skipped — client not ready");
				return;
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", line, null);
		});
	}

	// -- Profile sync: collection log + personal bests ---------------------------------------
	// Both are the player's OWN data going to the player's OWN clan site -- the pattern the hub
	// accepts (nothing here reads or reports anybody else). Everything is opt-out in config, and
	// nothing is read at all while the toggles are off.

	/**
	 * The sidebar's "Sync clan roster" button.
	 *
	 * <p>Same work as the in-game one, with its own in-flight guard so a double click is one push,
	 * and the result reported in chat where the player is looking. Refused outright when the clan
	 * channel isn't readable — the roster is scraped from it, so there is nothing to send.
	 */
	public void syncClanRosterFromPanel() {
		if (!isAdmin) {
			sendChatMessage("Only clan admins can sync the roster.");
			return;
		}
		// Cached, because this is called from the side panel on the EDT — reading the clan channel
		// from there is the same thread violation that swallowed the profile button's message.
		if (!clanRosterReadable) {
			sendChatMessage("Join your clan channel first — the roster is read from it.");
			return;
		}
		if (panelRosterSyncRunning) {
			sendChatMessage("Already syncing the roster.");
			return;
		}
		panelRosterSyncRunning = true;
		sendChatMessage("Syncing the clan roster...");
		syncClanRoster((ok, msg) -> {
			panelRosterSyncRunning = false;
			repaintSidebar(); // the callback lands on the executor or client thread, never the EDT
		});
	}

	/**
	 * Whether the clan site can store profile data at all — drives the in-tab "Sync profile" row.
	 *
	 * <p>Gated on the capability rather than discovered by 404ing: a site that predates these
	 * endpoints would otherwise be asked every 30 seconds, forever, by every member of the clan.
	 * Sites advertise it once they have somewhere to put it; until then the plugin does no reading,
	 * no batching and no requests.
	 */
	public boolean supportsProfileSync() {
		return config.syncClog() && apiClient.isConfigured() && serverSupportsCap("profile-sync");
	}

	// Whether the collection log is on screen, as last seen on a tick. The panel's "Sync profile" can
	// only work then (requestFullClogTransmit reads the log's own widgets); offered anywhere else it
	// was a button whose only answer was "open your collection log".
	private volatile boolean clogOpen;

	/** "Sync profile" in the side panel: supported, and the log is open to read from. */
	public boolean canSyncProfileFromPanel() {
		return clogOpen && supportsProfileSync();
	}

	private void trackClogOpen() {
		boolean open = client.getWidget(InterfaceID.Collection.FRAME) != null;
		if (open != clogOpen) {
			clogOpen = open;
			redrawSidebarLocal();
		}
	}

	/**
	 * Tell the site about a collection-log unlock as it happens, with the kill that produced it.
	 *
	 * <p>Otherwise the site only learns of the slot at the next log sync, and stamps it with THAT
	 * moment: Moxi taken on the 16th Amoxliatl and synced at 39 read "at 39 KC", dated whenever the
	 * log was next opened. The kill line is sent as-is and the site keeps it only when it belongs to
	 * the item's page. One request per unlock, which is once per slot per account, ever.
	 */
	private void sendClogUnlock(String item) {
		if (!supportsProfileSync() || !serverSupportsCap("clog-live-unlock")) {
			return;
		}
		// Read on the client thread, where the kill line was recorded.
		boolean recentKill = lastKcName != null && now() - lastKcAtMs <= KC_ATTRIBUTION_WINDOW_MS;
		String kcName = recentKill ? lastKcName : null;
		Integer kc = recentKill ? lastKcValue : null;
		ScheduledExecutorService ex = executor;
		if (ex == null) {
			return;
		}
		ex.submit(() -> {
			try {
				apiClient.submitClogUnlock(item, kcName, kc);
			} catch (Exception e) {
				// Not retried: the next log sync still records the slot, just without the live KC.
				log.debug("Collection log unlock push failed: {}", e.getMessage());
			}
		});
	}

	/**
	 * In no clan the config is a 404 and carries no capabilities; /api/version answers instead — the
	 * log and bests are the person's, so a solo player syncs them like anyone else.
	 */
	private boolean serverSupportsCap(String capability) {
		PluginConfigResponse cfg = pluginConfig;
		return cfg != null ? cfg.serverSupports(capability)
				: apiClient.signedInWithoutClan() && apiClient.siteAdvertises(capability);
	}


	/**
	 * Point the profile-sync state at the account that just logged in.
	 *
	 * <p>State is per-RSN, so switching characters swaps it rather than merging two logs. A no-op
	 * when the same account logs back in, which is the common case.
	 */
	private void loadProfileSyncState(String rsn) {
		String key = rsn == null ? "" : rsn.trim().toLowerCase(Locale.ROOT);
		if (key.isEmpty() || key.equals(profileSyncRsn)) {
			return;
		}
		profileSyncRsn = key;
		clogSync.reset();
		personalBests.reset();
		// A different character doesn't inherit this one's unsent highlights — the site files them
		// against whoever the request authenticates as, which would now be the wrong person.
		moments.reset();
		clogSync.restoreState(cfgGet(accountKey(CFG_CLOG_STATE, key)));
		// The whole-log fingerprint survives a restart: opening the collection log re-transmits
		// everything every time, and without this each session's first open re-sent a log the site
		// already had, byte for byte.
		lastClogFingerprint = cfgLong(accountKey(CFG_CLOG_FINGERPRINT, key));
		personalBests.restoreState(cfgGet(accountKey(CFG_PB_STATE, key)));
		importRuneLitePersonalBests(key);
	}

	/**
	 * Copy the personal bests RuneLite's own chat-commands plugin has already recorded, once.
	 *
	 * <p>Local config only -- the same store the player's own client wrote, on the same machine, for
	 * the account they're logged into. Nothing is read about anyone else. Without it a profile
	 * starts empty and fills in over months; with it, a player who has been playing for years sees
	 * their real times the first time they open their clan profile.
	 *
	 * <p>Runs once per account per activity list (a flag in our own config), and does nothing when
	 * chat-commands has never run -- then the live capture builds the set from the next kill onward.
	 * The flag stores a signature of the names we asked for, so when the site adds an activity --
	 * the awakened DT2 bosses, say -- everyone re-probes once for the new names. Re-running is safe:
	 * a seeded time only ever replaces a slower one.
	 */
	private void importRuneLitePersonalBests(String rsnKey) {
		if (!config.importRuneLitePbs() || !config.syncPersonalBests()) {
			return;
		}
		if (configManager.getRSProfileKey() == null || configManager.getRSProfileKey().isEmpty()) {
			return; // No RS profile yet -- try again next login rather than marking it done.
		}
		// The names to ask for. Without them there is nothing to probe, so we leave the flag unset
		// and try again once the site's config has landed.
		PluginConfigResponse cfg = pluginConfig;
		List<String> activities = cfg != null ? cfg.pbActivities : null;
		if (activities == null || activities.isEmpty()) {
			return;
		}
		// String.hashCode is specified, so the same list gives the same signature on every client
		// and every release. An older flag ("1", or an earlier list) simply doesn't match.
		String signature = Integer.toString(activities.hashCode());
		String done = cfgGet(accountKey(CFG_PB_IMPORTED, rsnKey));
		if (signature.equals(done)) {
			return;
		}

		// ASK, don't list. RuneLite stores these under the RS-profile scope, and its only key-listing
		// API reads the main profile — so the obvious loop over getConfigurationKeys() silently found
		// nothing at all, whatever prefix it was given. getRSProfileConfiguration reads the right
		// store, one key at a time, which is why the names have to come from somewhere.
		Map<String, Integer> imported = new HashMap<>();
		for (String base : activities) {
			if (base == null || base.isEmpty()) {
				continue;
			}
			probeRuneLitePb(base, imported);
			// Every scale RuneLite files a raid under. Its own pattern is
			// "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)", so a solo run is the WORD solo — not
			// "1 players" — and a big team is a bucket rather than an exact count. Probing only
			// "N players" therefore missed every solo raid time anyone had.
			probeRuneLitePb(base + " solo", imported);
			for (int size = 1; size <= MAX_PB_TEAM_SIZE; size++) {
				probeRuneLitePb(base + " " + size + " players", imported);
			}
			for (String bucket : PB_TEAM_BUCKETS) {
				probeRuneLitePb(base + " " + bucket, imported);
			}
		}

		int adopted = personalBests.seed(imported, now());
		cfgSet(accountKey(CFG_PB_IMPORTED, rsnKey), signature);
		log.info("Imported {} existing personal best(s) from RuneLite ({} probed)",
				adopted, imported.size());
		if (adopted > 0) {
			sendChatMessage("Imported " + adopted + " personal best" + (adopted == 1 ? "" : "s")
					+ " from RuneLite.");
		}
	}

	/**
	 * Try the personal-best import again on the periodic tick.
	 *
	 * <p>It needs three things that don't arrive together: an account (login), an RS profile key
	 * (login), and the site's activity list (the first config fetch). Running it only at login meant
	 * the config usually hadn't landed yet and the import quietly did nothing. The once-per-account
	 * flag makes every call after a successful one free.
	 */
	private void retryPersonalBestImport() {
		String rsn = profileSyncRsn;
		if (rsn != null && !rsn.isEmpty()) {
			importRuneLitePersonalBests(rsn);
		}
	}

	/** Read one stored best, if RuneLite has it for this account. Times are seconds; ours centis. */
	private void probeRuneLitePb(String activity, Map<String, Integer> into) {
		String raw = configManager.getRSProfileConfiguration(RUNELITE_PB_GROUP, activity);
		if (raw == null || raw.trim().isEmpty()) {
			return;
		}
		try {
			int centis = (int) Math.round(Double.parseDouble(raw.trim()) * 100.0);
			if (centis > 0) {
				into.put(activity, centis);
			}
		} catch (NumberFormatException e) {
			// Not a time -- skip the key rather than the import.
		}
	}

	/**
	 * The send contract the profile-sync pushes share: the result on success (backoff cleared), else
	 * null after the matching handler ran — rate-limited (gets the wait in ms), refused for good
	 * (drop the batch) or failed (backoff bumped, batch kept); the last two get the error message.
	 */
	private <T> T pushBatch(String what, SyncBackoff backoff, long now, Callable<T> send,
			LongConsumer limited, Consumer<String> refused, Consumer<String> failed) {
		try {
			T result = send.call();
			backoff.onSuccess();
			return result;
		} catch (RateLimitedException e) {
			log.debug("{} rate-limited for {}ms", what, e.retryAfterMs);
			limited.accept(e.retryAfterMs);
		} catch (PermanentSubmissionException e) {
			log.info("{} refused, dropping it: {}", what, e.getMessage());
			refused.accept(e.getMessage());
		} catch (Exception e) {
			backoff.onFailure(now);
			log.debug("{} push failed, retrying in {}s: {}", what, backoff.secondsUntilReady(now), e.getMessage());
			failed.accept(e.getMessage());
		}
		return null;
	}

	/**
	 * Send any collection-log pages that have changed. Runs on the shared executor's 30s tick --
	 * no thread of our own, and nothing on the client thread.
	 */
	private void flushClogSync() {
		if (profileSyncRsn == null || !supportsProfileSync()) {
			return;
		}
		long now = now();
		if (!clogSync.isDue(now) || !clogBackoff.ready(now)) {
			return;
		}
		List<ClogPage> batch = clogSync.nextBatch();
		// Rate-limited: background sync, nothing to tell the player, just wait as long as the site asked.
		// Refused outright (a malformed page, a site that doesn't take these): dropping the batch is the
		// only way out of an otherwise permanent 30-second retry loop.
		if (pushBatch("Collection log pages", clogBackoff, now, () -> {
			apiClient.submitClogPages(batch, clogSync.syncedPages());
			return batch;
		}, ms -> clogPushAllowedAt = now() + Math.max(ms, 1_000L), m -> clogSync.onSent(batch), m -> {
		}) == null) {
			return;
		}
		clogSync.onSent(batch);
		cfgSet(accountKey(CFG_CLOG_STATE, profileSyncRsn),
				clogSync.serializeState());
	}

	/**
	 * Push a settled whole-log transmit (see {@link ClogFullSync}). Runs on the same 30s tick as the
	 * page sync; the two are complementary — this carries every obtained item, the page route carries
	 * the kill-count lines that only appear on a drawn page.
	 */
	private void flushFullClogSync() {
		if (profileSyncRsn == null || !supportsProfileSync()) {
			return;
		}
		long now = now();
		if (!clogFullSync.isDue(now) || !clogFullBackoff.ready(now)) {
			return;
		}
		// The site's own rate limit, respected before the request rather than discovered by it.
		if (now < clogPushAllowedAt) {
			return;
		}
		boolean manual = clogFullSync.isManual();
		int count = clogFullSync.size();
		// Opening the log re-transmits everything, and most opens change nothing. Pushing an
		// identical log would burn the server's cooldown and rewrite 1,700 rows to say the same
		// thing. A deliberate press still goes, so "sync now" always means something happened.
		long fingerprint = clogFullSync.fingerprint();
		if (!manual && fingerprint == lastClogFingerprint) {
			log.debug("Collection log unchanged — nothing to push");
			clogFullSync.onSent();
			// Nothing to send. Said once a login — proof the sync ran and agreed with the site —
			// and then not again: the log is re-transmitted on every open, and a line each time
			// saying nothing happened is worse than saying nothing at all.
			if (!autoClogReportedThisLogin) {
				autoClogReportedThisLogin = true;
				sendChatMessage("Collection log checked — your profile is up to date.");
			}
			return;
		}
		// Rate-limited: it said when. Wait exactly that long instead of doubling blindly, and keep the
		// batch. Refused: the site will keep saying no — most often because it predates whole-log pushes
		// and wants pages instead — so retrying forever is just noise on their server. Failed: kept for
		// the next attempt; a site that's down mustn't cost them the transmit.
		ClogPushResult result = pushBatch("Whole-log", clogFullBackoff, now,
				() -> apiClient.submitClogItems(clogFullSync.snapshot()), ms -> {
					clogPushAllowedAt = now + Math.max(ms, 1_000L);
					clogFullSync.onSendFailed(now);
					if (manual) {
						sendChatMessage("Synced very recently — the site allows one sync a minute. Try again in "
								+ secs(ms) + "s.");
					}
				}, m -> {
					clogFullSync.onSent();
					if (manual) {
						sendChatMessage("Couldn't sync your profile: " + m + ".");
					}
				}, m -> {
					clogFullSync.onSendFailed(now);
					if (manual) {
						sendChatMessage("Couldn't sync your profile: " + m + ". It'll retry on its own.");
					}
				});
		manualSyncStartedAt = 0; // landed or given up on — nothing for the watchdog to complain about
		if (result == null) {
			return;
		}
		clogPushAllowedAt = now + SERVER_CLOG_COOLDOWN_MS;
		lastClogFingerprint = fingerprint;
		if (profileSyncRsn != null) {
			cfgSet(accountKey(CFG_CLOG_FINGERPRINT, profileSyncRsn),
					Long.toString(fingerprint));
		}
		clogFullSync.onSent();
		log.info("Collection log synced: {} items", count);
		if (manual) {
			sendChatMessage("Profile synced — " + count + " collection log slots.");
		} else if (result.added > 0) {
			// New slots are news: always said.
			autoClogReportedThisLogin = true;
			sendChatMessage("Collection log synced — " + result.added + " new slot"
					+ (result.added == 1 ? "" : "s") + ".");
		} else if (!autoClogReportedThisLogin) {
			// A push that added nothing still proves the round trip worked — once a login.
			autoClogReportedThisLogin = true;
			sendChatMessage("Collection log synced — nothing new.");
		}
	}

	/** Same contract for best times. */
	private void flushPersonalBests() {
		if (!config.syncPersonalBests() || !apiClient.isConfigured() || profileSyncRsn == null
				|| !serverSupportsCap("profile-sync")) {
			return;
		}
		long now = now();
		if (!personalBests.isDue(now) || !pbBackoff.ready(now)) {
			return;
		}
		Map<String, Integer> batch = personalBests.nextBatch();
		// Bests ride the same limiter; a rate-limited batch stays dirty and goes up when it clears.
		if (pushBatch("Personal bests", pbBackoff, now, () -> {
			apiClient.submitPersonalBests(batch);
			return batch;
		}, ms -> pbBackoff.onFailure(now()), m -> personalBests.onSent(batch), m -> {
		}) == null) {
			return;
		}
		personalBests.onSent(batch);
		cfgSet(accountKey(CFG_PB_STATE, profileSyncRsn),
				personalBests.serializeState());
	}

	/**
	 * The clan channel loaded (or changed) — the moment the in-game roster becomes readable.
	 *
	 * <p>Rosters used to drift until an admin remembered to press "Sync clan roster": someone joins,
	 * the site doesn't know, and their drops land as a guest. The data is right here at login, so
	 * take it. Admin-only (the site refuses anyone else's push anyway), at most once every half hour
	 * per session, and silent — an automatic sync that announced itself in chat every login would be
	 * worse than the drift.
	 */
	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event) {
		if (!event.isGuest() && config.autoSyncClanRoster()) {
			// The member list arrives just after the channel; a delay is cheaper than polling for it.
			later(() -> safely("autoRosterSync", this::autoSyncClanRoster), AUTO_ROSTER_DELAY_MS);
		}
	}

	/**
	 * Push the in-game roster if we're allowed to and haven't recently. Every guard here is a reason
	 * NOT to send: not an admin, no token, roster not loaded yet, one already running, or one ran
	 * within the last half hour.
	 */
	private void autoSyncClanRoster() {
		if (autoRosterSyncRunning || !isAdmin) {
			return;
		}
		String token = config.playerToken();
		if (token == null || token.isEmpty() || !apiClient.isConfigured()) {
			return;
		}
		long now = now();
		if (lastAutoRosterSyncAt != 0 && now - lastAutoRosterSyncAt < AUTO_ROSTER_MIN_GAP_MS) {
			return;
		}
		autoRosterSyncRunning = true;
		lastAutoRosterSyncAt = now;
		autoRosterAnnounce = true;
		syncClanRoster((ok, msg) -> {
			autoRosterSyncRunning = false;
			if (ok) {
				log.debug("Clan roster auto-synced: {}", msg);
			} else {
				// Most likely "roster not loaded yet" — let the next channel change try again.
				lastAutoRosterSyncAt = 0;
				log.debug("Clan roster auto-sync skipped: {}", msg);
			}
		});
	}
}

package com.anvil;

import java.util.*;
import java.util.function.Supplier;
import lombok.RequiredArgsConstructor;
import java.util.function.Consumer;

/**
 * What the side panel reads from the plugin itself: the polled config (the clan picker, capabilities),
 * the logged-in character, pins, the starting shot, syncs and banner sounds. What it shows of the
 * clan and its boards is the site's (UiView); this is only what the client alone can know or do.
 */
public class AnvilSidebarDataSource
{
	private final Supplier<PluginConfigResponse> configSupplier;

	private final BingoApiClient apiClient;

	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient)
	{
		this.configSupplier = configSupplier;
		this.apiClient = apiClient;
	}

	/**
	 * The starting-shot action, bound by the plugin after construction (Guice builds this source
	 * before the plugin's own fields exist, so it can't be a constructor argument). Null in tests and
	 * anywhere the panel is driven without a live plugin — the sidebar then simply shows no button.
	 */
	private volatile Runnable startProofCapture;

	/** Bind the capture action. Idempotent; passing null unbinds. */
	public void setStartProofCapture(Runnable capture)
	{
		this.startProofCapture = capture;
	}

	/** The plugin behind the panel's buttons, bound after construction like the capture above. */
	private volatile AnvilPlugin plugin;

	public void setPlugin(AnvilPlugin plugin)
	{
		this.plugin = plugin;
	}

	/** Run {@code f} on the bound plugin; a no-op when none is bound (tests, a panel driven by hand). */
	private void withPlugin(Consumer<AnvilPlugin> f)
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			f.accept(p);
		}
	}

	/** {@code f} of the bound plugin, or {@code none} when there isn't one. */
	private <T> T fromPlugin(java.util.function.Function<AnvilPlugin, T> f, T none)
	{
		AnvilPlugin p = plugin;
		return p == null ? none : f.apply(p);
	}

	/** Actions available for the clan on screen. Never null. */
	public PanelActions actionsFor()
	{
		AnvilPlugin p = plugin;
		if (p == null)
		{
			return PanelActions.NONE;
		}
		boolean profile = p.canSyncProfileFromPanel();
		if (!p.isAdmin())
		{
			return new PanelActions(false, profile, null);
		}
		// Admin — but the roster comes from the clan channel, so it has to be readable. The CACHED
		// answer: this runs while the panel paints, on the EDT, where asking the client directly is a
		// thread violation.
		boolean scrape = p.isClanRosterReadable();
		return new PanelActions(scrape, profile, scrape ? null : "Join your clan channel to sync the roster");
	}

	/** The logged-in character's row, or {@code null} to hide it (logged out, not signed in). */
	public AccountRow accountRow()
	{
		return fromPlugin(AnvilPlugin::accountRow, null);
	}

	/** Run a row action; {@code done} gets a one-line outcome, off the EDT. */
	public void accountAction(AccountRow.Action action, Consumer<String> done)
	{
		withPlugin(p -> p.accountAction(action, done));
	}

	/** Push the in-game clan roster to the home site. */
	public void syncRoster()
	{
		withPlugin(AnvilPlugin::syncClanRosterFromPanel);
	}

	/** Send this account's collection log + bests to the home site. */
	public void syncProfile()
	{
		withPlugin(AnvilPlugin::syncProfileNow);
	}

	/** Is this clip in the play cycle? */
	public boolean bannerSoundOn(String clip)
	{
		return fromPlugin(p -> p.bannerSoundSelected(clip), false);
	}

	/** Flip one clip in or out of the cycle. */
	public void toggleBannerSound(String clip)
	{
		withPlugin(p -> p.toggleBannerSound(clip));
	}

	/** Copy the sounds folder's path — hub releases may not open a file manager (see Clipboards). */
	public void copyBannerSoundsPath()
	{
		withPlugin(AnvilPlugin::copyBannerSoundsPath);
	}

	/** Import a .wav into {@code kind}'s clips folder. */
	public void importSounds(BannerSoundService.Kind kind)
	{
		withPlugin(p -> p.importSounds(kind));
	}

	/** {@code kind}'s clips; for missions, the folder that decides between a clip and the built-in chime. */
	public List<String> sounds(BannerSoundService.Kind kind)
	{
		return fromPlugin(p -> p.soundClips(kind), Collections.emptyList());
	}

	/**
	 * The STARTING SHOT this account still owes on the addressed clan's live event (site lib/startProof),
	 * or {@code null} when nothing is owed — which is the case on every event that doesn't ask for
	 * one, on sites that predate the feature, and the moment one is filed.
	 */
	public PluginConfigResponse.StartProof startProof()
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null || cfg.startProof == null || !cfg.startProof.required
			|| !cfg.startProof.drawn || !cfg.startProof.needsUpload)
		{
			return null;
		}
		// Only while the event is actually live — the same gate the in-game overlay uses, so the
		// panel can't ask for a shot of an event that has ended.
		return AnvilOverlay.isEventActive(cfg.event) ? cfg.startProof : null;
	}

	/**
	 * The starting shot's live requirements (session age, position) for the card, in display order.
	 * Empty where nothing is checked. Cheap and non-blocking: the panel polls it every second.
	 */
	public List<StartProofRules.Check> startProofChecks(PluginConfigResponse.StartProof proof)
	{
		return fromPlugin(p -> p.startProofChecks(proof), Collections.emptyList());
	}

	/** Will the plugin take the starting shot by itself once the checks pass? (config autoStartShot) */
	public boolean autoStartShot()
	{
		return fromPlugin(AnvilPlugin::autoStartShotEnabled, false);
	}

	/** Ask Shortest Path for a route to the starting shot's spot. */
	public void routeToStartSpot()
	{
		withPlugin(AnvilPlugin::routeToStartSpot);
	}

	/**
	 * Whether this event's tiles can be pinned as in-game widgets: the site serves them (capability
	 * "tile-tracker") and it is the event you're playing, or one still waiting to start (pinned early,
	 * it counts down and goes live at the whistle).
	 */
	public boolean canTrackTiles(int eventId, boolean preStart)
	{
		PluginConfigResponse cfg = configSupplier.get();
		return eventId > 0 && (preStart || cfg != null && cfg.event != null && cfg.event.id == eventId)
			&& fromPlugin(AnvilPlugin::supportsTileTracker, false)
			&& fromPlugin(AnvilPlugin::inGame, false);
	}

	/** The live board's event id, or 0 with none. */
	public int activeEventId()
	{
		PluginConfigResponse cfg = configSupplier.get();
		return cfg != null && cfg.event != null ? cfg.event.id : 0;
	}

	/** This client's newest count for a tile, or -1 (AnvilPlugin.tileCount). */
	public long tileCount(int tileId)
	{
		return fromPlugin(p -> p.tileCount(tileId), -1L);
	}

		/** The tiles pinned over the game on {@code eventId}. */
	public List<Integer> pinnedTiles(int eventId)
	{
		return eventId > 0 ? fromPlugin(p -> p.tileTracker().pinned(eventId), Collections.<Integer>emptyList())
			: Collections.<Integer>emptyList();
	}

	/** Signed in, and the first config answer hasn't come back (or failed) yet. */
	public boolean awaitingFirstConfig()
	{
		return fromPlugin(AnvilPlugin::awaitingFirstConfig, false);
	}

	/** Take every pin on {@code eventId} off the screen. */
	public void unpinAll(int eventId)
	{
		withPlugin(p -> p.tileTracker().clear(eventId));
	}

	public void setTileTracked(int eventId, int tileId, boolean on)
	{
		withPlugin(p -> p.setTrackedTile(eventId, tileId, on));
	}

	/** Take + file the starting shot. No-op where {@link #startProof()} is null. Never blocks the EDT. */
	public void captureStartProof()
	{
		Runnable capture = startProofCapture;
		if (capture != null)
		{
			capture.run();
		}
	}

	/** Whether the site builds the Lookup and You tabs ({@link UiView}). False ⇒ no tabs, and a lookup opens the browser. */
	public boolean supportsPluginUi()
	{
		return siteSupports("plugin-ui");
	}

	/**
	 * The config's capability list when there is a config; /api/version's when the person is in no
	 * clan (a 404 config carries none). The You and Lookup tabs are exactly what someone without a
	 * clan should still get.
	 */
	private boolean siteSupports(String capability)
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg != null)
		{
			return cfg.serverSupports(capability);
		}
		return apiClient.signedInWithoutClan() && apiClient.siteAdvertises(capability);
	}

	/** The game's name lists for Lookup's suggestions; {@code then} runs on the client thread. */
	public void lookupNames(Consumer<LookupSuggestions.Names> then)
	{
		AnvilPlugin p = plugin;
		if (p == null)
		{
			then.accept(LookupSuggestions.Names.EMPTY);
			return;
		}
		p.lookupNames(then);
	}

	/** The character logged in right now, or null at the login screen. */
	public String myRsn()
	{
		return apiClient.getCurrentRsn();
	}

	// ── The clan switcher's data ────────────────────────────────────────────────────────────────
	//
	// One Anvil serves every clan, so the Site URL names none of them and a person may hold seats in
	// several. Straight off the config this source already reads, so offering the dropdown costs no
	// request.

	/**
	 * Re-read the config if it's stale (always, on a clicked Refresh — often someone was just made a
	 * clan admin, so ask about that now too). Blocking; the panel calls it off the EDT.
	 */
	public void refreshConfig(boolean force)
	{
		withPlugin(p ->
		{
			p.refreshConfigForSidebar(force);
			if (force)
			{
				p.reprobeAdminNow();
			}
		});
	}

	/** Every clan the signed-in person holds a seat in. Empty on an older site, or before the first poll. */
	public List<PluginConfigResponse.ClanRef> clans()
	{
		PluginConfigResponse cfg = configSupplier.get();
		return cfg == null ? Collections.emptyList() : cfg.switchableClans();
	}

	/** The member's explicit pick, or "" when they are on Auto and the site is deciding. */
	public String chosenClan()
	{
		return fromPlugin(AnvilPlugin::getChosenClan, "");
	}

	/**
	 * The clan slug this plugin is actually addressing — a pick if there is one, else whatever the
	 * site resolved. "" before the first answer.
	 */
	public String activeClan()
	{
		return apiClient.getActiveClan();
	}

	/** The member picked a clan (or "" for Auto): persist it and refetch, without waiting. EDT-safe. */
	public void chooseClan(String slug)
	{
		withPlugin(p -> p.setChosenClan(slug));
	}

	// ---- Weekly competitions (SOTW/BOTW) as sidebar events ----------------------------------------

	// ── The logged-in character: whose it's tracked as, and the way out ──────────────────────────
	//
	// The Account Token names whoever set this RuneLite up, not whoever is playing. Every character
	// links to it by default (the one-click path); siblings and visitors use this row to say "not
	// mine", and to claim back a character that's linked to somebody else.

	/** One line about the logged-in character. */
	@RequiredArgsConstructor
	public static final class AccountRow
	{
		public enum State
		{
			/** Linked to (or linking to) the signed-in Anvil account. Offers Not my account. */
			TRACKING,
			/** Marked Not my account on this computer; nothing is sent. Offers Track it again. */
			PAUSED,
			/** Claimed by another Anvil account; nothing tracks for this token. Offers It's mine. */
			OTHER,
		}

		public enum Action
		{
			NOT_MINE,
			TRACK_AGAIN,
			DISPUTE,
		}

		public final String rsn;
		public final State state;

	}

	/**
	 * What the panel may DO for the addressed clan.
	 *
	 * <p>A roster sync scrapes the clan channel you are standing in, so it needs an admin with that
	 * channel readable. A profile sync goes to the site the plugin is authenticated against.
	 */
	public static final class PanelActions
	{
		public static final PanelActions NONE = new PanelActions(false, false, null);

		/** Show "Sync clan roster": admin, at home, with a readable clan channel. */
		public final boolean canSyncRoster;
		/** Show "Sync profile": the site takes profile data and it's the one we're signed in to. */
		public final boolean canSyncProfile;
		/** Why the roster button is absent, when the reason is worth saying. Null when it isn't. */
		public final String rosterNote;

		public PanelActions(boolean canSyncRoster, boolean canSyncProfile, String rosterNote)
		{
			this.canSyncRoster = canSyncRoster;
			this.canSyncProfile = canSyncProfile;
			this.rosterNote = rosterNote;
		}
	}
}

package com.anvil;

import com.google.gson.JsonObject;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.*;
import javax.swing.*;
import javax.swing.Timer;
import java.awt.event.*;
import javax.swing.plaf.basic.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.*;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.game.*;

import static com.anvil.Ui.*;
import net.runelite.client.config.ConfigManager;
import java.util.function.Supplier;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/**
 * The side panel. What it holds natively is what only this client has: signing in, the account line,
 * the clan picker, the tab strip, the Lookup search box, settings and banner sounds, and the starting
 * shot. Everything to look at — the Clan tab's events and boards, You, what Lookup found — is a view
 * the site builds and {@link UiView} draws. An auto-refresh runs only while the panel is open.
 *
 * <p><b>Threading:</b> all Swing mutation stays on the EDT; the config re-read and the views' fetches
 * run off it and hand back via invokeLater. {@link Singleton} — one toolbar panel.</p>
 */
@Slf4j
@Singleton
public class AnvilSidebarPanel extends PluginPanel
{
	/** Auto-refresh cadence while the panel is open. Mirrors the plugin's other polls. */
	private static final int POLL_INTERVAL_MS = 15_000;


	// Anvil theme for the interactive widgets: flat dark surfaces with the gold/orange accent the
	// rest of the sidebar (title, bars, links) already uses — default Swing chrome sticks out badly.
	private static final Color WIDGET_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color WIDGET_BG_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;
	private static final Color WIDGET_BORDER = new Color(0x47_47_47);

	/** Wrap width for the connect-status line so a long notice wraps instead of clipping (tooltip carries full text). */
	private static final int STATUS_WRAP_PX = PluginPanel.PANEL_WIDTH - 40;


	/** Clip rows on the home page before the rest collapse into a "+N more" line. */
	private static final int BANNER_CLIPS_SHOWN = 8;




	private final AnvilSidebarDataSource dataSource;
	/** Item and boss icons for the player card. Null in tests that build the panel by hand. */
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final SkillIconManager skillIconManager;

	// ---- Tabs: Clan · You · Lookup ----------------------------------------------------------------
	// Clan is everything the panel always was — `content` below, untouched. You and Lookup are views
	// the site builds (UiView), and only exist while it does (the `plugin-ui` capability): without it
	// the strip hides and the Clan tab says the site is too old, with Sync profile and the sound lists
	// under it (renderEmpty).
	enum Tab { CLAN, YOU, LOOKUP, SETTINGS }
	private Tab tab = Tab.CLAN;
	/** Whether the strip is showing, i.e. signed in to a site that serves player cards. */
	private boolean tabsOn;
	// Holds ONLY the selected tab's panel. A CardLayout sized every tab to the tallest one — usually
	// Clan mid-event — and BoxLayout spread that extra height through the You card: log bars drifted
	// apart and the grids were squeezed until their last row clipped.
	private final JPanel tabBody = new JPanel(new BorderLayout());
	private final JPanel tabStrip = new JPanel(new GridBagLayout());
	private final Map<Tab, JLabel> tabLabels = new EnumMap<>(Tab.class);
