	// ---- The logged-in character's account row -----------------------------------------------------

	private void refreshAccountRow()
	{
		AnvilSidebarDataSource.AccountRow row = dataSource.accountRow();
		boolean changed = shownAccountRow == null || row == null
			|| shownAccountRow.state != row.state || !shownAccountRow.rsn.equals(row.rsn);
		shownAccountRow = row;
		// Shown whenever this computer is signed in — it is also where Sign out lives.
		accountRowPanel.setVisible(!apiClient.needsSignIn());
		if (row == null)
		{
			setAccountLabel("Signed in", "Signed in to Anvil on this computer. Log in to a character to start tracking it.", false);
			accountLink.setVisible(false);
			setAccountStatus("");
			accountRowPanel.repaint();
			return;
		}
		if (changed && !accountActionInFlight)
		{
			setAccountStatus("");
		}
		String name = esc(row.rsn);
		switch (row.state)
		{
			case PAUSED:
				setAccountLabel("Not tracking <b>" + name + "</b> on this computer", row.rsn + " is marked Not my account here — nothing is sent for it.", true);
				accountLink.setText("Track again");
				accountLink.setVisible(true);
				break;
			case OTHER:
				setAccountLabel("<b>" + name + "</b> is linked to another Anvil account", row.rsn + " is linked to another Anvil account, so nothing is tracked for you.", true);
				accountLink.setText("It's mine?");
				accountLink.setVisible(true);
				break;
			default:
				setAccountLabel("Tracking <font color='#ffffff'><b>" + name + "</b></font>", "Tracking " + row.rsn + " for your Anvil account.", false);
				// Everyday state: nothing to decide, so the action lives in the Account menu.
				accountLink.setVisible(false);
				break;
		}
		accountLink.setEnabled(!accountActionInFlight);
		capH(accountRowPanel).revalidate();
		accountRowPanel.repaint();
	}

	private void onAccountButton()
	{
		AnvilSidebarDataSource.AccountRow row = shownAccountRow;
		if (row == null || accountActionInFlight)
		{
			return;
		}
		AnvilSidebarDataSource.AccountRow.Action action;
		String question;
		switch (row.state)
		{
			case PAUSED:
				action = AnvilSidebarDataSource.AccountRow.Action.TRACK_AGAIN;
				question = null; // undoing is harmless — no confirm
				break;
			case OTHER:
				action = AnvilSidebarDataSource.AccountRow.Action.DISPUTE;
				question = "Ask Anvil staff to move " + row.rsn + " to your Anvil account?\n\n"
					+ "It's linked to someone else right now. Staff will check and move it if it's yours.";
				break;
			default:
				action = AnvilSidebarDataSource.AccountRow.Action.NOT_MINE;
				question = "Stop tracking " + row.rsn + " on this computer?\n\n"
					+ "Use this if someone else plays it here — a sibling, a friend. It's unlinked from your "
					+ "Anvil account and nothing is sent while it's logged in. Your other accounts aren't affected, "
					+ "and you can undo it from this panel.";
				break;
		}
		if (question != null && JOptionPane.showConfirmDialog(this, question, "Anvil",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE) != JOptionPane.OK_OPTION)
		{
			return;
		}
		accountActionInFlight = true;
		accountLink.setEnabled(false);
		setAccountStatus("Working…");
		dataSource.accountAction(action, outcome -> SwingUtilities.invokeLater(() ->
		{
			accountActionInFlight = false;
			refreshAccountRow();
			setAccountStatus(outcome);
			refresh();
		}));
	}

	/** Room the label leaves for the link (and ⋯) to its right. */
	private static final int ACCOUNT_LINK_ROOM_PX = 72;

	/**
	 * The everyday "Tracking X" stays one quiet line (a long name is clipped; the tooltip has it all).
	 * The rare states that ask for a decision wrap instead, so they're read in full.
	 */
	private void setAccountLabel(String html, String tooltip, boolean wrap)
	{
		accountLabel.setText(wrap
			? wrapHtml(html, STATUS_WRAP_PX - ACCOUNT_LINK_ROOM_PX)
			: "<html><nobr>" + html + "</nobr></html>");
		accountLabel.setToolTipText(tooltip);
	}

	private void setAccountStatus(String text)
	{
		setStatus(accountStatus, text, accountRowPanel);
	}

	/**
	 * A status line under a control, wrapped as HTML so a long line breaks instead of being clipped at
	 * the edge of a narrow sidebar, and hidden while empty. The row holding it is re-capped on every
	 * change: capped once at construction, while the line was hidden, it could never grow to fit it.
	 */
	private static boolean setStatus(JLabel status, String text, JPanel row)
	{
		String plain = text == null ? "" : text;
		boolean show = !plain.isEmpty();
		status.setText(show ? wrapHtml(esc(plain), STATUS_WRAP_PX) : "");
		status.setVisible(show);
		capH(row).revalidate();
		return show;
	}


	// ---- Refresh flow -----------------------------------------------------------------------------

	/**
	 * Forget everything on screen, because it belongs to a site or an account we are no longer using.
	 *
	 * <p>Called the moment the token changes. Without it the panel kept rendering the
	 * previous clan's events, board and roster until a fetch against the NEW credentials succeeded —
	 * which is indefinitely when the new ones are wrong, so the member sits looking at a clan they
	 * just left and reasonably concludes the change didn't take.
	 */
	public void clearForCredentialChange()
	{
		clanShown = false;
		rebuildingPicker = true;
		clanPicker.removeAllItems();
		rebuildingPicker = false;
		setPickerWanted(false); // no config for the new credentials yet, so no clans to choose between
		setSignInStatus("");
		refreshSignInRow();
		renderLoading();
	}

	/** Ask again: the clan picker and sign-in state from the config the plugin holds, the tab from the site. */
	public void refresh()
	{
		refresh(false);
	}

	/** A background refresh (the timer): the same, and the view redraws only if the site's answer changed. */
	public void poll()
	{
		refresh(false);
	}

	/**
	 * The plugin's config re-read happens off the EDT (so a fetch never holds the panel), then the
	 * picker and strip redraw from it and the Clan tab asks the site. A burst of repaints — config,
	 * hello, a login — asks the site once; a click on Refresh always asks.
	 */
	private void refresh(boolean manual)
	{
		if (!onScreen)
		{
			return;
		}
		refreshAccountRow();
		interactive().execute(() ->
		{
			dataSource.refreshConfig(manual);
			SwingUtilities.invokeLater(() ->
			{
				rebuildClanPicker();
				updateTabStrip();
				refreshSignInRow();
				refreshAccountRow();
				if (tab == Tab.YOU)
				{
					renderYou(false); // a refresh can change what You shows: the character, the card
				}
				else if (tab == Tab.SETTINGS)
				{
					renderSettings(); // admin rights and the sound list can change under it
				}
				showClan(manual);
			});
		});
	}

	/** The Clan tab: the sign-in card, a line, or the site's view of the clan. EDT. */
	private void showClan(boolean manual)
	{
		if (apiClient.needsSignIn() || !dataSource.supportsPluginUi())
		{
			clanShown = false;
			if (dataSource.awaitingFirstConfig())
			{
				renderLoading();
			}
			else
			{
				renderEmpty();
			}
			return;
		}
		long now = System.currentTimeMillis();
		if (!clanShown)
		{
			clanShown = true;
			clanAskedAt = now;
			setContent(clanView);
			clanView.show("home", Collections.emptyMap(), "Loading progress…");
		}
		else if (manual || now - clanAskedAt >= MIN_ASK_GAP_MS && !typingInSearch())
		{
			clanAskedAt = now;
			clanView.refresh();
		}
	}

	/** The least time between the Clan tab's own asks, Refresh aside. */
	private static final long MIN_ASK_GAP_MS = 5_000L;

	/** Somebody is in the tiles or Teams search: don't ask again under their caret. */
	private boolean typingInSearch()
	{
		Window w = SwingUtilities.getWindowAncestor(clanView);
		Component f = w == null ? null : w.getFocusOwner();
		return f instanceof JTextField && SwingUtilities.isDescendingFrom(f, clanView);
	}

	/** The site confirmed a tile done: ask now, so a tile's detail doesn't say "Open" after the chat said done. */
	public void tileCompleted()
	{
		clanAskedAt = 0;
		refresh();
	}

	private BooleanSupplier pushLive = () -> false;
	private int quietTicks;

	void setPushLive(BooleanSupplier live)
	{
		pushLive = live;
	}

	/** The live push says the board moved: ask now. */
	void boardChanged()
	{
		clanAskedAt = 0;
		SwingUtilities.invokeLater(this::poll);
	}

	private final AtomicBoolean liveQueued = new AtomicBoolean();
	/** After counts alone moved, the rest of the view (who's on what, the feed) is asked for this much later. */
	private static final int COUNTS_CATCH_UP_MS = 15_000;
	private final Timer countsCatchUp = new Timer(COUNTS_CATCH_UP_MS, e -> boardChanged());

	/** Counts moved here (own progress, the push): the Clan tab's live ones redraw, at most once per frame. Any thread. */
	void liveCountsMoved()
	{
		if (liveQueued.compareAndSet(false, true))
		{
			SwingUtilities.invokeLater(() ->
			{
				liveQueued.set(false);
				clanView.tickLive();
			});
		}
	}

	/** The push carried counts only: they're on screen already; the rest catches up once, a little later. */
	void countsChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (!countsCatchUp.isRunning())
			{
				countsCatchUp.setRepeats(false);
				countsCatchUp.start();
			}
		});
	}

	private void tickStartProof()
	{
		if (startProofTick != null)
		{
			startProofTick.run();
		}
	}

	/**
	 * Repopulate the clan dropdown, suppressing the selection-event storm a setModel provokes.
	 *
	 * <p>Fed from the site's list of this person's seats, not from the boards we happen to have loaded:
	 * the point of the control is to reach a clan whose board we have NOT loaded. Hidden below two
	 * entries, because one option that cannot be changed is not a choice.</p>
	 *
	 * <p>There used to be a rule here that landed a guest on their own clan instead. It is gone
	 * deliberately, not lost: the server applies the stronger version of it when it resolves a clanless
	 * request — a live event first, then a real membership before any guest seat — and two copies of a
	 * default that can disagree is worse than one copy that decides.</p>
	 */
	private void rebuildClanPicker()
	{
		List<ClanChoice> choices = ClanChoice.of(dataSource.clans());
		rebuildingPicker = true;
		try
		{
			DefaultComboBoxModel<ClanChoice> model = new DefaultComboBoxModel<>();
			String chosen = dataSource.chosenClan();
			ClanChoice toSelect = null;
			for (ClanChoice c : choices)
			{
				model.addElement(c);
				if (c.slug.equals(chosen))
				{
					toSelect = c;
				}
			}
			clanPicker.setModel(model);
			// Nothing chosen — the site is deciding, which is the Auto row.
			clanPicker.setSelectedItem(toSelect != null ? toSelect : choices.isEmpty() ? null : choices.get(0));
			setPickerWanted(choices.size() > 2);
		}
		finally
		{
			rebuildingPicker = false;
		}
	}

	/**
	 * One row of the clan dropdown: a clan to narrow to, or all of them.
	 *
	 * "All clans" is the DEFAULT and it is a real row, not an implied initial state, because it is
	 * also the only way back. A member who narrows to a clan that later goes quiet would otherwise be
	 * stuck watching a dead board while their live one runs somewhere else, with nothing in the UI
	 * admitting it.
	 *
	 * On "All clans" the site decides which board the plugin addresses — live event first — and the
	 * rest appear under "Also live". Choosing a clan narrows to it and moves where submissions file,
	 * which is a bigger deal than a filter usually is; the rows say so.
	 */
	static final class ClanChoice
	{
		/** Clan slug, or "" for Auto. */
		final String slug;
		final String label;
		/** Second line — the board running there, or what this seat is. Never null. */
		final String detail;

		ClanChoice(String slug, String label, String detail)
		{
			this.slug = slug == null ? "" : slug;
			this.label = label == null ? "" : label;
			this.detail = detail == null ? "" : detail;
		}

		/** Auto first, then the clans in the order the site sent them (newest seat first). */
		static List<ClanChoice> of(List<PluginConfigResponse.ClanRef> clans)
		{
			List<ClanChoice> out = new ArrayList<>();
			if (clans == null || clans.isEmpty())
			{
				return out;
			}
			out.add(new ClanChoice("", "All clans", "Everything you're playing"));
			for (PluginConfigResponse.ClanRef c : clans)
			{
				if (c == null || c.slug == null || c.slug.isEmpty())
				{
					continue;
				}
				out.add(new ClanChoice(c.slug, c.name == null || c.name.isEmpty() ? c.slug : c.name, detailOf(c)));
			}
			return out;
		}

		/** What is happening in this clan, in one short line — the reason to pick it or not. */
		private static String detailOf(PluginConfigResponse.ClanRef c)
		{
			if (c.live == null || c.live.eventName == null || c.live.eventName.isEmpty())
			{
				return "guest".equals(c.kind) ? "Guest \u00b7 nothing live" : "Nothing live";
			}
			// A competition has a leaderboard rather than a board to fill, so "0/0" would be a lie
			// dressed as progress. The name is the whole answer there.
			String head = c.live.isWeekly() || c.live.tilesTotal <= 0
				? c.live.eventName
				: c.live.eventName + "  " + c.live.tilesComplete + "/" + c.live.tilesTotal;
			// One line names ONE of them. Say how many were not named rather than letting an arbitrary
			// pick stand in for the whole clan — the number is why you would open the clan at all.
			int more = c.liveCount - 1;
			return more > 0 ? head + "  +" + more + " more" : head;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}


	// ---- Render states ----------------------------------------------------------------------------

	private void renderLoading()
	{
		// The picker STAYS. Switching clan renders this state on purpose, and yanking the control the
		// member is holding — then putting it back a second later — reads as the click having failed.
		JLabel loading = new JLabel("Loading progress…", SwingConstants.CENTER);
		loading.setForeground(MUTED);
		loading.setBorder(BorderFactory.createEmptyBorder(24, 0, 0, 0));
		setContent(loading);
	}

	private void renderEmpty()
	{
		// TWO DIFFERENT NOTHINGS, and they were being told the same story. "Link a clan on your Anvil
		// site" is advice for somebody who HAS a site and an account; a fresh install has neither, and
		// reading it as their first contact with the plugin leaves them looking for a clan page nobody
		// has given them the address of. Signed out is the state to answer first, because it is the
		// state every new install starts in.
		if (apiClient.needsSignIn())
		{
			setContent(firstRunCard());
			return;
		}
		// Signed in, but the site doesn't draw the panel (no `plugin-ui`): an older or self-hosted Anvil,
		// or none reachable yet. Say that rather than "no clans", and keep what still works without it —
		// Sync profile, the roster button and the sound lists — since the tab strip is hidden here.
		PluginErrorPanel empty = new PluginErrorPanel();
		empty.setContent("Can't show your clan here",
			"Your Anvil site is older than this plugin, or can't be reached right now. If it stays like this, ask whoever runs it to update.");
		renderSettings();
		JPanel stack = new JPanel();
		stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
		stack.setOpaque(false);
		stack.add(empty);
		stack.add(settingsPanel);
		setContent(stack);
	}

	/**
	 * What a fresh install sees: what this is, the one button that connects it, and where that goes.
	 *
	 * <p>The sign-in button itself lives in the header (it is shown in exactly this state), so this
	 * points at it rather than repeating it. What it adds is the half a stranger cannot guess — that
	 * the account is free, that it is theirs rather than their clan's, and that a person with no clan
	 * still gets something out of it. The link is the only address here, and it is the same one
	 * pressing Sign in would write.</p>
	 */
	private JPanel firstRunCard()
	{
		JPanel card = section("New here?");
		card.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		card.add(note("Anvil tracks your OSRS progress — collection log, personal bests, records — and"
			+ " your clan's bingo boards. Press Sign in with Discord above to make your free account"
			+ " and connect this client in one step."));
		card.add(gap(6));
		card.add(note("You don't need a clan: your profile is your own. If you run one, starting it"
			+ " there is free too."));
		JLabel site = styleLink(new JLabel(BingoApiClient.CANONICAL_SITE.replaceFirst("^https?://", "")), "Open Anvil in your browser",
			() -> LinkBrowser.browse(BingoApiClient.CANONICAL_SITE));
		site.setIcon(new GlyphIcon(GlyphIcon.Shape.EXTERNAL, 11));
		site.setHorizontalTextPosition(SwingConstants.LEADING);
		site.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		card.add(site);

		return card;
	}

	/** A wrapped grey paragraph at the panel's width — long copy clips rather than wraps without it. */
	private static JLabel note(String text)
	{
		return note(text, MUTED);
	}

	private static JLabel note(String text, Color color)
	{
		JLabel label = new JLabel(wrapHtml(esc(text == null ? "" : text), STATUS_WRAP_PX));
		label.setFont(SMALL);
		label.setForeground(color);
		return label;
	}

	/**

	// ---- Events list (a clan running more than one thing) ------------------------------------------

	/**
	 * Roster sync and profile sync, when this account can do them here.
	 *
	 * <p>A roster is scraped from the clan channel you're standing in, so the button is absent for
	 * any clan but your own — an admin elsewhere still can't see a roster they aren't in — and it
	 * says why rather than vanishing without explanation. Both buttons carry the same limits as
	 * their in-game counterparts, which live in the plugin, not here.
	 */
	private JPanel buildPanelActions(boolean withProfile)
	{
		JPanel panel = column();
		AnvilSidebarDataSource.PanelActions full = dataSource.actionsFor();
		// Sync profile sends YOUR log and best times; with the You tab showing it lives there.
		AnvilSidebarDataSource.PanelActions actions = withProfile ? full
			: new AnvilSidebarDataSource.PanelActions(full.canSyncRoster, false, full.rosterNote);
		if (!actions.canSyncRoster && !actions.canSyncProfile && actions.rosterNote == null)
		{
			return panel; // nothing this account can do here; no empty heading either
		}

		heading(panel, "This clan");

		// Two buttons that do the same KIND of thing belong on one line: stacked full-width they read
		// as a list of unrelated commands, and they cost two rows of a panel that has none to spare.
		// Side by side the labels have to be short, which is why the pair says "Sync roster" and the
		// lone button (nothing to sit beside) keeps the longer "Sync clan roster".
		boolean both = actions.canSyncProfile && actions.canSyncRoster;
		if (both)
		{
			panel.add(buttonRow(
				flatButton("Sync profile", "Send your collection log and best times to this clan's site",
					dataSource::syncProfile),
				flatButton("Sync roster", "Push the in-game clan member list to the site",
					dataSource::syncRoster)));
		}
		else if (actions.canSyncProfile)
		{
			panel.add(fullWidthButton("Sync profile",
				"Send your collection log and best times to this clan's site", dataSource::syncProfile));
		}
		else if (actions.canSyncRoster)
		{
			panel.add(fullWidthButton("Sync clan roster",
				"Push the in-game clan member list to the site", dataSource::syncRoster));
		}

		if (!actions.canSyncRoster && actions.rosterNote != null)
		{
			if (actions.canSyncProfile)
			{
				panel.add(gap(4));
			}
			panel.add(small(actions.rosterNote, MUTED));
		}

		return panel;
	}

	/**
	 * Banner clips, which are files in a folder on THIS machine.
	 *
	 * <p>Nothing here is per account or per clan — swapping character or clan doesn't change which
	 * .wav files are on your disk — so the list is the same wherever you are in the panel. A lit
	 * swatch is in the play cycle, a hollow one is muted, and clicking the row flips it.
	 */
	private JPanel buildBannerSounds()
	{
		List<String> clips = dataSource.sounds(BannerSoundService.Kind.BANNER);
		JPanel panel = section("Banner sounds");

		if (clips.isEmpty())
		{
			panel.add(small("None added — use Add clip, or the banner folder.", MUTED));
			panel.add(gap(4));
		}
		else
		{
			for (String clip : clips.subList(0, Math.min(clips.size(), BANNER_CLIPS_SHOWN)))
			{
				panel.add(buildClipRow(clip, dataSource.bannerSoundOn(clip)));
				panel.add(gap(2));
			}
			if (clips.size() > BANNER_CLIPS_SHOWN)
			{
				JLabel more = small("+" + (clips.size() - BANNER_CLIPS_SHOWN) + " more in the folder", MUTED);
				more.setBorder(BorderFactory.createEmptyBorder(2, CLIP_TEXT_INSET, 0, 0));
				panel.add(more);
			}
			panel.add(gap(4));
		}

		panel.add(buttonRow(
			flatButton("Add clip", "Pick .wav files to copy into the banner sounds folder", Color.WHITE,
				() -> dataSource.importSounds(BannerSoundService.Kind.BANNER)),
			flatButton("Copy folder path", "Copy the sounds folder's path — paste it into your file manager to rename or delete clips",
				Color.WHITE, dataSource::copyBannerSoundsPath)));

		// MISSIONS, stated rather than configured. A mission dropping should not sound like a tile
		// being finished, and what it sounds like is decided by whether this folder has anything in
		// it — so the panel says which of the two is happening, and the button is how you change it.
		panel.add(gap(8));
		int missions = dataSource.sounds(BannerSoundService.Kind.MISSION).size();
		panel.add(small(missions == 0
			? "Missions: a game sound (no clip added)"
			: "Missions: " + missions + (missions == 1 ? " clip" : " clips"), MUTED));
		panel.add(gap(4));
		panel.add(fullWidth(flatButton(missions == 0 ? "Add mission clip" : "Add mission clips",
			"Pick .wav files to play when a mission drops, instead of the game sound used by default",
			Color.WHITE, () -> dataSource.importSounds(BannerSoundService.Kind.MISSION))));
		return panel;
	}

	/** How far a clip's name sits from the panel edge — the swatch's width plus its gap. */
	private static final int CLIP_TEXT_INSET = 14;

	/**
	 * One clip: a lit swatch, its name, and a click that mutes or unmutes it.
	 *
	 * <p>Colour alone carried this before — a green name meant playing, a grey one meant muted — which
	 * is invisible if you don't already know the rule, and unreadable if you can't separate the two
	 * greens. The swatch says on/off the way the in-game list does, the row lights under the pointer
	 * so it's clearly a control, and the tooltip names the action rather than the state.
	 */
	private JPanel buildClipRow(String clip, boolean on)
	{
		String display = BannerSoundService.displayName(clip);

		JPanel row = left(new JPanel(new BorderLayout(6, 0)));
		row.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 4));
		row.setToolTipText(plainText(display) + (on ? " — click to mute" : " — muted; click to unmute"));

		JPanel swatch = new JPanel();
		swatch.setPreferredSize(new Dimension(8, 8));
		swatch.setMinimumSize(new Dimension(8, 8));
		swatch.setMaximumSize(new Dimension(8, 8));
		swatch.setBackground(on ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.DARK_GRAY_COLOR);
		swatch.setBorder(BorderFactory.createLineBorder(on
			? ColorScheme.PROGRESS_COMPLETE_COLOR : WIDGET_BORDER));
		// Centre the 8px square against the text line rather than stretching it down the row.
		JPanel swatchBox = new JPanel(new GridBagLayout());
		swatchBox.setOpaque(false);
		swatchBox.setPreferredSize(new Dimension(CLIP_TEXT_INSET - 6, 12));
		swatchBox.add(swatch);

		row.add(swatchBox, BorderLayout.WEST);
		row.add(small(display.length() <= 26 ? display : display.substring(0, 25).trim() + "…", on ? ColorScheme.TEXT_COLOR : MUTED), BorderLayout.CENTER);
		hoverable(capH(row), ColorScheme.DARK_GRAY_COLOR, () ->
		{
			dataSource.toggleBannerSound(clip);
			renderSettings();
		});
		return row;
	}

	// ---- Component builders -----------------------------------------------------------------------

	/** A small gold section label, matching the panel's header style. */
	private static JLabel sectionHeader(String text)
	{
		return small(text, ColorScheme.BRAND_ORANGE);
	}

	/** A section heading and the gap under it, added to {@code into}. */
	private static void heading(JPanel into, String text)
	{
		into.add(sectionHeader(text));
		into.add(gap(6));
	}

	/** A {@link Ui#column} that opens with a section heading. */
	private static JPanel section(String text)
	{
		JPanel p = column();
		heading(p, text);
		return p;
	}

	/**
	 * The starting-shot prompt: where to stand, this account's keyword, and the one button that
	 * captures the frame, burns the proof banner onto it and files it. Rendered only while a shot is
	 * actually owed — {@link AnvilSidebarDataSource#startProof()} returns null the moment one is filed.
	 */
	private JPanel buildStartProofCard(PluginConfigResponse.StartProof proof)
	{
		JPanel card = block();
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE),
			BorderFactory.createEmptyBorder(6, 8, 8, 8)));
		card.add(small("Starting shot needed", ColorScheme.BRAND_ORANGE));

		if (proof.location != null && !proof.location.isEmpty())
		{
			JLabel where = small("Go to " + proof.location, Color.WHITE);
			where.setToolTipText(plainText(proof.location));
			card.add(gap(4));
			card.add(where);
		}

		if (proof.keyword != null && !proof.keyword.isEmpty())
		{
			card.add(gap(2));
			card.add(small("Keyword: " + proof.keyword, MUTED));
		}

		// The requirements the button checks — session age, position — shown live, so a player can
		// see each one go green instead of finding out from a refusal in chat. Ticks every second
		// while the card is on screen, on the panel's own second tick; dropped once the card is replaced.
		JPanel checks = column();
		checks.setOpaque(false);
		renderStartProofChecks(checks, proof);
		if (checks.getComponentCount() > 0)
		{
			card.add(gap(4));
			card.add(checks);
			startProofTick = () ->
			{
				if (checks.isDisplayable())
				{
					renderStartProofChecks(checks, proof);
				}
				else
				{
					startProofTick = null;
				}
			};
		}

		if ("rejected".equals(proof.status))
		{
			card.add(gap(2));
			card.add(warningLabel("Your last shot was rejected — take another."));
		}

		// WHY it matters, which the card never said. A player who reads "starting shot needed" and
		// carries on has no way to know their drops are landing in a review queue meanwhile.
		card.add(gap(4));
		card.add(warningLabel("Drops you send now are held for review until this is filed."));

		String left = StartProofRules.describeWindow(proof, System.currentTimeMillis());
		if (left != null)
		{
			JLabel expires = small("Asked for another " + left + ", then it lapses", Color.WHITE);
			expires.setToolTipText("Six hours in, the game has logged everyone out anyway, so the shot stops being asked for.");
			card.add(gap(2));
			card.add(expires);
		}

		if (proof.spot != null && dataSource.autoStartShot())
		{
			card.add(gap(2));
			card.add(small("Taken and sent automatically once both are green.", ColorScheme.LIGHT_GRAY_COLOR));

		}

		JButton take = new JButton("Take starting shot");
		styleFlatButton(take, ColorScheme.BRAND_ORANGE);
		take.addActionListener(e ->
		{
			take.setEnabled(false);
			take.setText("Sending...");
			// The capture itself hops to the next rendered frame and then to a worker; the panel just
			// asks for it. The button goes away entirely on the next poll, once the site agrees.
			dataSource.captureStartProof();
			// ...unless the capture refused it — standing in the wrong place, or a session too old to
			// have flushed the hiscores. That answer arrives in chat, so the button has to come back
			// rather than sit on "Sending..." until the next poll redraws the card.
			Timer restore = new Timer(4000, ev ->
			{
				take.setText("Take starting shot");
				take.setEnabled(true);
			});
			restore.setRepeats(false);
			restore.start();
		});
		card.add(gap(6));
		card.add(take);

		if (proof.spot != null)
		{
			card.add(gap(4));
			card.add(fullWidthButton("Route me there", "Draws the way there with the Shortest Path plugin, if you have it",
				dataSource::routeToStartSpot));
		}

		return card;
	}

	private void renderStartProofChecks(JPanel into, PluginConfigResponse.StartProof proof)
	{
		List<StartProofRules.Check> list = dataSource.startProofChecks(proof);
		into.removeAll();
		for (StartProofRules.Check c : list)
		{
			Color color = c.state == StartProofRules.Check.State.OK ? ColorScheme.PROGRESS_COMPLETE_COLOR
				: c.state == StartProofRules.Check.State.BAD ? ColorScheme.PROGRESS_ERROR_COLOR
				: ColorScheme.LIGHT_GRAY_COLOR;
			GlyphIcon.Shape shape = c.state == StartProofRules.Check.State.OK ? GlyphIcon.Shape.CHECK : GlyphIcon.Shape.CLOSE;
			JLabel row = small(c.text, color);
			row.setIcon(new GlyphIcon(shape, 9, color));
			row.setIconTextGap(4);
			row.setToolTipText("Hiscores only save when you log out, so a fresh session is what sets your starting totals.");
			into.add(row);
		}
		into.revalidate();
		into.repaint();
	}

	// ---- Tiles and Teams pages --------------------------------------------------------------------

	/** Install one row listener on the panel and every label nested inside it. */
	static void addMouseListenerToTree(Component component, MouseAdapter listener)
	{
		component.addMouseListener(listener);
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				addMouseListenerToTree(child, listener);
			}
		}
	}

	private JLabel warningLabel(String message)
	{
		JLabel warn = small(message, ColorScheme.PROGRESS_ERROR_COLOR);
		return warn;
	}

	/** Swap the single content component and repaint. */
	private void setContent(Component component)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (content.getComponentCount() == 1 && content.getComponent(0) == component)
			{
				return;
			}
			content.removeAll();
			if (component instanceof JComponent)
			{
				((JComponent) component).setAlignmentX(LEFT_ALIGNMENT);
			}
			content.add(component);
			content.revalidate();
			content.repaint();
		});
	}

	// ---- Anvil-themed widget chrome ---------------------------------------------------------------

	/** A themed action button in the panel's orange, wired to one thing it does. */
	static JButton flatButton(String label, String tooltip, Runnable onClick)
	{
		return flatButton(label, tooltip, ColorScheme.BRAND_ORANGE, onClick);
	}

	private static JButton flatButton(String label, String tooltip, Color foreground, Runnable onClick)
	{
		JButton b = new JButton(label);
		styleFlatButton(b, foreground);
		b.setToolTipText(tooltip);
		b.addActionListener(e -> onClick.run());
		return b;
	}

	/**
	 * Two buttons on one line, equal halves.
	 *
	 * <p>The height cap matters: a grid inside a vertical BoxLayout will happily stretch to whatever
	 * space is left, which turns a pair of buttons into a pair of slabs.
	 */
	private static JPanel buttonRow(JButton left, JButton right)
	{
		return buttons(new GridLayout(1, 2, 4, 0), left, right);
	}

	/** {@link #flatButton} holding a whole row, so a lone action doesn't sit in half a line. */
	static JPanel fullWidthButton(String label, String tooltip, Runnable onClick)
	{
		return fullWidth(flatButton(label, tooltip, onClick));
	}

	private static JPanel fullWidth(JButton button)
	{
		return buttons(new GridLayout(1, 1), button);
	}

	private static JPanel buttons(GridLayout layout, JButton... buttons)
	{
		JPanel row = left(new JPanel(layout));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (JButton b : buttons)
		{
			row.add(b);
		}
		return capH(row);
	}

	private static void styleFlatButton(JButton b, Color foreground)
	{
		b.setFocusPainted(false);
		b.setForeground(foreground);
		b.setBackground(WIDGET_BG);
		b.setFont(SMALL);
		b.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(WIDGET_BORDER),
			BorderFactory.createEmptyBorder(4, 10, 4, 10)));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (b.isEnabled())
				{
					b.setBackground(WIDGET_BG_HOVER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				b.setBackground(WIDGET_BG);
			}
		});
	}

	/** Flat combo for the clan selector and tile-status filter: dark field, gold arrow — default Swing sticks out. */
	static void styleCombo(JComboBox<?> combo)
	{
		combo.setBackground(WIDGET_BG);
		combo.setForeground(Color.WHITE);
		combo.setFont(SMALL);
		combo.setBorder(BorderFactory.createLineBorder(WIDGET_BORDER));
		combo.setUI(new BasicComboBoxUI()
		{
			@Override
			protected JButton createArrowButton()
			{
				BasicArrowButton arrow = new BasicArrowButton(
					SwingConstants.SOUTH, WIDGET_BG, WIDGET_BG, ColorScheme.BRAND_ORANGE, WIDGET_BG);
				arrow.setBorder(BorderFactory.createEmptyBorder());
				return arrow;
			}
		});
	}

	/**
	 * Two real labels, not one HTML one.
	 *
	 * The second line was <code>&lt;font size='-2'&gt;</code> inside a label already set to
	 * RuneScape's small font. That font is a bitmap face: asked to render smaller still it does not
	 * get daintier, it gets illegible — and the size the browser-ish HTML renderer picks is not one
	 * the face was drawn at. The rest of this panel never shrinks type to mean "secondary"; it keeps
	 * the same small font and drops the colour to {@link #MUTED}. This does the same.
	 *
	 * Building the row out of components also means no markup, which means no clan name can smuggle
	 * any: {@link #plainText} was guarding a string we were about to concatenate into HTML ourselves,
	 * which is the one case it does not guard.
	 */
	private static final class ClanChoiceRenderer implements ListCellRenderer<ClanChoice>
	{
		private final JPanel row = new JPanel(new BorderLayout(0, 1));
		private final JLabel name = new JLabel();
		private final JLabel detail = new JLabel();

		ClanChoiceRenderer()
		{
			name.setFont(SMALL);
			detail.setFont(SMALL);
			row.setOpaque(true);
			row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			row.add(name, BorderLayout.NORTH);
			row.add(detail, BorderLayout.SOUTH);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends ClanChoice> list, ClanChoice value,
			int index, boolean isSelected, boolean cellHasFocus)
		{
			// index >= 0 → a popup row; -1 → the closed field. Dark rows, gold-tinted hover.
			boolean hover = isSelected && index >= 0;
			row.setBackground(hover ? WIDGET_BG_HOVER : WIDGET_BG);
			name.setForeground(hover ? ColorScheme.BRAND_ORANGE : Color.WHITE);
			detail.setForeground(MUTED);

			name.setText(value == null ? "" : plainText(value.label));
			// The closed field shows the name alone — a second line there would resize the header on
			// every refresh, and the detail is what you read while choosing, not after.
			boolean showDetail = index >= 0 && value != null && !value.detail.isEmpty();
			detail.setText(showDetail ? plainText(value.detail) : "");
			detail.setVisible(showDetail);
			return row;
		}
	}
}

package com.anvil;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

import javax.inject.*;
import javax.swing.SwingUtilities;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.stream.*;

/**
 * Plays a clip when the bingo banner fires, and another when a mission drops. No clips ship with the
 * plugin — users supply their own WAV/PCM files (the only format stock Java decodes) through
 * {@link #importSounds}, which copies them into {@code sounds/banner/} or {@code sounds/mission/}.
 * The folder is what makes a clip a banner clip or a mission clip; there is no setting to keep in
 * step with it, and a mission folder left empty simply keeps the built-in chime. The old {@code .runelite/anvil-bingo-sounds}
 * folder is not readable from here and is not the one legacy directory the migration could carry, so
 * anyone who used it re-imports. Nothing plays until a file is added. Playback goes through RuneLite's {@link AudioPlayer} (plugin-hub policy requires
 * this over the raw Java Sound API).
 */
@Slf4j
@Singleton
public class BannerSoundService
{
	/**
	 * The plugin's own `sounds/` folder, handed over by AnvilPlugin at startUp.
	 *
	 * NOT MIGRATED, and deliberately so: the client moves exactly one legacy folder and that slot is
	 * spent on the pending queue, which holds screenshots of drops that cannot be taken again. A .wav
	 * is still wherever the user got it, and Add sounds re-imports it through the same picker they
	 * used the first time.
	 */
	private volatile Filepath root;

	private final AnvilConfig config;
	private final AudioPlayer audioPlayer;
	// The service is a singleton that outlives a plugin stop/start, so shutdown() can't leave a dead
	// executor behind: the next play() would throw RejectedExecutionException into the loot handler.
	private ExecutorService audioExecutor;

	@Inject
	public BannerSoundService(AnvilConfig config, AudioPlayer audioPlayer)
	{
		this.config = config;
		this.audioPlayer = audioPlayer;
	}

	public void setRoot(Filepath dir)
	{
		this.root = dir;
		migrateLooseClips();
		for (Kind kind : Kind.values())
		{
			relist(kind);
		}
	}

	/**
	 * WHICH CLIP IS THIS? Answered by the folder it is in, not by a setting.
	 *
	 * <p>A mission dropping is the opposite kind of news from a tile being finished, so the two
	 * should not sound alike — but "different how?" used to be a toggle choosing between the banner
	 * clip and a built-in chime, with no way to supply a mission clip at all. A folder each answers
	 * it without asking anything: drop a .wav in {@code mission/} and missions play it, leave it
	 * empty and they keep the built-in chime.</p>
	 */
	@RequiredArgsConstructor
	public enum Kind
	{
		BANNER("banner"),
		MISSION("mission");

		private final String folder;

	}

	/** One kind's directory, created on demand, or null when there is nowhere to read or write. */
	private Filepath dir(Kind kind)
	{
		Filepath d = root;
		if (d == null)
		{
			return null;
		}
		try
		{
			Filepath sub = d.joinSegment(kind.folder);
			if (!sub.exists())
			{
				sub.createDirectories();
			}
			return sub;
		}
		catch (IOException e)
		{
			log.warn("Anvil: cannot create the {} sounds directory: {}", kind.folder, e.getMessage());
			return null;
		}
	}

	/**
	 * Clips added before the folders existed sat loose in {@code sounds/}, where nothing looks any
	 * more. They are banner clips — that is all there was — so they are moved once, quietly. Doing it
	 * here rather than asking means nobody's sounds stop working because the layout changed under
	 * them.
	 */
	private void migrateLooseClips()
	{
		Filepath d = root;
		List<Filepath> loose = d == null || !d.isDirectory() ? new ArrayList<>() : wavsIn(d);
		Filepath banner = loose.isEmpty() ? null : dir(Kind.BANNER);
		if (banner == null)
		{
			return;
		}
		for (Filepath f : loose)
		{
			try
			{
				f.moveTo(banner.joinSegment(f.getFileName()), StandardCopyOption.REPLACE_EXISTING);
			}
			catch (Exception e)
			{
				log.debug("Could not move {} into banner/: {}", f.getFileName(), e.getMessage());
			}
		}
		log.debug("Anvil: moved {} clip(s) into banner/", loose.size());
	}

	/** Every .wav in one kind's folder. Depth 1 — a clip is a file in it, never deeper. */
	private List<Filepath> wavFiles(Kind kind)
	{
		Filepath dir = dir(kind);
		return dir == null ? new ArrayList<>() : wavsIn(dir);
	}

	private static List<Filepath> wavsIn(Filepath dir)
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(f -> f.isFile() && f.getFileName().toLowerCase().endsWith(".wav")).collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.debug("Could not list sounds in {}: {}", dir.getFileName(), e.getMessage());
			return new ArrayList<>();
		}
	}

	/** True if this kind has at least one .wav (i.e. it could play something of its own). */
	public boolean hasClips(Kind kind)
	{
		return !wavFiles(kind).isEmpty();
	}

	/**
	 * How old a folder listing may get before it's re-read. The panel asks on every draw, on the EDT,
	 * so it is always answered from memory and the re-read happens on {@link #audioExecutor}; a clip
	 * dropped into the folder by hand shows up this much later at worst (Add sounds re-reads at once).
	 */
	private static final long LISTING_TTL_MS = 10_000L;
	private final Map<Kind, List<String>> listed = new EnumMap<>(Kind.class);
	private final Map<Kind, Long> listedAt = new EnumMap<>(Kind.class);
	private final Set<Kind> relisting = EnumSet.noneOf(Kind.class);
	/** Told (on the audio thread) when a re-read finds the clips changed, so the panel can redraw. */
	private volatile Runnable onClipsChanged = () -> { };

	public void setOnClipsChanged(Runnable onChange)
	{
		onClipsChanged = onChange == null ? () -> { } : onChange;
	}

	/**
	 * All .wav filenames for one kind, case-insensitively sorted (for the in-tab manager). Never
	 * touches disk: it answers from the last listing (empty before the first) and, if that's stale,
	 * re-reads the folder in the background.
	 */
	public List<String> listClips(Kind kind)
	{
		List<String> cached;
		boolean stale;
		synchronized (this)
		{
			cached = listed.getOrDefault(kind, Collections.emptyList());
			Long at = listedAt.get(kind);
			stale = at == null || System.currentTimeMillis() - at >= LISTING_TTL_MS;
		}
		if (stale)
		{
			relist(kind);
		}
		return cached;
	}

	/** Re-read one kind's folder on the audio thread; a no-op while a re-read is already queued. */
	private void relist(Kind kind)
	{
		synchronized (this)
		{
			if (!relisting.add(kind))
			{
				return;
			}
		}
		try
		{
			executor().execute(() -> relistNow(kind));
		}
		catch (RejectedExecutionException e)
		{
			synchronized (this)
			{
				relisting.remove(kind);
			}
		}
	}

	/** Blocking (disk) — the audio thread only. */
	private void relistNow(Kind kind)
	{
		List<String> names = Collections.unmodifiableList(wavFiles(kind).stream()
			.map(Filepath::getFileName).sorted(String.CASE_INSENSITIVE_ORDER).collect(Collectors.toList()));
		List<String> before;
		synchronized (this)
		{
			relisting.remove(kind);
			before = listed.put(kind, names);
			listedAt.put(kind, System.currentTimeMillis());
		}
		if (!names.equals(before == null ? Collections.emptyList() : before))
		{
			onClipsChanged.run();
		}
	}

	/**
	 * A clip filename as something to read: "odablock-we-won.wav" becomes "Odablock we won".
	 *
	 * <p>Clips arrive as downloaded files, so their names are slugs. Printed verbatim they made both
	 * the in-game list and the side panel look like a directory listing that had leaked into the
	 * interface. Lives here rather than in either panel because both of them show the same files.
	 */
	public static String displayName(String file)
	{
		String s = file == null ? "" : file.trim();
		int dot = s.lastIndexOf('.');
		if (dot > 0)
		{
			s = s.substring(0, dot);
		}
		s = s.replace('_', ' ').replace('-', ' ').replaceAll("\\s+", " ").trim();
		if (s.isEmpty())
		{
			return file == null ? "" : file;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/**
	 * True if {@code name} is in the play cycle. The cycle is the comma-separated allowlist in
	 * {@link AnvilConfig#bannerSoundClip()}; an empty allowlist means "every clip plays".
	 */
	public boolean isSelected(String name)
	{
		Set<String> sel = parseSelected(config.bannerSoundClip());
		return sel.isEmpty() || sel.contains(name.toLowerCase());
	}

	/** Parse the comma-separated clip allowlist into lowercased ".wav" filenames. Empty = play all. */
	static Set<String> parseSelected(String csv)
	{
		Set<String> out = new LinkedHashSet<>();
		if (csv == null)
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String s = part.trim().toLowerCase();
			if (s.isEmpty())
			{
				continue;
			}
			if (!s.endsWith(".wav"))
			{
				s += ".wav";
			}
			out.add(s);
		}
		return out;
	}

	public void play(Kind kind)
	{
		if (!config.bannerSound())
		{
			return;
		}
		try
		{
			executor().submit(() -> playBlocking(kind));
		}
		catch (RejectedExecutionException e)
		{
			log.debug("Banner sound skipped", e);
		}
	}

	private synchronized ExecutorService executor()
	{
		if (audioExecutor == null || audioExecutor.isShutdown())
		{
			audioExecutor = Executors.newSingleThreadExecutor(r ->
			{
				Thread t = new Thread(r, "anvil-banner-sound");
				t.setDaemon(true);
				return t;
			});
		}
		return audioExecutor;
	}

	private void playBlocking(Kind kind)
	{
		try
		{
			List<Filepath> files = wavFiles(kind);
			if (files.isEmpty())
			{
				return;
			}

			// The cycle is the allowlist (comma-separated filenames); empty = every clip is eligible.
			// Each banner plays one at random from the eligible set, so a multi-clip cycle varies.
			// Mission clips have no allowlist: the folder is already the choice of what plays.
			Set<String> selected = kind == Kind.BANNER ? parseSelected(config.bannerSoundClip()) : Collections.emptySet();
			List<Filepath> candidates = new ArrayList<>();
			for (Filepath f : files)
			{
				if (selected.isEmpty() || selected.contains(f.getFileName().toLowerCase()))
				{
					candidates.add(f);
				}
			}
			if (candidates.isEmpty())
			{
				return;
			}

			// AudioPlayer takes a Filepath directly as of 1.12.39, so the clip never leaves the sandbox.
			audioPlayer.play(candidates.get(ThreadLocalRandom.current().nextInt(candidates.size())), gainDb());
		}
		catch (Exception e)
		{
			log.debug("Banner sound skipped: {}", e.getMessage());
		}
	}

	/**
	 * Convert the 0–100 volume config to a MASTER_GAIN decibel value AudioPlayer applies. 100 → 0 dB
	 * (unattenuated); lower volumes attenuate logarithmically; 0 → effectively silent. AudioPlayer
	 * clamps to the line's supported range.
	 */
	private float gainDb()
	{
		int vol = Math.max(0, Math.min(100, config.bannerSoundVolume()));
		return vol <= 0 ? -80f : (float) (20.0 * Math.log10(vol / 100.0));
	}

	/**
	 * Opens a file picker and copies the chosen WAV(s) into the user sounds folder. {@code onImported}
	 * (may be null) is invoked with the successfully-copied filenames so the caller can confirm in chat;
	 * it's skipped when the user cancels or nothing copied.
	 */
	public void importSounds(Kind kind, Consumer<List<String>> onImported)
	{
		SwingUtilities.invokeLater(() ->
		{
			// Filepath.Chooser rather than a bare JFileChooser: the user picking a file is how a
			// plugin is granted anything outside its own directory, and it is the same dialog they
			// were already looking at. Nothing else about this flow changes — the clips are copied
			// in, and playback still only ever reads our own folder.
			List<Filepath> chosen = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsFiles()
				.setMultiSelectionEnabled(true)
				.setDialogTitle(kind == Kind.MISSION ? "Add mission sounds" : "Add banner sounds")
				.addExtensionFilter("WAV audio", "wav")
				.showDialog((java.awt.Component) null);
			if (chosen == null || chosen.isEmpty())
			{
				return;
			}
			Filepath dir = dir(kind);
			if (dir == null)
			{
				return;
			}
			// The picker needs the EDT; the copies don't, and a big .wav is a long copy.
			try
			{
				executor().execute(() -> copyIn(kind, dir, chosen, onImported));
			}
			catch (RejectedExecutionException e)
			{
				log.debug("Sound import skipped, plugin shutting down");
			}
		});
	}

	/** Blocking (disk) — the audio thread only. */
	private void copyIn(Kind kind, Filepath dir, List<Filepath> chosen, Consumer<List<String>> onImported)
	{
		List<String> imported = new ArrayList<>();
		for (Filepath src : chosen)
		{
			String name = src.getFileName();
			try
			{
				src.copyTo(dir.joinSegment(name), StandardCopyOption.REPLACE_EXISTING);
				imported.add(name);
			}
			catch (Exception e)
			{
				log.warn("Could not import sound {}: {}", name, e.getMessage());
			}
		}
		relistNow(kind);
		if (onImported != null && !imported.isEmpty())
		{
			onImported.accept(imported);
		}
	}

	/** Copies the user sounds folder's path — see Clipboards for why it can't be opened directly. */
	public void copyFolderPath()
	{
		Filepath dir = root;
		if (dir == null)
		{
			return;
		}
		// The PARENT, not one kind's folder: both `banner/` and `mission/` are inside it, so one
		// paste lands somewhere the player can see the whole arrangement and drag files between them.
		try
		{
			if (!dir.exists())
			{
				dir.createDirectories();
			}
		}
		catch (IOException e)
		{
			log.debug("Could not create the sounds folder: {}", e.getMessage());
			return;
		}
		// LinkBrowser::open is restricted for hub releases, so the path goes on the clipboard and the
		// player pastes it wherever they were going to open it.
		Clipboards.copy(dir.toString());
	}

	public synchronized void shutdown()
	{
		if (audioExecutor != null)
		{
			audioExecutor.shutdownNow();
			audioExecutor = null;
		}
	}
}

package com.anvil;

import com.google.gson.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class BingoApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");

	private final Gson gson;
	// Package-private so tests can drive a request through the pause gate (AccountOptOutTest).
	final OkHttpClient httpClient;
	private String apiUrl;
	private String playerToken;
	// In-game RSN of the locally logged-in account. Sent as `X-RSN` on every player-token
	// request so the server can scope the per-user plugin token to the correct clan_member
	// (and reject drops on accounts that aren't signed up for the active event).
	private volatile String currentRsn;
	// Stable Jagex account hash (client.getAccountHash()) of the locally logged-in account.
	// Sent as `X-Account-Hash` so the server can anchor auto-verification to the account even
	// across in-game renames. Null when logged out / unavailable.
	private volatile String accountHash;
	// The character the Jagex Launcher says is about to log in (client.getLauncherDisplayName()), sent
	// as `X-RSN-Hint` only while no RSN is stamped. The site uses it to pick which of this person's own
	// characters a read is about, so the panel shows the right board before Play; it never claims,
	// links or verifies anything — that stays with X-RSN after the real login. Null off the launcher.
	private volatile String rsnHint;
	/** True while the logged-in world is a seasonal (Leagues) world. Set from the plugin on login/hop. */
	private volatile boolean seasonal;
	// The logged-in character was marked "Not my account" on this install (AccountOptOut). While set,
	// NOTHING carrying the Account Token leaves the client — isConfigured() says no, so every gated
	// path stays quiet, and an interceptor refuses anything that slips past a gate. The one exception
	// is the account action itself (tagged ACCOUNT_ACTION), which is how the choice reaches the site.
	private volatile boolean accountPaused;

	/** Request tag that lets an account action through while {@link #accountPaused} is set. */
	private static final class AccountAction
	{
	}

	private static final AccountAction ACCOUNT_ACTION = new AccountAction();

	private okhttp3.Interceptor pauseGate()
	{
		return chain ->
		{
			Request r = chain.request();
			if (accountPaused && r.header("Authorization") != null && r.tag(AccountAction.class) == null)
			{
				throw new IOException("Anvil is off for this account on this computer (Not my account).");
			}
			return chain.proceed(r);
		};
	}

	private final OkHttpClient readClient;

	/** The injected Gson, for callers that serialise what this client returns. */
	Gson gson()
	{
		return gson;
	}

	@Inject
	public BingoApiClient(Gson gson, OkHttpClient client)
	{
		this.gson = gson;
		// Read timeout is generous because some server reads do several round-trips to Turso
		// and can take a while; tighter timeouts here will trip even on healthy servers.
		this.httpClient = client.newBuilder()
			.addInterceptor(pauseGate())
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(90, TimeUnit.SECONDS)
			.writeTimeout(30, TimeUnit.SECONDS)
			.build();
		this.pushClient = httpClient.newBuilder().pingInterval(30, TimeUnit.SECONDS).build();
		// Reads the sidebar waits on (config, feed, board, cards) give up sooner: a panel stuck on
		// "Loading…" for a minute and a half is worse than one that says the site is slow and keeps
		// what it had. Uploads and submissions keep the long timeout above.
		this.readClient = httpClient.newBuilder()
			.readTimeout(20, TimeUnit.SECONDS)
			.build();
	}

	/**
	 * Point the client at Anvil with this Account Token.
	 *
	 * THE SITE IS FIXED ({@link #CANONICAL_SITE}); there is no Site URL to configure. What the client
	 * still holds back on is WHEN it uses it: the address is only live once there is a token, so an
	 * install nobody has signed into reaches nothing — every poll bails on an empty {@code apiUrl}.
	 * Sign-in itself goes to the constant directly ({@link #authUrl}), since it runs before any token.
	 */
	public void configure(String playerToken)
	{
		this.playerToken = playerToken;
		this.apiUrl = playerToken == null || playerToken.trim().isEmpty() ? "" : CANONICAL_SITE;
	}

	/** The site base URL in use, or "" while signed out (see {@link #configure}). */
	public String getApiUrl()
	{
		return apiUrl == null ? "" : apiUrl;
	}

	// ── WHICH CLAN THIS CLIENT IS TALKING TO ────────────────────────────────────────────────
	//
	// The site is one Anvil, and one Anvil serves every clan. On the canonical
	// address it therefore names no clan at all, and the server picks one from the token — live event
	// first, then latest start, then newest seat.
	//
	// Good defaults, but a guess re-made on every request. Once we have been TOLD which clan we are
	// dealing with — either because the member chose one in the sidebar, or because /config answered
	// and said which one it answered for — we say so outright, by addressing `/c/<slug>` instead of
	// the bare root. Same canonical path a browser uses, and the site has resolved it since the day
	// clans stopped being subdomains.
	//
	// Two things fall out of it that are worth having on purpose. A member in two live boards stops
	// being at the mercy of "latest start wins". And the handful of routes outside /api/plugin that
	// still resolve a clan from the ADDRESS rather than the token — filing a submission, filing the
	// starting shot, uploading its image — resolve correctly on the bare apex, which they do not when
	// nothing names a clan.

	/** A clan slug as the site accepts one; anything else is treated as naming no clan. */
	private static final Pattern CLAN_SLUG = Pattern.compile("[a-z0-9-]{2,32}");

	// TWO SLUGS, and the difference between them is the whole design.
	//
	// `chosen` is the member's pick in the sidebar. Empty means "Auto" — they have not chosen, and
	// the server should keep deciding.
	//
	// `resolved` is what the server last told us it answered for. In Auto we adopt it for every call
	// EXCEPT the config poll itself, which stays unaddressed so the server keeps re-deciding: a member
	// whose live board moves to their other clan should follow it without touching a dropdown. Adopting
	// it everywhere else is what makes a submission, a starting shot and its upload land in the right
	// clan on the canonical address, where nothing in the URL says which clan is meant.

	/** The member's explicit pick, or "" for Auto. Survives restarts (AnvilPlugin persists it). */
	private volatile String chosenClan = "";

	/** The clan the site last said it answered for. In-memory: it is the server's judgement, not a setting. */
	private volatile String resolvedClan = "";

	/** The member picked a clan in the sidebar, or picked Auto (null/blank). */
	public void setChosenClan(String slug)
	{
		this.chosenClan = cleanSlug(slug);
	}

	/** The member's explicit pick, or "" when they are on Auto. */
	public String getChosenClan()
	{
		return chosenClan;
	}

	/** The site answered, and named the clan it answered for. */
	public void setResolvedClan(String slug)
	{
		this.resolvedClan = cleanSlug(slug);
	}

	/** The clan this client is actually addressing right now — a pick beats the server's guess. */
	public String getActiveClan()
	{
		return !chosenClan.isEmpty() ? chosenClan : resolvedClan;
	}

	/**
	 * Validated rather than trusted: a slug arrives over the wire and is about to be pasted into every
	 * URL this client builds. Anything that is not a slug names no clan — which is the behaviour we
	 * already had, and so cannot break anything.
	 */
	private static String cleanSlug(String slug)
	{
		String clean = slug == null ? "" : slug.trim().toLowerCase();
		return !clean.isEmpty() && CLAN_SLUG.matcher(clean).matches() ? clean : "";
	}

	/**
	 * A clan-scoped URL: the base, the clan we are addressing, then the path.
	 *
	 * Everything the plugin calls is clan-scoped except signing in, which is about a person and happens
	 * before any clan is known ({@link #rootUrl}), and the config poll in Auto ({@link #configUrl}).
	 */
	String clanUrl(String path)
	{
		String slug = getActiveClan();
		return slug.isEmpty() ? apiUrl + path : apiUrl + "/c/" + slug + path;
	}

	/**
	 * Where to ask for the config.
	 *
	 * An explicit pick is addressed like everything else. On Auto this stays deliberately unaddressed,
	 * so every poll is a fresh question — the answer names the clan, and the answer is allowed to
	 * change when the member's live board does.
	 */
	String configUrl(String path)
	{
		return chosenClan.isEmpty() ? apiUrl + path : apiUrl + "/c/" + chosenClan + path;
	}

	/** A URL that must NOT carry a clan. */
	String rootUrl(String path)
	{
		return apiUrl + path;
	}

	/** The device sign-in pair — identity, not membership, and run BEFORE there is a token, so it
	 * cannot wait for {@code apiUrl}: always the fixed site. */
	static String authUrl(String path)
	{
		return CANONICAL_SITE + path;
	}

	/**
	 * Sets the in-game RSN of the locally logged-in account. The plugin should call this
	 * on every login (and clear it on logout). Null/empty values are tolerated — the
	 * server will fall back to "any active event" matching, but cross-account safety
	 * degrades.
	 */
	public void setCurrentRsn(String rsn)
	{
		// Mid-login the client names the player "#Player2014" for a tick or two. No real name has a
		// '#', and stamping that one filed requests under a character that doesn't exist.
		this.currentRsn = (rsn == null || rsn.isEmpty() || rsn.indexOf('#') >= 0) ? null : rsn;
	}

	/** The RSN currently stamped on requests (the logged-in character), or null. Thread-safe read. */
	public String getCurrentRsn()
	{
		return currentRsn;
	}

	/**
	 * Sets the stable Jagex account hash of the locally logged-in account. Call alongside
	 * {@link #setCurrentRsn} on login (and clear on logout). Pass the raw value from
	 * {@code client.getAccountHash()}; values that mean "not logged in" (null or -1) are
	 * treated as cleared.
	 */
	public void setAccountHash(long hash)
	{
		this.accountHash = hash == -1L ? null : Long.toString(hash);
	}

	/** The Jagex Launcher's character name, or null when RuneLite wasn't started from the launcher. */
	public void setRsnHint(String name)
	{
		this.rsnHint = (name == null || name.trim().isEmpty()) ? null : name.trim();
	}

	/** The account hash currently stamped on requests, or null. */
	public String getAccountHash()
	{
		return accountHash;
	}

	public String getRsnHint()
	{
		return rsnHint;
	}

	/** Called when the world changes: seasonal posts route to the clan's Leagues channel server-side. */
	public void setSeasonal(boolean seasonal)
	{
		this.seasonal = seasonal;
	}

	/**
	 * Anvil — the only server this plugin talks to. There is no Site URL setting: one site serves every
	 * clan, and the clan is resolved from the Account Token.
	 *
	 * A fresh install contacts no server until someone starts sign-in. The sign-in UI names the
	 * destination before the click; after authentication, {@link #configure} enables requests with the
	 * resulting Account Token.
	 */
	public static final String CANONICAL_SITE = "https://anvilosrs.com";

	/**
	 * True when there is no Account Token yet — the state the Sign-in button serves.
	 *
	 * The Sign-in button is the way in for a fresh install — it fills the token in itself
	 * (DeviceSignIn), so nobody has to copy anything out of the site.
	 */
	public boolean needsSignIn()
	{
		return playerToken == null || playerToken.isEmpty();
	}

	// ---- Device-code sign-in (home-native RFC 8628; see the site's /api/plugin/auth/*) ----------

	/** POST /api/plugin/auth/start response. */
	public static class DeviceAuthStart
	{
		public String device_code;
		public String user_code;
		public String verification_url;
		public String verification_url_complete;
		public int interval;
		public int expires_in;
	}

	/** POST /api/plugin/auth/poll response — status: pending | slow_down | expired | denied | complete. */
	public static class DeviceAuthPoll
	{
		public String status;
		public String token;
		public int interval;
	}

	/** Begin the device sign-in. Deliberately UNAUTHENTICATED (the whole point is no token yet), and
	 * only ever started by a click on Sign in. Null on transport/HTTP failure. */
	public DeviceAuthStart authStart()
	{
		return getOrNull(plainRequest(authUrl("/api/plugin/auth/start")).post(RequestBody.create(null, new byte[0])),
			DeviceAuthStart.class, "auth/start");
	}

	/** GET /api/plugin/push/ticket: a pass onto the live push socket ({@link PushSocket}). */
	public static class PushTicket
	{
		public String url;
		public String ticket;
	}

	/**
	 * Null when signed out, refused, or there's no board to listen to (204) — and when the socket it
	 * names isn't on the site this plugin already talks to, which it never dials anywhere else.
	 */
	PushTicket fetchPushTicket()
	{
		PushTicket t = isConfigured() ? getOrNull(authedRequest(clanUrl("/api/plugin/push/ticket")).get(), PushTicket.class, "push ticket") : null;
		HttpUrl socket = t == null || t.url == null ? null : HttpUrl.parse(t.url.replaceFirst("^ws", "http"));
		HttpUrl site = HttpUrl.parse(getApiUrl());
		return socket != null && site != null && socket.host().equals(site.host()) ? t : null;
	}

	/**
	 * Pings keep the push socket honest: without them a connection that died quietly (sleep, a Wi-Fi
	 * change, an expired NAT entry) sends no close and no failure, and the plugin would believe it's
	 * live — polling slowly — forever. Derived from the injected client, so it shares its pool.
	 */
	private final OkHttpClient pushClient;

	WebSocket openPush(PushTicket ticket, WebSocketListener listener)
	{
		return pushClient.newWebSocket(plainRequest(ticket.url).header("Authorization", "Bearer " + ticket.ticket).build(), listener);
	}

	/** Poll the device sign-in. Null on transport failure (caller treats as a pending tick). */
	public DeviceAuthPoll authPoll(String deviceCode)
	{
		if (deviceCode == null || deviceCode.isEmpty())
		{
			return null;
		}
		RequestBody body = RequestBody.create(MediaType.parse("application/json"),
			gson.toJson(Collections.singletonMap("device_code", deviceCode)));
		return getOrNull(plainRequest(authUrl("/api/plugin/auth/poll")).post(body), DeviceAuthPoll.class, "auth/poll");
	}

	/** An unauthenticated request carrying only the plugin version. */
	private static Request.Builder plainRequest(String url)
	{
		return new Request.Builder().url(url).header("X-Anvil-Plugin-Version", PLUGIN_VERSION);
	}

	/**
	 * A GET that sends the Account Token when there is one — never X-RSN or the account hash: a lookup
	 * is usually about somebody else, so the identity headers that drive claims have no business here.
	 *
	 * Also the token-optional calls (weekly leaderboard, hello). Those were written against a site that
	 * WAS a clan; on the canonical address, which names none, the token is the only thing that can say
	 * which clan the caller means. A caller without a token gets exactly what it got before.
	 */
	private Request.Builder publicRequest(String url)
	{
		Request.Builder rb = plainRequest(url).get();
		String token = playerToken;
		if (token != null && !token.trim().isEmpty())
		{
			rb.header("Authorization", "Bearer " + token.trim());
		}
		return rb;
	}

	/** Reads one response: status and headers on {@code r}, its body already read as text ("" when none). */
	private interface Reply<T>
	{
		T read(Response r, String body) throws IOException;
	}

	/**
	 * Every blocking call goes through here, so each one trips {@link OffThread} if it lands on a thread
	 * that must not wait. {@code client} is deliberate: {@link #readClient} for reads the sidebar waits on,
	 * {@link #httpClient} for writes and uploads. {@code reply} sees every status; one it refuses is thrown
	 * as an {@link HttpStatusException} (or a subclass), so a caller can tell a refusal by its code.
	 */
	private <T> T execute(OkHttpClient client, Request.Builder request, Reply<T> reply) throws IOException
	{
		Request req = request.build();
		OffThread.check("HTTP " + req.method() + " " + req.url().encodedPath());
		try (Response r = client.newCall(req).execute())
		{
			return reply.read(r, r.body() != null ? r.body().string() : "");
		}
	}

	/** {@link #execute}, null on a transport, status or parse failure (logged as "{@code label} failed"). */
	private <T> T executeOrNull(OkHttpClient client, Request.Builder request, String label, Reply<T> reply)
	{
		try
		{
			return execute(client, request, reply);
		}
		catch (IOException | JsonParseException e)
		{
			log.debug("{} failed: {}", label, e.getMessage());
			return null;
		}
	}

	/** Parse a 2xx body as {@code type}; null on any other status or a transport/parse failure. */
	private <T> T getOrNull(Request.Builder request, Class<T> type, String label)
	{
		return executeOrNull(readClient, request, label, (r, body) ->
		{
			if (!r.isSuccessful())
			{
				throw new HttpStatusException("HTTP " + r.code(), r.code());
			}
			return gson.fromJson(body, type);
		});
	}

	/**
	 * Plugin semver, read from the same resource build.gradle uses as its version source
	 * (src/main/resources/com/anvil/version.txt). Sent on every site call as
	 * X-Anvil-Plugin-Version so sites can see which plugin versions their members run.
	 */
	static final String PLUGIN_VERSION = loadPluginVersion();

	private static String loadPluginVersion()
	{
		try (InputStream in = BingoApiClient.class.getResourceAsStream("version.txt"))
		{
			if (in == null)
			{
				return "unknown";
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
		catch (IOException e)
		{
			return "unknown";
		}
	}

	/** An Account Token request as the logged-in character. */
	Request.Builder authedRequest(String url)
	{
		return authedRequest(url, currentRsn, rsnHint, accountHash);
	}

	/**
	 * The one place the identity headers are written, so a queued notification resent later goes out
	 * exactly as a live one would, as the character it was first sent for. The hint only rides when no
	 * RSN is stamped.
	 */
	private Request.Builder authedRequest(String url, String rsn, String hint, String hash)
	{
		Request.Builder b = plainRequest(url).header("Authorization", "Bearer " + playerToken);
		if (rsn != null && !rsn.isEmpty()) b.header("X-RSN", rsn);
		else if (hint != null) b.header("X-RSN-Hint", hint);
		if (hash != null && !hash.isEmpty()) b.header("X-Account-Hash", hash);
		return b;
	}

	public boolean isConfigured()
	{
		return isSignedIn() && !accountPaused;
	}

	/** Signed in at all, whether or not the logged-in character is paused. For the panel's account row. */
	public boolean isSignedIn()
	{
		return !getApiUrl().isEmpty() && !needsSignIn();
	}

	/** Stop (or resume) every Anvil request for the logged-in character. See {@link #accountPaused}. */
	public void setAccountPaused(boolean paused)
	{
		this.accountPaused = paused;
	}

	public boolean isAccountPaused()
	{
		return accountPaused;
	}

	/** Result of POST /api/plugin/account. */
	public static class AccountActionResult
	{
		public boolean ok;
		public String error;
		public String reason;
		public boolean alreadyOpen;
	}

	/**
	 * The side panel's account row: {@code release} ("Not my account"), {@code resume} (undo) or
	 * {@code dispute} ("It's mine" on a character linked to somebody else). Runs on the caller's
	 * thread — call it off the EDT. Allowed through while paused: it is how the choice gets there.
	 * Never throws; a network failure comes back as {@code ok=false} with the reason.
	 */
	public AccountActionResult postAccountAction(String action)
	{
		AccountActionResult out = new AccountActionResult();
		if (!isSignedIn() || currentRsn == null)
		{
			out.error = "Sign in and log in to the account first.";
			return out;
		}
		JsonObject payload = new JsonObject();
		payload.addProperty("action", action);
		try
		{
			return execute(httpClient, authedRequest(clanUrl("/api/plugin/account"))
				.tag(AccountAction.class, ACCOUNT_ACTION).post(json(payload)), (r, text) ->
			{
				AccountActionResult parsed = text.isEmpty() ? null : gson.fromJson(text, AccountActionResult.class);
				AccountActionResult res = parsed != null ? parsed : out;
				res.ok = r.isSuccessful();
				if (!res.ok && res.error == null)
				{
					res.error = "The site said " + r.code() + ".";
				}
				return res;
			});
		}
		catch (IOException | JsonParseException e)
		{
			out.error = "Couldn't reach Anvil: " + e.getMessage();
			return out;
		}
	}

	/**
	 * Fire-and-forget: POST a clan notification to our own site, which builds the Discord post (from
	 * {@code facts}, see {@link NotifyFacts}) and forwards it to the channel configured server-side.
	 * {@code content} (deaths, PvP kills) or {@code facts} may be null; so may {@code png}. The plugin
	 * never holds a webhook URL (plugin-hub rule). Never blocks: OkHttp's async dispatcher.
	 */
	public void postNotification(String channel, String content, NotifyFacts facts, byte[] png, String filename)
	{
		if (!isConfigured() || channel == null || channel.isEmpty())
		{
			return;
		}
		JsonObject payload = new JsonObject();
		payload.addProperty("channel", channel);
		// The player is on a Leagues world. The plugin reports only that fact — whether the clan has a
		// separate Leagues channel, and what a seasonal post looks like, is the server's decision, so
		// either can change without waiting for a plugin release. Carried as ambient state like the RSN
		// and account hash, so every notification path gets it without threading a flag through each.
		if (seasonal)
		{
			payload.addProperty("seasonal", true);
		}
		if (content != null && !content.isEmpty())
		{
			payload.addProperty("content", content);
		}
		if (facts != null)
		{
			payload.addProperty("kind", facts.kind);
			payload.add("facts", facts.facts);
		}

		String url = clanUrl("/api/plugin/notify");
		String payloadJson = payload.toString();
		// Read once: a retry, should this attempt fail, says the same thing as the same character.
		String rsn = currentRsn;
		String hash = accountHash;
		Request request = authedRequest(url, rsn, rsnHint, hash).post(notifyBody(payloadJson, png, filename)).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			// WARN, not debug. RuneLite logs at INFO, so both of these were invisible: a notification
			// that the server rejected looked exactly like one that was never sent, and the only
			// honest answer to "why didn't my 99 post" was that nobody could tell.
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Anvil: '{}' notification never reached the site: {}", channel, e.getMessage());
				keepForRetry(url, channel, payloadJson, png, filename, rsn, hash);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.warn("Anvil: the site refused a '{}' notification (HTTP {}).", channel, r.code());
						if (!RetryPolicy.isPermanent(r.code()))
						{
							keepForRetry(url, channel, payloadJson, png, filename, rsn, hash);
						}
						return;
					}
					// A destination disappearing between config refresh and send used to answer 204,
					// while a failed Discord fan-out answered {ok:false} with HTTP 200. Both looked
					// exactly like a successful post in the only log a player can share with us.
					if (r.code() == 204)
					{
						log.warn("Anvil: '{}' notification had no configured Discord destination.", channel);
						return;
					}
					// A successful older site may return no JSON contract. Success is still success.
					String ok = r.body() == null ? null : jsonString(jsonObject(r.body().string()), "ok");
					if (ok != null && !Boolean.parseBoolean(ok))
					{
						log.warn("Anvil: Discord refused every '{}' notification destination.", channel);
					}
				}
			}
		});
	}

	/** Notifications that failed for a reason that may clear wait here (NotifyOutbox); null = dropped as before. */
	private volatile NotifyOutbox notifyOutbox;

	void setNotifyOutbox(NotifyOutbox outbox)
	{
		this.notifyOutbox = outbox;
	}

	private static RequestBody notifyBody(String payloadJson, byte[] png, String filename)
	{
		if (png != null && png.length > 0)
		{
			return new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", payloadJson)
				.addFormDataPart("file", filename != null && !filename.isEmpty() ? filename : "image.png",
					RequestBody.create(PNG, png))
				.build();
		}
		return RequestBody.create(JSON, payloadJson);
	}

	/** Runs on an OkHttp callback thread: hand the failed notification to the outbox. */
	private void keepForRetry(String url, String channel, String payloadJson, byte[] png, String filename,
		String rsn, String hash)
	{
		NotifyOutbox outbox = notifyOutbox;
		if (outbox == null)
		{
			return;
		}
		NotifyOutbox.Item it = NotifyOutbox.newItem(System.currentTimeMillis());
		it.url = url;
		it.channel = channel;
		it.payload = payloadJson;
		it.filename = filename;
		it.rsn = rsn;
		it.accountHash = hash;
		it.account = DiskFiles.fingerprint(playerToken);
		outbox.enqueue(it, png);
	}

	/**
	 * Resend one queued notification as the character it was first sent for. Blocking; the outbox
	 * calls it on the OkHttp pool. Never throws.
	 */
	NotifyOutbox.Result sendQueuedNotification(NotifyOutbox.Item it, byte[] png)
	{
		String base = getApiUrl();
		if (!isConfigured() || base.isEmpty())
		{
			return NotifyOutbox.Result.RETRY; // paused, or between sign-ins: it can wait (or expire)
		}
		// Queued under another account's sign-in, or for another site: not this token's to send.
		if (!DiskFiles.fingerprint(playerToken).equals(it.account) || it.url == null || !it.url.startsWith(base + "/"))
		{
			return NotifyOutbox.Result.PERMANENT;
		}
		// No launcher hint: it names who is about to play NOW, not who the notification was for.
		try
		{
			return execute(httpClient, authedRequest(it.url, it.rsn, null, it.accountHash)
				.post(notifyBody(it.payload, png, it.filename)), (r, body) ->
			{
				if (r.isSuccessful())
				{
					log.info("Anvil: queued '{}' notification delivered", it.channel);
					return NotifyOutbox.Result.SENT;
				}
				return RetryPolicy.isPermanent(r.code()) ? NotifyOutbox.Result.PERMANENT : NotifyOutbox.Result.RETRY;
			});
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Queued '{}' notification still failing: {}", it.channel, e.getMessage());
			return NotifyOutbox.Result.RETRY;
		}
	}

	/** The last config poll was the site's "no clan for this account yet" (lib/pluginNoClan). */
	private volatile boolean lastConfigNoClan;

	/**
	 * Signed in, and the site says this person is in no clan. Not an error state: their stats are still
	 * theirs, and the stats route takes a push for a character the token owns (the site's account-only
	 * path), so the plugin keeps reporting — that's what makes the profile useful without a clan.
	 */
	public boolean signedInWithoutClan()
	{
		return isConfigured() && lastConfigNoClan;
	}

	// What the site can do, for someone the config can't tell: a person in no clan gets a 404 config
	// and so no `server.capabilities`. /api/version is public and tiny; read at most every 10 minutes,
	// only on that path, from the config poll (already off the EDT).
	private static final long VERSION_CAPS_TTL_MS = 10 * 60_000L;
	private volatile Set<String> versionCaps = Collections.emptySet();
	private volatile long versionCapsAt;

	/** A capability /api/version advertised (the no-clan fallback for {@link PluginConfigResponse#serverSupports}). */
	public boolean siteAdvertises(String capability)
	{
		return versionCaps.contains(capability);
	}

	private void refreshVersionCaps()
	{
		long now = System.currentTimeMillis();
		if (now - versionCapsAt < VERSION_CAPS_TTL_MS)
		{
			return;
		}
		versionCapsAt = now;
		VersionInfo info = getOrNull(plainRequest(CANONICAL_SITE + "/api/version").get(), VersionInfo.class,
			"version capabilities fetch");
		if (info != null)
		{
			versionCaps = info.capabilities == null ? Collections.emptySet() : new HashSet<>(info.capabilities);
		}
	}

	/** The part of /api/version the plugin reads. */
	static final class VersionInfo
	{
		List<String> capabilities;
	}

	/** GET /api/plugin/config — event, team, player and everything the client tracks. */
	public PluginConfigResponse fetchConfig() throws IOException
	{
		try
		{
			PluginConfigResponse parsed = etagGet(configUrl("/api/plugin/config"), PluginConfigResponse.class, polls, "Config fetch",
				ResponseDiskCache.CONFIG);
			lastConfigNoClan = false;
			return parsed;
		}
		catch (HttpStatusException e)
		{
			lastConfigNoClan = e.code == 404;
			if (lastConfigNoClan)
			{
				refreshVersionCaps();
			}
			throw e;
		}
	}

	/**
	 * GET /api/plugin/chat-patterns — the site's chat-line re-wordings (ChatPatterns). Global, so never
	 * clan-addressed. Null on any failure; a 304 hands back the cached object.
	 */
	ChatPatterns.OverridesResponse fetchChatPatterns()
	{
		return etagGetOrNull(rootUrl("/api/plugin/chat-patterns"), ChatPatterns.OverridesResponse.class, polls,
			"Chat patterns", ResponseDiskCache.CHAT_PATTERNS);
	}

	/** A non-2xx answer, from any call: every refusal this client throws is one, so callers can go by {@link #code}. */
	static class HttpStatusException extends IOException
	{
		final int code;

		HttpStatusException(String message, int code)
		{
			super(message);
			this.code = code;
		}
	}

	/** A bounded URL → {etag, parsed body} cache, for If-None-Match. */
	private static Map<String, Object[]> etagCache(int max)
	{
		return Collections.synchronizedMap(new LinkedHashMap<String, Object[]>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Object[]> eldest)
			{
				return size() > max;
			}
		});
	}

	// Conditional-GET caches. The config poll runs every 30s and a clan's board rarely changes between
	// polls, so the last ETag + parsed body per URL rides along as If-None-Match: a 304 reuses the cached
	// body and costs a few header bytes instead of the whole board. The roster gets its own cache so
	// paging back and forth never evicts the polls.
	private final Map<String, Object[]> polls = etagCache(16);
	private final Map<String, Object[]> trackedTiles = etagCache(TileTracker.MAX_PINS);

	/**
	 * Where the last good config and board are saved between sessions (ResponseDiskCache). Null until
	 * the plugin hands one over, and in tests — nothing is saved then.
	 */
	private volatile ResponseDiskCache diskCache;

	void setDiskCache(ResponseDiskCache diskCache)
	{
		this.diskCache = diskCache;
	}

	/**
	 * Load a saved answer into the conditional-GET cache, so the first poll of a session asks
	 * If-None-Match and an unchanged config or board comes back as a 304. Returns the parsed body for
	 * display, or null. Blocking (disk); call on the executor.
	 */
	<T> T seedFromDisk(ResponseDiskCache.Entry saved, Class<T> type)
	{
		if (saved == null)
		{
			return null;
		}
		try
		{
			T parsed = gson.fromJson(saved.body, type);
			if (parsed != null && saved.etag != null && saved.url.startsWith(getApiUrl()) && !getApiUrl().isEmpty())
			{
				polls.putIfAbsent(saved.url, new Object[]{saved.etag, parsed});
			}
			return parsed;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			log.debug("Saved answer unreadable: {}", e.getMessage());
			return null;
		}
	}

	private <T> T etagGet(String url, Class<T> type, Map<String, Object[]> cache, String label) throws IOException
	{
		return etagGet(url, type, cache, label, null);
	}

	/**
	 * An authed conditional GET: the cached body on a 304, else the parsed 2xx body. Throws
	 * {@link HttpStatusException} otherwise. A {@code persistAs} kind also saves a fresh body to disk.
	 */
	private <T> T etagGet(String url, Class<T> type, Map<String, Object[]> cache, String label, String persistAs) throws IOException
	{
		Request.Builder rb = authedRequest(url).get();
		Object[] hit = cache.get(url);
		if (hit != null)
		{
			rb.header("If-None-Match", (String) hit[0]);
		}
		return execute(readClient, rb, (response, text) ->
		{
			if (response.code() == 304 && hit != null)
			{
				return type.cast(hit[1]); // unchanged since the last poll — reuse it, no body transferred
			}
			if (!response.isSuccessful())
			{
				throw new HttpStatusException(label + " failed: HTTP " + response.code(), response.code());
			}
			T parsed = gson.fromJson(text, type);
			String etag = response.header("ETag");
			if (etag != null && parsed != null)
			{
				cache.put(url, new Object[]{etag, parsed});
			}
			ResponseDiskCache disk = diskCache;
			if (persistAs != null && disk != null && parsed != null)
			{
				disk.store(persistAs, url, etag, text, currentRsn != null ? currentRsn : rsnHint);
			}
			return parsed;
		});
	}

	/** {@link #etagGet} for the sidebar's reads: null on any failure. */
	private <T> T etagGetOrNull(String url, Class<T> type, Map<String, Object[]> cache, String label)
	{
		return etagGetOrNull(url, type, cache, label, null);
	}

	private <T> T etagGetOrNull(String url, Class<T> type, Map<String, Object[]> cache, String label, String persistAs)
	{
		try
		{
			return etagGet(url, type, cache, label, persistAs);
		}
		catch (IOException | JsonParseException e)
		{
			log.debug("{} failed: {}", label, e.getMessage());
			return null;
		}
	}

	/**
	 * One panel view ({@code plugin-ui}, {@link UiView}): {@code GET /api/plugin/ui?v=view&args}, plus
	 * {@code clan}, the clan the panel is on. The token and X-RSN go with it: "Compare with me" and the
	 * goals are about the character being played — except while that character is paused, when nothing
	 * names it. Null on any failure. Blocking; off the EDT.
	 */
	public JsonObject fetchUi(String view, Map<String, String> args, String clan)
	{
		HttpUrl.Builder url = HttpUrl.get(rootUrl("/api/plugin/ui")).newBuilder().addQueryParameter("v", view);
		args.forEach(url::addQueryParameter);
		if (clan != null && !clan.isEmpty())
		{
			url.addQueryParameter("clan", clan);
		}
		return getOrNull(uiRequest(url.build().toString()).get(), JsonObject.class, "panel view");
	}

	/** {@code POST /api/plugin/ui}: one of a view's actions, answered with the view to show next. */
	public JsonObject postUi(String act, Map<String, String> args, Map<String, String> fields)
	{
		JsonObject body = new JsonObject();
		body.addProperty("act", act);
		body.add("args", strings(args));
		body.add("fields", strings(fields));
		return getOrNull(uiRequest(rootUrl("/api/plugin/ui")).post(json(body)), JsonObject.class, "panel action");
	}

	private static JsonObject strings(Map<String, String> map)
	{
		JsonObject o = new JsonObject();
		map.forEach(o::addProperty);
		return o;
	}

	/** A page on the site this plugin talks to: a view's link names a path, never a host. */
	public String siteLink(String path)
	{
		HttpUrl base = HttpUrl.parse(getApiUrl().isEmpty() ? CANONICAL_SITE : getApiUrl());
		HttpUrl url = base == null ? null : base.resolve(path);
		return url == null ? CANONICAL_SITE : url.toString();
	}

	private Request.Builder uiRequest(String url)
	{
		return accountPaused ? publicRequest(url) : authedRequest(url);
	}

	/**
	 * Where to run a fetch a person is waiting on (a lookup, a compare, a log page).
	 *
	 * NOT RuneLite's injected ScheduledExecutorService: that is ONE thread shared by every plugin, so
	 * a blocking call queued there waits behind every other plugin's work and our own polls and
	 * uploads — a right-click lookup could sit for seconds behind a screenshot upload. OkHttp's
	 * dispatcher pool belongs to the client's own HTTP stack (the pool its async calls run on), so
	 * this adds no thread of ours and the shared thread stays free.
	 */
	public ExecutorService interactiveExecutor()
	{
		return httpClient.dispatcher().executorService();
	}

	/** {@code body} as a JSON object, or null when it isn't one. */
	static JsonObject jsonObject(String body)
	{
		try
		{
			JsonElement json = new JsonParser().parse(body);
			return json.isJsonObject() ? json.getAsJsonObject() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** A primitive member as a string, or null when {@code json} is null or the member isn't a primitive. */
	static String jsonString(JsonObject json, String key)
	{
		JsonElement e = json == null ? null : json.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}

	private static RequestBody json(JsonObject payload)
	{
		return RequestBody.create(JSON, payload.toString());
	}

	/**
	 * {@code GET /api/plugin/event/<id>/tile/<tileId>/progress} — every team's progress on one pinned
	 * tile (site capability "tile-tracker"). Null on any failure. Blocking.
	 */
	public TileTracker.Progress fetchTileProgress(int eventId, int tileId)
	{
		return !isConfigured() || eventId <= 0 || tileId <= 0 ? null
			: etagGetOrNull(clanUrl("/api/plugin/event/" + eventId + "/tile/" + tileId + "/progress"),
				TileTracker.Progress.class, trackedTiles, "tile progress fetch");
	}

	/**
	 * POST /api/upload — uploads a PNG screenshot, returns the image URL.
	 */
	public String uploadImage(byte[] pngBytes, String filename) throws IOException
	{
		MultipartBody multipart = new MultipartBody.Builder().setType(MultipartBody.FORM)
			.addFormDataPart("file", filename, RequestBody.create(PNG, pngBytes)).build();
		return execute(httpClient, authedRequest(clanUrl("/api/upload")).post(multipart), (r, body) ->
		{
			if (!r.isSuccessful())
			{
				throw new HttpStatusException("Image upload failed: HTTP " + r.code(), r.code());
			}
			return new JsonParser().parse(body).getAsJsonObject().get("url").getAsString();
		});
	}

