package com.anvil;

import com.google.gson.Gson;
import java.io.IOException;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * "Not my account": which characters this install sends nothing for, and that nothing does go out.
 */
public class AccountOptOutTest
{
	@Test
	public void matchesByHashOrName()
	{
		AccountOptOut set = AccountOptOut.EMPTY.with(12345L, "Sibling Main");
		assertTrue(set.contains(12345L, "Sibling Main"));
		assertTrue("renamed — the hash still knows it", set.contains(12345L, "New Name"));
		assertTrue("pre-login (no hash yet) — the name knows it", set.contains(-1L, "sibling main"));
		assertTrue(set.containsName("Sibling Main"));
		assertFalse("your own alts are untouched", set.contains(999L, "My Alt"));
	}

	@Test
	public void roundTripsAndUndoes()
	{
		AccountOptOut set = AccountOptOut.EMPTY.with(1L, "A").with(2L, "B");
		AccountOptOut back = AccountOptOut.parse(set.serialize());
		assertTrue(back.contains(1L, "A"));
		assertTrue(back.contains(2L, "B"));
		AccountOptOut undone = back.without(1L, "A");
		assertFalse(undone.contains(1L, "A"));
		assertTrue(undone.contains(2L, "B"));
		assertTrue(AccountOptOut.parse("").isEmpty());
		assertTrue(AccountOptOut.parse(null).isEmpty());
	}

	@Test
	public void storesDigestsNotTheHashOrName()
	{
		String stored = AccountOptOut.EMPTY.with(424242424242L, "Zezima").serialize();
		assertFalse(stored.contains("424242424242"));
		assertFalse(stored.toLowerCase().contains("zezima"));
	}

	@Test
	public void pausedClientSendsNothingWithTheToken() throws Exception
	{
		BingoApiClient client = new BingoApiClient(new Gson(), new OkHttpClient());
		client.configure("tok");
		client.setCurrentRsn("Sibling Main");
		assertTrue(client.isConfigured());

		client.setAccountPaused(true);
		assertFalse("every gated path goes quiet", client.isConfigured());
		assertTrue("but still signed in — the panel row stays", client.isSignedIn());

		// Anything that slips past a gate is refused before it touches the network. 127.0.0.1:9 is
		// the discard port: if the gate didn't fire we'd get a connect error, not this message.
		Request r = client.authedRequest("http://127.0.0.1:9/api/plugin/config").get().build();
		OkHttpClient http = client.httpClient;
		try
		{
			http.newCall(r).execute().close();
			fail("a paused account's request went out");
		}
		catch (IOException e)
		{
			assertTrue(e.getMessage(), e.getMessage().contains("Not my account"));
		}

		client.setAccountPaused(false);
		assertTrue(client.isConfigured());
		assertEquals("Sibling Main", client.getCurrentRsn());
	}

	@Test
	public void failsClosedWhileTheCharacterIsUnknown()
	{
		AccountOptOut none = AccountOptOut.EMPTY;
		AccountOptOut some = AccountOptOut.EMPTY.with(1L, "Sibling Main");
		assertFalse("nothing opted out: an install behaves as before", AnvilPlugin.shouldPauseAccount(none, null, -1L));
		assertTrue("opted-out character", AnvilPlugin.shouldPauseAccount(some, "Sibling Main", 1L));
		assertFalse("your own character", AnvilPlugin.shouldPauseAccount(some, "My Main", 2L));
		assertTrue("name/hash never loaded: can't tell, so closed", AnvilPlugin.shouldPauseAccount(some, null, -1L));
		assertTrue(AnvilPlugin.shouldPauseAccount(some, "My Main", -1L));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ActivityStatsTest
{
	/** A stand-in client: ids we set answer with their value, everything else reads 0. */
	private static IntUnaryOperator reader(Map<Integer, Integer> values)
	{
		return id -> values.getOrDefault(id, 0);
	}

	private static final IntUnaryOperator ZERO = id -> 0;

	@Test
	public void readsAVarbitBackedClueTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 47);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesElite"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(47), out.get("cluesElite"));
	}

	@Test
	public void readsAVarpBackedCounter()
	{
		Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.COLLECTION_COUNT, 548);
		varps.put(VarPlayerID.COLOSSEUM_GLORY, 12_400);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "colosseumGlory"), ZERO, reader(varps));

		assertEquals(Integer.valueOf(548), out.get("collectionsLogged"));
		assertEquals(Integer.valueOf(12_400), out.get("colosseumGlory"));
	}

	@Test
	public void cluesAllSumsEveryTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED, 1);
		varbits.put(VarbitID.COLLECTION_CLUES_EASY_COMPLETED, 2);
		varbits.put(VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED, 4);
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 8);
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 16);
		varbits.put(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, 32);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesAll"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(63), out.get("cluesAll"));
	}

	/** An unsynced collection log reads 0; sending it would be a request that changes nothing. */
	@Test
	public void dropsNonPositiveReads()
	{
		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "cluesAll", "cluesHard"), ZERO, ZERO);

		assertTrue(out.isEmpty());
	}

	/**
	 * The site sends every activity key the board tracks, including the rank-based ones it has no
	 * in-game counter for. Those must fall out here rather than push a wrong number.
	 */
	@Test
	public void skipsKeysTheClientCannotAnswer()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 9);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("lastManStanding", "pvpArena", "bhHunter", "riftsClosed", "soulWarsZeal", "cluesHard"),
			reader(varbits), ZERO);

		assertEquals(1, out.size());
		assertEquals(Integer.valueOf(9), out.get("cluesHard"));
		assertNull(out.get("lastManStanding"));
		assertNull(out.get("soulWarsZeal"));

		assertFalse(ActivityStats.isReadable("riftsClosed"));
		assertTrue(ActivityStats.isReadable("cluesHard"));
		assertTrue(ActivityStats.isReadable("cluesAll"));
	}

	@Test
	public void triggersOnlyOnIdsItReads()
	{
		assertTrue(ActivityStats.isTrigger(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, -1));
		assertTrue(ActivityStats.isTrigger(-1, VarPlayerID.COLLECTION_COUNT));
		assertFalse(ActivityStats.isTrigger(VarbitID.INSIDE_WILDERNESS, -1));
		// RuneLite's "this wasn't a varbit" / "this wasn't a varp" sentinel must never match.
		assertFalse(ActivityStats.isTrigger(-1, -1));
	}

	@Test
	public void readsNothingWhenTheBoardTracksNoActivities()
	{
		assertTrue(ActivityStats.read(null, ZERO, ZERO).isEmpty());
		assertTrue(ActivityStats.read(Collections.emptyList(), ZERO, ZERO).isEmpty());
	}
}

package com.anvil;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The highlight queue: what collapses, what survives a failed push, and what gets dropped when a
 * session outruns the site.
 *
 * <p>The behaviour worth defending is the collapsing. The game announces everything more than once —
 * a kill fires two loot events, a pet fires up to three chat lines — so a queue that took each
 * sighting at face value would put the same drop on the clan's feed twice.
 */
public class AnvilMomentsTest
{
	private static AnvilMoments.Moment drop(String source, int itemId, long at)
	{
		return new AnvilMoments.Moment("drop", itemId, "Tanzanite fang", 1, 3_100_000L, source, "npc", 210, at,
			AnvilMoments.keyFor("drop", source, itemId, at));
	}

	@Test
	public void theSameDropSeenTwiceIsOneEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// NpcLootReceived then LootReceived, a tick apart — one drop, not two.
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_000_600L));
		assertEquals(1, moments.size());
	}

	@Test
	public void theSameItemFromTheSameBossMinutesLaterIsANewEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_300_000L));
		assertEquals(2, moments.size());
	}

	@Test
	public void aPetIsNamedAfterTheFactWithoutBecomingASecondEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// The chat line announces a pet without saying which one; the collection-log line follows.
		String key = AnvilMoments.keyFor("pet", "Zulrah", null, 5_000L);
		moments.record(new AnvilMoments.Moment("pet", null, null, 1, null, "Zulrah", "npc", 210, 5_000L, key));
		assertTrue(moments.nameQueued(key, "Pet snakeling", 12921));

		assertEquals(1, moments.size());
		AnvilMoments.Moment queued = moments.nextBatch().get(0);
		assertEquals("Pet snakeling", queued.itemName);
		assertEquals(Integer.valueOf(12921), queued.itemId);
		// Naming must not disturb what the moment already knew.
		assertEquals("Zulrah", queued.source);
		assertEquals(Integer.valueOf(210), queued.kc);
	}

	@Test
	public void namingSomethingThatIsNotQueuedDoesNothing()
	{
		AnvilMoments moments = new AnvilMoments();
		assertFalse(moments.nameQueued("nothing-here", "Beaver", 13322));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchStaysQueuedUntilItIsConfirmed()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		List<AnvilMoments.Moment> batch = moments.nextBatch();
		assertEquals(1, batch.size());
		// The push failed — nothing was confirmed, so nothing is lost.
		assertEquals(1, moments.size());
		moments.onSent(batch);
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchIsCappedAndTheRestWaits()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.BATCH + 5; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.BATCH, moments.nextBatch().size());
	}

	@Test
	public void anOverflowingQueueDropsItsOldestNotItsNewest()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.MAX_QUEUED + 10; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.MAX_QUEUED, moments.size());
		// The pet you just got must not be evicted to keep a loot pile from an hour ago.
		long newest = (AnvilMoments.MAX_QUEUED + 9) * 60_000L;
		boolean holdsNewest = false;
		for (AnvilMoments.Moment m : moments.nextBatch())
		{
			holdsNewest |= m.at == newest;
		}
		// nextBatch() returns the oldest first, so check the whole queue rather than the batch head.
		while (!holdsNewest && !moments.isEmpty())
		{
			List<AnvilMoments.Moment> batch = moments.nextBatch();
			for (AnvilMoments.Moment m : batch)
			{
				holdsNewest |= m.at == newest;
			}
			moments.onSent(batch);
		}
		assertTrue(holdsNewest);
	}

	@Test
	public void aKeylessMomentIsRefused()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(new AnvilMoments.Moment("drop", 12922, "Tanzanite fang", 1, 1L, "Zulrah", "npc", 1, 0L, null));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void resetForgetsEverything()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.reset();
		assertTrue(moments.isEmpty());
	}

	@Test
	public void deathsFromDifferentKillersDoNotShareAKey()
	{
		String olm = AnvilMoments.keyFor("death", "Great Olm", null, 1_000_000L);
		String vasa = AnvilMoments.keyFor("death", "Vasa Nistirio", null, 1_000_000L);
		assertFalse(olm.equals(vasa));
		// An unknown killer still produces a usable key rather than a null one — a death nobody can
		// attribute is still a death, and the site is what decides it belongs nowhere.
		assertTrue(AnvilMoments.keyFor("death", null, null, 1_000_000L).startsWith("death|"));
	}

	@Test
	public void aCombatTaskCarriesItsTaskAndTierAndNothingElse()
	{
		AnvilMoments.Moment m = AnvilMoments.Moment.combatTask("Perfect Zulrah", "Master", 1_000_000L);
		assertEquals("ca", m.kind);
		assertEquals("Perfect Zulrah", m.taskName);
		assertEquals("Master", m.tier);
		// No item, no price, no source: which boss it belongs to is the site's answer, out of its own
		// dataset, so inventing one here would only be something to disagree with later.
