package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the Combat Achievement completion chat-line parsing. CA bingo tiles credit off this
 * line (including recompletions fired by the in-game "Repeat completion" setting, which append a
 * " (N points)" suffix) — if Jagex changes the string a test here goes red and tells you CA tile
 * auto-detect broke (manual site submission is the fallback).
 */
public class CombatTaskLineTest
{
	/** Runs a line through the same parse the plugin does: match, then strip the points suffix. */
	private static String[] parse(String line)
	{
		Matcher m = TestPatterns.get("ca.task").matcher(line);
		if (!m.find())
		{
			return null;
		}
		String task = AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim();
		return new String[]{m.group(1), task};
	}

	@Test
	public void parsesFirstCompletion()
	{
		String[] r = parse("Congratulations, you've completed an Elite combat task: Whack-a-Mole.");
		assertEquals("Elite", r[0]);
		assertEquals("Whack-a-Mole", r[1]);
	}

	@Test
	public void parsesRepeatCompletionWithPointsSuffix()
	{
		// The in-game "Repeat completion" setting re-fires the line with a points suffix.
		String[] r = parse("Congratulations, you've completed a Master combat task: Nylocas, On the Rocks (5 points).");
		assertEquals("Master", r[0]);
		assertEquals("Nylocas, On the Rocks", r[1]);
	}

	@Test
	public void parsesSinglePointSuffixAndAArticle()
	{
		String[] r = parse("Congratulations, you've completed an Easy combat task: Noxious Foe (1 point).");
		assertEquals("Easy", r[0]);
		assertEquals("Noxious Foe", r[1]);
	}

	@Test
	public void tierResolvesForEveryGroupOneValue()
	{
		String[] r = parse("Congratulations, you've completed a Grandmaster combat task: The Worst Ranged Weapon.");
		assertEquals(CombatAchievementTier.GRANDMASTER, CombatAchievementTier.byName(r[0]));
	}

	@Test
	public void ignoresUnrelatedCongratulationsLines()
	{
		assertFalse(TestPatterns.get("ca.task").matcher(
			"Congratulations, you've just advanced your Mining level. You are now level 99.").find());
	}

	@Test
	public void keepsParenthesesThatAreNotAPointsSuffix()
	{
		// Task names can legitimately end in a parenthesised qualifier — only "(N points)" strips.
		String[] r = parse("Congratulations, you've completed an Elite combat task: Chambers of Xeric: CM (Solo) Speed-Chaser.");
		assertEquals("Chambers of Xeric: CM (Solo) Speed-Chaser", r[1]);
	}

	@Test
	public void matcherRequiresTierWord()
	{
		assertTrue(TestPatterns.get("ca.task").matcher(
			"Congratulations, you've completed a Hard combat task: Whack-a-Mole.").find());
		assertFalse(TestPatterns.get("ca.task").matcher(
			"you've completed a combat task").find());
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * What killed us, as opposed to what we were killing.
 *
 * <p>The feed used to name the last thing we landed a hit on, which produced "died to Abyssal
 * portal", "died to Volatile earth" and "died to Jug" — three things a player attacked and none
 * that killed anybody. A hitsplat carries no attacker, so the inference runs off who had us
 * TARGETED when we last took damage.
 */
public class DeathAttributionTest
{
	private static final long T = 1_000_000L;

	@Test
	public void namesTheThingAttackingUsRatherThanTheThingWeAttacked()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("The Whisperer", T);
		d.tookDamage(T + 100);
		// We spent the fight hitting a mechanic. It did not kill us.
		assertEquals("The Whisperer", d.killer("Volatile earth", T + 200));
	}

	@Test
	public void aMutualFightWinsOverAnythingElseOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Tekton", T);
		d.targetedUs("Abyssal portal", T + 50); // more recent, but not who we were fighting
		d.tookDamage(T + 100);
		assertEquals("Tekton", d.killer("Tekton", T + 200));
	}

	@Test
	public void otherwiseTheThingThatJustTurnedOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Guardian", T);
		d.targetedUs("Vasa Nistirio", T + 500);
		d.tookDamage(T + 600);
		// We were hitting neither; the newest acquisition is the one that finished it.
		assertEquals("Vasa Nistirio", d.killer("Muttadile", T + 700));
	}

	@Test
	public void reAcquiringUsRefreshesTheClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Nylocas Ischyros", T);
		d.targetedUs("Nylocas Toxobolos", T + 100);
		d.targetedUs("Nylocas Ischyros", T + 900); // switched back onto us
		d.tookDamage(T + 950);
		assertEquals("Nylocas Ischyros", d.killer(null, T + 1_000));
	}

	@Test
	public void somethingThatStoppedAttackingUsIsNotASuspect()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Zulrah", T);
		d.tookDamage(T + 100);
		d.stoppedTargetingUs("Zulrah");
		assertNull(d.killer("Zulrah", T + 200));
	}

	@Test
	public void nothingOnUsIsAnsweredWithNothing()
	{
		// A mechanic, a fall, poison after the fight. Naming what we were hitting is exactly the bug.
		DeathAttribution d = new DeathAttribution();
		d.tookDamage(T);
		assertNull(d.killer("Jug", T + 100));
	}

	@Test
	public void damageTooOldToBeThisDeathNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		assertNull(d.killer("Vorkath", T + 60_000));
	}

	@Test
	public void neverHavingTakenDamageNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void clearingEndsEveryClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		d.clear();
		assertEquals(0, d.attackerCount());
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void theAttackerListCannotGrowWithoutBound()
	{
		DeathAttribution d = new DeathAttribution();
		for (int i = 0; i < 200; i++)
		{
			d.targetedUs("Attacker " + i, T + i);
		}
		// Capped, and it is the OLDEST that get dropped — the newest arrivals are the suspects.
		assertEquals(24, d.attackerCount());
		d.tookDamage(T + 500);
		assertEquals("Attacker 199", d.killer(null, T + 600));
	}

	@Test
	public void blankNamesAreIgnoredRatherThanStored()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs(null, T);
		d.targetedUs("", T);
		d.tookDamage(T);
		assertEquals(0, d.attackerCount());
		assertNull(d.killer(null, T + 100));
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static com.anvil.DeviceSignIn.isConfiguredHomeUrl;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The sign-in browser pin: only the CONFIGURED home origin + /link-device may ever open (§8 shape,
 * anchored to the member-typed Site URL instead of a hardcoded host). */
public class DeviceSignInTest
{
	private static final String HOME = "https://clan.anvilosrs.com";

	@Test
	public void acceptsOwnLinkDevicePage()
	{
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device"));
		assertTrue(isConfiguredHomeUrl(HOME, HOME + "/link-device?code=ABCD-EFGH"));
	}

	@Test
	public void refusesForeignHosts()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com.evil.com/link-device"));
	}

	@Test
	public void refusesLookalikeAuthorityTricks()
	{
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com@evil.com/link-device"));
		assertFalse(isConfiguredHomeUrl(HOME, "https://clan.anvilosrs.com:8443/link-device")); // port mismatch
	}

	@Test
	public void refusesOtherPathsOnOwnHost()
	{
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/"));
		assertFalse(isConfiguredHomeUrl(HOME, HOME + "/profile"));
	}

	@Test
	public void refusesSchemeDowngrade()
	{
		// A https home never opens a http page; a deliberate http dev home may open its own http page.
		assertFalse(isConfiguredHomeUrl(HOME, "http://clan.anvilosrs.com/link-device"));
		assertTrue(isConfiguredHomeUrl("http://localhost:3000", "http://localhost:3000/link-device"));
	}

	@Test
	public void refusesGarbage()
	{
		assertFalse(isConfiguredHomeUrl(HOME, null));
		assertFalse(isConfiguredHomeUrl(HOME, ""));
		assertFalse(isConfiguredHomeUrl(HOME, "javascript:alert(1)"));
		assertFalse(isConfiguredHomeUrl(null, HOME + "/link-device"));
	}

	@Test
	public void cancelledFlowRunsNoFurtherSteps()
	{
		// The flow polls on RuneLite's shared executor, which outlives the plugin; a cancel at
		// shutdown must leave every queued step a no-op (no request, no callback).
		List<Runnable> queued = new ArrayList<>();
		List<Object> callbacks = new ArrayList<>();
		DeviceSignIn flow = new DeviceSignIn(null, url -> true, (step, delayMs) -> queued.add(step));
		flow.run(callbacks::add, callbacks::add);
		flow.cancel();
		for (Runnable step : new ArrayList<>(queued))
		{
			step.run();
		}
		assertEquals(1, queued.size());
		assertTrue(callbacks.isEmpty());
	}
}

package com.anvil;

import com.google.gson.Gson;
import java.lang.reflect.Constructor;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The on-disk stores went unexercised for a while (they never got their folders), so whatever users
 * have lying around — no folder, an empty one, a half-written file — must read as "nothing there".
 */
public class DiskFilesTest
{
	private Path tmp;
	private Filepath root;

	@Before
	public void setUp() throws Exception
	{
		tmp = Files.createTempDirectory("anvil-diskfiles");
		// Filepath has no public way in outside the client; a test-only reflective root.
		Constructor<Filepath> c = Filepath.class.getDeclaredConstructor(Path.class, Path.class);
		c.setAccessible(true);
		root = c.newInstance(tmp, tmp);
	}

	@After
	public void tearDown() throws Exception
	{
		root.deleteRecursively();
	}

	@Test
	public void absentEmptyAndTruncatedFilesReadAsNothing() throws Exception
	{
		Gson gson = new Gson();
		Filepath dir = root.joinSegment("missing");
		assertTrue(DiskFiles.listFiles(dir, n -> true).isEmpty());
		assertTrue(DiskFiles.listFiles(null, n -> true).isEmpty());
		assertNull(DiskFiles.readJson(gson, dir.joinSegment("x.json"), PushStash.Data.class));
		assertNull(DiskFiles.readJson(gson, null, PushStash.Data.class));

		Filepath empty = root.joinSegment("empty.json");
		empty.write(new byte[0]);
		assertNull(DiskFiles.readJson(gson, empty, PushStash.Data.class));
		Filepath cut = root.joinSegment("cut.json");
		cut.write("{\"savedAt\": 5, \"kc\": {\"Zul");
		assertNull(DiskFiles.readJson(gson, cut, PushStash.Data.class));
	}

	@Test
	public void listFilesIsOneLevelAndFiltersByName() throws Exception
	{
		root.joinSegment("a.json").write("{}");
		root.joinSegment("b.png").write("x");
		Filepath sub = root.joinSegment("sounds");
		sub.createDirectories();
		sub.joinSegment("c.json").write("{}");
		List<Filepath> json = DiskFiles.listFiles(root, n -> n.endsWith(".json"));
		assertEquals(1, json.size());
		assertEquals("a.json", json.get(0).getFileName());
	}

	@Test
	public void pendingStoreSkipsBrokenFilesAndRoundTrips() throws Exception
	{
		PendingSubmissionStore store = new PendingSubmissionStore(new Gson());
		store.setRoot(root.joinSegment("pending"));
		assertTrue(store.loadAll().isEmpty());

		PendingSubmissionStore.PendingSubmission p = new PendingSubmissionStore.PendingSubmission();
		p.tileId = 7;
		p.timestamp = System.currentTimeMillis();
		p.label = "Vorkath head";
		assertNotNull(store.save(p, new byte[]{1, 2, 3}));
		root.joinSegment("pending").joinSegment("1-1.json").write(new byte[0]);
		root.joinSegment("pending").joinSegment("2-2.json").write("{\"tileId\": 2, \"lab");

		List<PendingSubmissionStore.PendingSubmission> all = store.loadAll();
		assertEquals(1, all.size());
		assertEquals("Vorkath head", all.get(0).label);
		assertEquals(3, store.readScreenshot(all.get(0)).length);
	}

	@Test
	public void stashAndCacheTreatCorruptFilesAsNothingSaved() throws Exception
	{
		Gson gson = new Gson();
		PushStash stash = new PushStash(gson);
		stash.setDir(root.joinSegment("outbox"));
		assertNull(stash.take("k", 0));
		root.joinSegment("outbox").joinSegment("pushes-k.json").write("{\"savedAt\":");
		assertNull(stash.take("k", 0));
		stash.clearAll();

		ResponseDiskCache cache = new ResponseDiskCache(gson);
		cache.setDir(root.joinSegment("cache"));
		cache.switchAccount("token");
		assertNull(cache.load(ResponseDiskCache.CONFIG));
		cache.store(ResponseDiskCache.CONFIG, "u", "e", "{}", null);
		assertEquals("{}", cache.load(ResponseDiskCache.CONFIG).body);
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Luck / troll classification for drop posts — the difference between "spooned" and "finally".
 */
public class DropLuckTest
{
	private static final long BIG_VALUE = 50_000_000L;

	@Test
	public void obtainedShareFollowsTheDropRate()
	{
		// At exactly 1/rate kills, ~63% of players have it (1 - 1/e).
		assertEquals(0.632, DropLuck.obtainedShare(1.0 / 512, 512), 0.005);
		// A single kill at 1/512 is just the drop rate.
		assertEquals(1.0 / 512, DropLuck.obtainedShare(1.0 / 512, 1), 1e-9);
		// Missing inputs never blow up.
		assertEquals(0.0, DropLuck.obtainedShare(0, 100), 1e-9);
		assertEquals(0.0, DropLuck.obtainedShare(1.0 / 512, 0), 1e-9);
	}

	@Test
	public void earlyDropsAreSpoonedAndLongGrindsAreDry()
	{
		// 1/512 on the 20th kill: only ~4% of players are there yet.
		assertEquals(DropLuck.Verdict.SPOONED, DropLuck.classify(1.0 / 512, 20));
		// ~200 kills in: ahead of the pack, not miraculous.
		assertEquals(DropLuck.Verdict.LUCKY, DropLuck.classify(1.0 / 512, 200));
		// Around the drop rate: unremarkable.
		assertEquals(DropLuck.Verdict.TYPICAL, DropLuck.classify(1.0 / 512, 500));
		// Triple the rate: almost everyone had it by now.
		assertEquals(DropLuck.Verdict.DRY, DropLuck.classify(1.0 / 512, 1500));
	}

	@Test
	public void classifyNeedsBothARateAndAKillCount()
	{
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(null, 500));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, null));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, 0));
	}

	@Test
	public void trollsAreRareRollsOnWorthlessItems()
	{
		// A 1/10,000 roll on a ~35k item — the joke drop.
		assertTrue(DropLuck.isTrollDrop(1.0 / 10_000, 35_000, 10_000));
		// Same rarity, real money: just a rare drop.
		assertFalse(DropLuck.isTrollDrop(1.0 / 10_000, 5_000_000, 10_000));
		// Cheap but not rare enough to be funny — this is the herb spam we don't want.
		assertFalse(DropLuck.isTrollDrop(1.0 / 2_000, 5_000, 10_000));
		// Qualified on value alone (no rate known).
		assertFalse(DropLuck.isTrollDrop(null, 5_000, 10_000));
	}

	@Test
	public void earnedAwardsAreNeverCalledSpooned()
	{
		assertTrue(DropLuck.isEarnedAward("Infernal cape"));
		assertTrue(DropLuck.isEarnedAward("Dizana's quiver"));
		assertTrue(DropLuck.isEarnedAward("Fire cape"));
		assertFalse(DropLuck.isEarnedAward("Twisted bow"));

		// Even a 1-KC Inferno clear gets no "spooned" line — it was earned, not rolled.
		assertFalse(DropLuck.deservesSpoonLine("Infernal cape", 0, 1.0 / 1, 1, BIG_VALUE));
		// A genuine early roll does.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 20, BIG_VALUE));
		// A dry grind doesn't get called lucky just because the item is worth a lot... unless it's
		// worth *so* much that the drop is a moment on its own.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 1500, BIG_VALUE));
		assertFalse(DropLuck.deservesSpoonLine("Dragon spear", 35_000, 1.0 / 512, 1500, BIG_VALUE));
		// No rate/KC to judge by: value decides.
		assertFalse(DropLuck.deservesSpoonLine("Rune platebody", 38_000, null, null, BIG_VALUE));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the drop-attribution chat-line parsing against the REAL in-game message. This line is
 * the ONLY loot signal for drops that bypass both loot events (Maggot King's spill-out uniques),
 * so if Jagex changes the string a test here goes red and tells you drop auto-detect broke for
 * those bosses (manual site submission is the fallback).
 */
public class DropNotificationLineTest
{
	@Test
	public void parsesMaggotKingSpillLine()
	{
		// Exact line observed in game, following "Some loot spills out alongside the Maggot
		// King's guts. Yuck."
		Matcher m = TestPatterns.get("drop.personal").matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void parsesQuantityPrefixAndTrailingPeriod()
	{
		Matcher m = TestPatterns.get("drop.personal").matcher(
			"Nisbro received a drop: 1,500 x Cannonball (Maggot King).");
		assertTrue(m.matches());
		assertEquals("1,500", m.group(2));
		assertEquals("Cannonball", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void keepsParenthesesInsideItemNames()
	{
		// Greedy item group: only the LAST parenthetical is the source.
		Matcher m = TestPatterns.get("drop.personal").matcher(
			"Nisbro received a drop: Rune platebody (g) (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void ignoresClanBroadcastVariant()
	{
		// The CLAN_MESSAGE broadcast carries a value and a "from <source>" suffix. The personal
		// pattern must not match it — the broadcast has its own pattern (below) whose handler is
		// recipient-checked, and a personal-pattern match would mis-parse the source group.
		assertFalse(TestPatterns.get("drop.personal").matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.").matches());
	}

	@Test
	public void parsesClanBroadcastVariant()
	{
		// Exact clan broadcast observed in game alongside (and independently of) the personal
		// line — the fallback signal when a member's in-game loot notifications are off.
		Matcher m = TestPatterns.get("drop.clan_broadcast").matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastKeepsParenthesesInsideItemNames()
	{
		Matcher m = TestPatterns.get("drop.clan_broadcast").matcher(
			"Nisbro received a drop: Rune platebody (g) (39,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastDoesNotMatchPersonalLine()
	{
		// The personal line has no "(N coins) from" tail — each pattern matches only its own
		// variant so one chat line can never be parsed twice by both handlers.
		assertFalse(TestPatterns.get("drop.clan_broadcast").matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)").matches());
	}

	@Test
	public void aChestsItemLinesAreReadWithoutASource()
	{
		Matcher plain = TestPatterns.get("drop.plain").matcher("Drenvox received a drop: Dagon'hai robe bottom");
		assertTrue(plain.matches());
		assertEquals("Drenvox", plain.group(1));
		assertEquals("Dagon'hai robe bottom", plain.group(3));

		Matcher stack = TestPatterns.get("drop.plain").matcher("Drenvox received a drop: 581 x Iron ore");
		assertTrue(stack.matches());
		assertEquals("581", stack.group(2));
		assertEquals("Iron ore", stack.group(3));

		Matcher valuable = TestPatterns.get("drop.valuable").matcher("Valuable drop: Dagon'hai robe bottom (573,719 coins)");
		assertTrue(valuable.matches());
		assertEquals("Dagon'hai robe bottom", valuable.group(2));

		Matcher untradeable = TestPatterns.get("drop.valuable").matcher("Untradeable drop: Dagon'hai hat");
		assertTrue(untradeable.matches());
		assertEquals("Dagon'hai hat", untradeable.group(2));
	}

	@Test
	public void theClansPetBroadcastNamesThePet()
	{
		Matcher m = AnvilPlugin.CLAN_PET_BROADCAST_PATTERN.matcher(
			"Biggie OG has a funny feeling like he's being followed: Dom at 519 levels from Doom of Mokhaiotl.");
		assertTrue(m.matches());
		assertEquals("Biggie OG", m.group(1));
		assertEquals("Dom", m.group(2));

		Matcher dupe = AnvilPlugin.CLAN_PET_BROADCAST_PATTERN.matcher(
			"Kayle has a funny feeling like she would have been followed: Baby mole at 412 killcount.");
		assertTrue(dupe.matches());
		assertEquals("Baby mole", dupe.group(2));

		Matcher pack = AnvilPlugin.CLAN_PET_BROADCAST_PATTERN.matcher(
			"Zezima feels something weird sneaking into their backpack: Heron at 13,034,431 XP.");
		assertTrue(pack.matches());
		assertEquals("Heron", pack.group(2));

		// The Unsired's orphan has its own wording.
		Matcher orphan = AnvilPlugin.CLAN_PET_BROADCAST_PATTERN.matcher(
			"Kayle feels like she's acquired something special: Abyssal orphan");
		assertTrue(orphan.matches());
		assertEquals("Kayle", orphan.group(1));
		assertEquals("Abyssal orphan", orphan.group(2));

		// A drop line is not a pet line.
		assertFalse(AnvilPlugin.CLAN_PET_BROADCAST_PATTERN.matcher("Zezima received a drop: Dragon claws").matches());
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Naming a drop's source, and reading the server's facts about it.
 */
public class DropSourceTest
{
	private static PluginConfigResponse.DropFacts facts()
	{
		PluginConfigResponse.DropFacts f = new PluginConfigResponse.DropFacts();
		f.pets = new HashMap<>();
		f.guaranteed = new HashMap<>();
		return f;
	}

	private static PluginConfigResponse.DropFacts.Pet pet(String kind, String... sources)
	{
		PluginConfigResponse.DropFacts.Pet p = new PluginConfigResponse.DropFacts.Pet();
		p.kind = kind;
		p.sources = Arrays.asList(sources);
		return p;
	}

	// ---- guaranteed drops -------------------------------------------------------------------

	@Test
	public void aGuaranteedDropIsRecognisedFromTheSourceThatOwesIt()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("ancient blood ornament kit", Arrays.asList("duke sucellus", "vardorvis"));
		assertTrue(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "Duke Sucellus"));
		assertTrue(DropSource.isGuaranteed(f, "ANCIENT BLOOD ORNAMENT KIT", "vardorvis"));
		// Same item, a source that does not owe it: still a real roll.
		assertFalse(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "The Whisperer"));
	}

	@Test
	public void aStarSourceMeansWhereverItDrops()
	{
		// What a clan override that named no sources stores.
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("some kit", Collections.singletonList("*"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", "Anything"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", null));
	}

	@Test
	public void anOlderSiteKnowsNothingAndChangesNothing()
	{
		assertFalse(DropSource.isGuaranteed(null, "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), null, "Duke Sucellus"));
	}

	// ---- pets -------------------------------------------------------------------------------

	@Test
	public void aPetComesFromItsOwnBossNotFromWhateverDroppedLootLast()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("baby mole", pet("npc", "Giant Mole"));
		// The client had just seen loot from something else entirely — a stray kill on the way out.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", "Hill Giant", null));
		// And with nothing observed at all, which is the skilling-adjacent case.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", null, null));
	}

	@Test
	public void whatTheClientSawWinsWhenItIsOneOfTheRealSources()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "vet'ion", null));
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "Calvar'ion", null));
	}

	@Test
	public void severalSourcesAndNoSightingFallBackToWhereTheyActuallyGrind()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		Map<String, Integer> kc = new HashMap<>();
		kc.put("calvar'ion", 12);
		kc.put("vet'ion", 940);
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, kc));
		// No kills recorded anywhere: the first listed source beats naming nothing.
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, null));
	}

	@Test
	public void aSkillingPetHasNoMonsterAndDoesNotBorrowOne()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("beaver", pet("skill"));
		// Whatever loot the client saw, a Beaver did not come from it.
		assertNull(DropSource.resolvePetSource(f, "Beaver", "Hill Giant", null));
	}

	@Test
	public void anUnknownPetKeepsWhateverTheClientSaw()
	{
		// A pet released after the site's last dataset regen: the old guess is still the best there
		// is, so nothing gets worse while the server catches up.
		assertEquals("New Boss", DropSource.resolvePetSource(facts(), "Newpet", "New Boss", null));
		assertEquals("New Boss", DropSource.resolvePetSource(null, "Newpet", "New Boss", null));
	}

	@Test
	public void wikiVariantNamesMatchTheBareInGameName()
	{
		assertEquals("Armoured zombie", DropSource.inGameNpcName("Armoured zombie (Zemouregal's Fort)"));
		assertEquals("TzKal-Zuk", DropSource.inGameNpcName("TzKal-Zuk"));
		java.util.List<String> npcs = java.util.Collections.singletonList("Armoured zombie (Zemouregal's Fort)");
		assertTrue(DropSource.sourceMatches(npcs, "Armoured zombie"));
		assertFalse(DropSource.sourceMatches(npcs, "Zombie"));
		assertFalse(DropSource.sourceMatches(npcs, null));
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** Naming the duplicates the game won't name — and refusing to guess when it can't be sure. */
public class DuplicateInferenceTest
{
	private static PluginConfigResponse.DropFacts.Pet pet(String kind, String skill, String... sources)
	{
		PluginConfigResponse.DropFacts.Pet p = new PluginConfigResponse.DropFacts.Pet();
		p.kind = kind;
		p.skill = skill;
		p.sources = Arrays.asList(sources);
		return p;
	}

	private static PluginConfigResponse.DropFacts facts()
	{
		PluginConfigResponse.DropFacts f = new PluginConfigResponse.DropFacts();
		f.pets = new HashMap<>();
		f.pets.put("vorki", pet("npc", null, "Vorkath"));
		f.pets.put("olmlet", pet("event", null, "Chambers of Xeric", "Chambers of Xeric Challenge Mode"));
		f.pets.put("rock golem", pet("skill", "Mining"));
		f.pets.put("heron", pet("skill", "Fishing"));
		// Two pets from one source: no single answer.
		f.pets.put("pet a", pet("npc", null, "Shared Boss"));
		f.pets.put("pet b", pet("npc", null, "Shared Boss"));
		return f;
	}

	@Test
	public void aBossNamesItsPet()
	{
		assertEquals("vorki", DuplicateInference.petForSource(facts(), "vorkath"));
		assertEquals("olmlet", DuplicateInference.petForSource(facts(), "Chambers of Xeric Challenge Mode"));
	}

	@Test
	public void aSkillNamesItsPet()
	{
		assertEquals("rock golem", DuplicateInference.petForSkill(facts(), "Mining"));
		assertNull(DuplicateInference.petForSkill(facts(), "Cooking"));
	}

	@Test
	public void ambiguityIsNotAnAnswer()
	{
		assertNull(DuplicateInference.petForSource(facts(), "Shared Boss"));
		assertNull(DuplicateInference.petForSource(facts(), "Goblin"));
		assertNull(DuplicateInference.petForSource(null, "Vorkath"));
		PluginConfigResponse.DropFacts empty = new PluginConfigResponse.DropFacts();
		empty.pets = Collections.emptyMap();
		assertNull(DuplicateInference.petForSkill(empty, "Mining"));
	}

	@Test
	public void championScrollsComeFromOneMonsterEach()
	{
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_GOBLIN), DuplicateInference.championScrollFor("Goblin"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_HOBGOBLIN), DuplicateInference.championScrollFor("Hobgoblin"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_GIANT), DuplicateInference.championScrollFor("Hill Giant"));
		assertEquals(Integer.valueOf(ItemID.CHAMPIONS_CHALLENGE_LESSERDEMON), DuplicateInference.championScrollFor("Lesser demon"));
		assertNull(DuplicateInference.championScrollFor("Greater demon"));
		assertNull(DuplicateInference.championScrollFor(null));
	}
}

package com.anvil;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client setting a live board silently depends on.
 *
 * <p>A switch the member is not looking at turns their event off, and the board gives them no way to
 * tell. The in-game loot-drop line is what corpse-boss loot credits off, and the reminder to enable
 * it used to be gated on clan rare-drop POSTS being on, which has nothing to do with whether the
 * board needs it.</p>
 *
 * <p>There used to be a second one here: "Auto Submit Drops" governed every tile kind and the stat
 * pushes, not just drops, so one flick of it played a whole bingo for nothing — and the nudge was
 * the apology for a switch that should not have existed. The setting is gone, and submitting is
 * simply what the plugin does, so the nudge went with it.</p>
 *
 * <p>Asked only while an event is actually running: a plugin that lectures about settings for
 * something that is not happening is noise, and noise is what gets a nudge ignored.</p>
 */
public class EventNudgeTest
{
	private static PluginConfigResponse live()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.name = "July Bingo";
		cfg.event.startDate = "2020-01-01T00:00:00.000Z";
		return cfg;
	}

	private static PluginConfigResponse notStarted()
	{
		PluginConfigResponse cfg = live();
		cfg.event.startDate = "2099-01-01T00:00:00.000Z";
		return cfg;
	}

	@Test
	public void aBoardWithDropTilesNeedsTheInGameDropLine()
	{
		PluginConfigResponse cfg = live();
		cfg.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void soDoesOneWithValueTiles()
	{
		// Same signal, same reason: a haul from a corpse boss reaches neither tile kind without it.
		PluginConfigResponse cfg = live();
		cfg.trackedValues = Collections.singletonList(new PluginConfigResponse.TrackedValue());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void aBoardWithNeitherIsLeftAlone()
	{
		assertFalse("a KC-only board never reads that line", AnvilPlugin.eventNeedsDropLines(live()));
		assertFalse(AnvilPlugin.eventNeedsDropLines(null));

		PluginConfigResponse upcoming = notStarted();
		upcoming.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertFalse("not until it starts", AnvilPlugin.eventNeedsDropLines(upcoming));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The first request must carry both halves of identity or roster-first linking falls back to review. */
public class IdentityStampTest
{
	@Test
	public void waitsForBothRsnAndAccountHash()
	{
		assertFalse(AnvilPlugin.identityReady(null, 42L));
		assertFalse(AnvilPlugin.identityReady("", 42L));
		assertFalse(AnvilPlugin.identityReady("Hells Taco", -1L));
		assertTrue(AnvilPlugin.identityReady("Hells Taco", 42L));
	}

	@Test
	public void spotsAnInGameRenameButNotAMissingName()
	{
