package com.anvil;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class VestigeRollsTest
{
	private static PluginConfigResponse.RollTable duke()
	{
		PluginConfigResponse.RollTable t = new PluginConfigResponse.RollTable();
		t.boss = "Duke Sucellus";
		// Virtus ×3, chromium ingot, Magus vestige, Eye of the duke.
		t.rollItemIds = Arrays.asList(26241, 26243, 26245, 28276, 28281, 28321);
		t.vestigeItemId = 28281;
		t.vestigeName = "Magus vestige";
		t.rollsPerVestige = 3;
		return t;
	}

	@Test
	public void countsRollsAndCallsTheVestigeOneAhead()
	{
		VestigeRolls v = new VestigeRolls();
		VestigeRolls.Result r1 = v.record(duke(), 28276); // chromium ingot
		assertEquals(1, r1.state.rolls);
		assertFalse(r1.vestigeNext);
		assertTrue(r1.line.contains("Roll 1 of 3"));

		VestigeRolls.Result r2 = v.record(duke(), 26241); // Virtus mask
		assertEquals(2, r2.state.rolls);
		assertTrue("two rolls in, the next unique is the vestige", r2.vestigeNext);
		assertTrue(r2.line.contains("Magus vestige"));
	}

	@Test
	public void theVestigeResetsAndAnchorsTheCycle()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		VestigeRolls.Result r = v.record(duke(), 28281); // Magus vestige
		assertTrue(r.vestige);
		assertEquals(0, r.state.rolls);
		assertTrue("a seen vestige anchors the cycle — the count is exact from here", r.state.exact);
		assertTrue(r.line.contains("cycle resets"));
	}

	@Test
	public void countsAreEstimatedUntilAVestigeIsSeen()
	{
		VestigeRolls v = new VestigeRolls();
		assertTrue(v.record(duke(), 28276).line.contains("(estimated)"));
		v.record(duke(), 28281); // vestige seen — anchored
		assertFalse(v.record(duke(), 28276).line.contains("estimated"));
	}

	@Test
	public void aNonVestigeWhereTheVestigeWasDueReAnchorsInsteadOfLying()
	{
		// Two rolls in (so we think the vestige is next), then a non-vestige: our count was wrong,
		// which is what happens when drops landed while the plugin wasn't running.
		VestigeRolls.State was = new VestigeRolls.State(2, true);
		VestigeRolls.Result r = VestigeRolls.advance(was, false, 3, "Magus vestige");
		assertEquals(1, r.state.rolls);
		assertFalse("we can't claim exact after being wrong", r.state.exact);
		assertTrue(r.line.contains("re-anchoring"));
	}

	@Test
	public void itemsOutsideTheRollTableAreNotRolls()
	{
		VestigeRolls v = new VestigeRolls();
		assertNull("the pet is its own roll, not a unique-table one", v.record(duke(), 28250));
		assertNull("awakener's orb likewise", v.record(duke(), 28334));
		assertEquals(0, v.get("Duke Sucellus").rolls);
	}

	@Test
	public void eachBossKeepsItsOwnCycle()
	{
		PluginConfigResponse.RollTable vard = new PluginConfigResponse.RollTable();
		vard.boss = "Vardorvis";
		vard.rollItemIds = Arrays.asList(26241, 28276, 28285, 28319);
		vard.vestigeItemId = 28285;
		vard.vestigeName = "Ultor vestige";
		vard.rollsPerVestige = 3;

		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 26241);
		v.record(vard, 28276);
		assertEquals(2, v.get("Duke Sucellus").rolls);
		assertEquals(1, v.get("Vardorvis").rolls);
	}

	@Test
	public void stateSurvivesASerialiseRoundTrip()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 28281); // vestige — exact
		v.record(duke(), 26241);

		VestigeRolls back = VestigeRolls.parse(v.serialise());
		assertEquals(1, back.get("Duke Sucellus").rolls);
		assertTrue(back.get("duke sucellus").exact);
	}

	@Test
	public void aCorruptedConfigValueLosesOnlyThatBoss()
	{
		VestigeRolls back = VestigeRolls.parse("duke sucellus=2:1;vardorvis=notanumber;the whisperer=1:0");
		assertEquals(2, back.get("Duke Sucellus").rolls);
		assertEquals(0, back.get("Vardorvis").rolls);
		assertEquals(1, back.get("The Whisperer").rolls);
	}

	@Test
	public void anEmptyOrAbsentConfigStartsClean()
	{
		assertEquals(0, VestigeRolls.parse(null).get("Duke Sucellus").rolls);
		assertEquals(0, VestigeRolls.parse("").get("Duke Sucellus").rolls);
	}
}

package com.anvil.scenario;

import com.anvil.AnvilPlugin;
import com.anvil.BingoApiClient;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.loottracker.LootReceived;
import okhttp3.OkHttpClient;

/**
 * DEV CLIENT ONLY — lives in src/test, never in the hub jar. Replays scripted game events into the
 * running Anvil plugin so a tile can be tested without the grind (a 2,000-kc pet is one chat line),
 * and records real ones to build those scripts from. See src/test/resources/scenarios/README.md.
 */
@PluginDescriptor(
	name = "Anvil Scenario Lab",
	description = "DEV ONLY: replay/record game events into the Anvil plugin (::anvil help)",
	tags = {"anvil", "dev", "test"}
)
public class AnvilScenarioPlugin extends Plugin
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(AnvilScenarioPlugin.class);
	private static final String TAG = "<col=ff5fd7>[anvil-lab]</col> ";
	private static final String CFG_GROUP = "osrsbingo";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private ScheduledExecutorService executor;

	private final SiteBridge bridge = new SiteBridge();
	private ScenarioLibrary library;
	private ScenarioPlayer player;
	private ScenarioRecorder recorder;
	private BingoApiClient apiClient;

	/** True while WE are emitting events, so the recorder never records its own replay. */
	private boolean injecting;
	private String echoExpected;
	private boolean echoSeen;

	static Path labDir()
	{
		return RuneLite.RUNELITE_DIR.toPath().resolve("anvil-scenarios");
	}

	@Override
	protected void startUp()
	{
		library = new ScenarioLibrary(labDir());
		player = new ScenarioPlayer(client, eventBus, this::addChatLine, this::print);
		apiClient = findApiClient();
		if (apiClient != null && bridge.install(apiClient))
		{
			String site = initialSite();
			if (site != null)
			{
				try
				{
					bridge.setSite(site);
					log.info("anvil-lab: plugin traffic re-hosted to {}", bridge.site());
				}
				catch (IllegalArgumentException e)
				{
					log.warn("anvil-lab: ignoring site override: {}", e.getMessage());
				}
			}
		}
		for (String err : library.reload())
		{
			log.warn("anvil-lab scenario: {}", err);
		}
	}

	@Override
	protected void shutDown()
	{
		if (player != null)
		{
			player.stop();
		}
		recorder = null;
	}

	// ── commands ─────────────────────────────────────────────────────────────────────────────

	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (!"anvil".equalsIgnoreCase(e.getCommand()))
		{
			return;
		}
		String[] a = e.getArguments();
		String sub = a.length == 0 ? "help" : a[0].toLowerCase();
		switch (sub)
		{
			case "list":
				list();
				break;
			case "run":
				run(a);
				break;
			case "stop":
				player.stop();
				bridge.scenarioEnded();
				print("stopped");
				break;
			case "record":
				record(a);
				break;
			case "setvarb":
				if (a.length < 3)
				{
					print("usage: ::anvil setvarb <id|NAME> <value>");
					break;
				}
				runOneOff("varbit", varbitStep(a[1], a[2]));
				break;
			case "site":
				site(a);
				break;
			case "sync":
				sync();
				break;
			case "signin":
				signIn();
				break;
			case "reload":
				reload();
				break;
			default:
				help();
		}
	}

	private void help()
	{
		print("::anvil list | run <name> [k=v …] | stop | record on [varbits] | record off");
		print("::anvil setvarb <id|NAME> <value> | site [url|off] | signin | sync | reload");
		print("site: " + bridge.site() + (bridge.overridden() ? " (override)" : " (production!)"));
	}

	private void list()
	{
		reload();
		for (Scenario s : library.all())
		{
			StringBuilder p = new StringBuilder();
			for (Map.Entry<String, String> en : s.params.entrySet())
			{
				p.append(' ').append(en.getKey()).append('=').append(en.getValue());
			}
			print(s.name + " [" + s.origin.name().toLowerCase() + "]" + p + " — " + s.description);
		}
	}

	private void reload()
	{
		List<String> errors = library.reload();
		for (String err : errors)
		{
			print("bad scenario: " + err);
		}
		print(library.all().size() + " scenarios loaded");
	}

	private void run(String[] a)
	{
		if (a.length < 2)
		{
			print("usage: ::anvil run <name> [key=value …]");
			return;
		}
		library.reload();
		Scenario s = library.get(a[1]);
		if (s == null)
		{
			print("no scenario '" + a[1] + "' — ::anvil list");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			print("log in first — scenarios advance on game ticks");
			return;
		}
		if (!bridge.overridden())
		{
			print("WARNING: no site override — this replay reaches anvilosrs.com (production). ::anvil site <url>");
		}
		List<JsonObject> steps;
		try
		{
			Map<String, String> args = Scenario.parseArgs(a, 2);
			// ${me}: the logged-in RSN, for lines the plugin only acts on when they name the local player.
			if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
			{
				args.putIfAbsent("me", client.getLocalPlayer().getName());
			}
			steps = s.resolve(args);
		}
		catch (IllegalArgumentException ex)
		{
			print(s.name + ": " + ex.getMessage());
			return;
		}
		bridge.scenarioStarted(s.name);
		player.start(s.name, steps);
		print("running " + s.name + " (" + steps.size() + " steps)");
	}

	private void runOneOff(String kind, JsonObject body)
	{
		JsonObject step = new JsonObject();
		step.add(kind, body);
		bridge.scenarioStarted("setvarb");
		player.start("setvarb", List.of(step));
	}

	private static JsonObject varbitStep(String idOrName, String value)
	{
		JsonObject v = new JsonObject();
		if (idOrName.chars().allMatch(Character::isDigit))
		{
			v.addProperty("id", Integer.parseInt(idOrName));
		}
		else
		{
			v.addProperty("name", idOrName);
		}
		v.addProperty("value", value);
		return v;
	}

	private void record(String[] a)
	{
		String mode = a.length > 1 ? a[1].toLowerCase() : "";
		if ("on".equals(mode))
		{
			boolean varbits = a.length > 2 && "varbits".equalsIgnoreCase(a[2]);
			recorder = new ScenarioRecorder(varbits);
			print("recording" + (varbits ? " (with varbits)" : "") + " — ::anvil record off to save");
		}
		else if ("off".equals(mode))
		{
			ScenarioRecorder r = recorder;
			recorder = null;
			if (r == null)
			{
				print("not recording");
				return;
			}
			try
			{
				Path file = r.save(library.localDir(), gson);
				print("saved " + r.size() + " steps → " + file.getFileName() + " (rename the file's \"name\" to keep it)");
			}
			catch (IOException ex)
			{
				print("save failed: " + ex.getMessage());
			}
		}
		else
		{
			print("usage: ::anvil record on [varbits] | off");
		}
	}

	private void site(String[] a)
	{
		if (a.length < 2)
		{
			print("site: " + bridge.site() + (bridge.overridden() ? " (override)" : " (production)"));
			return;
		}
		if (apiClient == null)
		{
			print("can't find the Anvil plugin's api client — override unavailable");
			return;
		}
		try
		{
			bridge.setSite(a[1]);
			Path f = labDir().resolve("site.txt");
			Files.createDirectories(f.getParent());
			if (bridge.overridden())
			{
				Files.writeString(f, bridge.site());
			}
			else
			{
				Files.deleteIfExists(f);
			}
			print("site → " + bridge.site() + ". Tokens are per site: ::anvil signin"
				+ (bridge.overridden() ? "" : " (or the side panel)"));
		}
		catch (IllegalArgumentException | IOException ex)
		{
			print(ex.getMessage());
		}
	}

	/** Device sign-in against the current site; on success the token goes where the side panel puts it. */
	private void signIn()
	{
		// Its own thread: the poll sleeps for minutes, and the shared executor belongs to every plugin.
		Thread t = new Thread(() ->
		{
			try
			{
				String token = bridge.signIn(okHttpClient, gson,
					msg -> clientThread.invokeLater(() -> print(msg)), net.runelite.client.util.LinkBrowser::browse);
				if (token != null)
				{
					// ConfigChanged → the Anvil plugin re-configures its api client with the new token.
					configManager.setConfiguration(CFG_GROUP, "playerToken", token);
					clientThread.invokeLater(() -> print("signed in to " + bridge.site()));
				}
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
			}
		}, "anvil-lab-signin");
		t.setDaemon(true);
		t.start();
	}

	private void sync()
	{
		String token = configManager.getConfiguration(CFG_GROUP, "playerToken");
		String rsn = apiClient == null ? null : apiClient.getCurrentRsn();
		long hash = client.getAccountHash();
		print("syncing from " + bridge.site() + " …");
		executor.execute(() ->
		{
			SiteBridge.SyncResult r = bridge.sync(okHttpClient, gson, token, rsn, hash, library.siteDir());
			clientThread.invokeLater(() ->
			{
				if (r.error != null)
				{
					print(r.error);
				}
				print("synced " + r.count + " site scenarios");
				library.reload();
			});
		});
	}

	// ── playback ─────────────────────────────────────────────────────────────────────────────

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (player == null || !player.isRunning())
		{
			return;
		}
		injecting = true;
		try
		{
			String done = player.tick();
			if (done != null)
			{
				bridge.scenarioEnded();
				print("finished " + done);
			}
		}
		finally
		{
			injecting = false;
		}
	}

	/** ChatSink: through the client, so the line shows in the chatbox and fires ChatMessage as the game's would. */
	private boolean addChatLine(ChatMessageType type, String name, String message, String sender)
	{
		echoExpected = message;
		echoSeen = false;
		client.addChatMessage(type, name, message, sender);
		echoExpected = null;
		return echoSeen;
	}

	/**
	 * Harness output. CONSOLE is outside the plugin's credit gate; the two any-channel parsers
	 * (drop / clog broadcasts) are defused by never letting their trigger phrases through.
	 */
	private void print(String text)
	{
		String safe = text.replace("received a", "got a");
		boolean was = injecting;
		injecting = true;
		try
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "", TAG + safe, null);
		}
		finally
		{
			injecting = was;
		}
	}

	// ── recording (and the chat echo check) ──────────────────────────────────────────────────

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (echoExpected != null && echoExpected.equals(e.getMessage()))
		{
			echoSeen = true;
		}
		ScenarioRecorder r = recorder;
		if (r != null && !injecting)
		{
			r.chat(client.getTickCount(), e.getType(), e.getName(), e.getMessage(), e.getSender());
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived e)
	{
		ScenarioRecorder r = recorder;
		if (r != null && !injecting)
		{
			NPC npc = e.getNpc();
			r.loot(client.getTickCount(), "npc", npc.getName(), npc.getId(), npc.getCombatLevel(), null, e.getItems());
		}
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot e)
	{
		ScenarioRecorder r = recorder;
		if (r != null && !injecting && e.getComposition() != null)
		{
			r.loot(client.getTickCount(), "server", e.getComposition().getName(), e.getComposition().getId(),
				e.getComposition().getCombatLevel(), null, e.getItems());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived e)
	{
		ScenarioRecorder r = recorder;
		if (r != null && !injecting)
		{
			r.loot(client.getTickCount(), "generic", e.getName(), -1, e.getCombatLevel(),
				e.getType() == null ? null : e.getType().name(), e.getItems());
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		ScenarioRecorder r = recorder;
		if (r != null && !injecting && r.recordsVarbits())
		{
			r.varbit(client.getTickCount(), e.getVarbitId(), e.getValue());
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		ScenarioRecorder r = recorder;
		if (r != null && !injecting)
		{
			r.stat(client.getTickCount(), e.getSkill(), e.getXp(), e.getLevel(), e.getBoostedLevel());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		ScenarioRecorder r = recorder;
		if (r == null || injecting)
		{
			return;
		}
		if (e.getActor() == client.getLocalPlayer())
		{
			r.death(client.getTickCount(), true, null, -1);
		}
		else if (e.getActor() instanceof NPC)
		{
			NPC npc = (NPC) e.getActor();
			r.death(client.getTickCount(), false, npc.getName(), npc.getId());
		}
	}

	// ── wiring ───────────────────────────────────────────────────────────────────────────────

	/** ANVIL_SITE env / -Danvil.site win over the saved ::anvil site choice. */
	private static String initialSite()
	{
		String v = System.getProperty("anvil.site");
		if (v == null || v.isBlank())
		{
			v = System.getenv("ANVIL_SITE");
		}
		if (v == null || v.isBlank())
		{
			try
			{
				Path f = labDir().resolve("site.txt");
				v = Files.isRegularFile(f) ? Files.readString(f).trim() : null;
			}
			catch (IOException e)
			{
				v = null;
			}
		}
		return v == null || v.isBlank() ? null : v;
	}

	/** The running Anvil plugin's own BingoApiClient (a per-plugin-injector singleton, so not ours to inject). */
	private BingoApiClient findApiClient()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (p instanceof AnvilPlugin)
			{
				try
				{
					Field f = AnvilPlugin.class.getDeclaredField("apiClient");
					f.setAccessible(true);
					return (BingoApiClient) f.get(p);
				}
				catch (ReflectiveOperationException e)
				{
					log.warn("anvil-lab: AnvilPlugin.apiClient not found", e);
				}
			}
		}
		return null;
	}
}

package com.anvil.scenario;

import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;

/**
 * Stand-ins for the client's interface types (NPC, Player, NPCComposition, Hitsplat) that a
 * scenario needs to put inside an event. Built with {@link Proxy}: the named getters answer from
 * the map, every other method returns the type's zero value (null / 0 / false), and default methods
 * (Hitsplat.isMine reads getHitsplatType) run their real bodies.
 */
final class Fakes
{
	private Fakes()
	{
	}

	static NPC npc(String name, int id, int combatLevel)
	{
		NPCComposition comp = composition(name, id, combatLevel);
		return proxy(NPC.class, Map.of(
			"getName", name,
			"getId", id,
			"getCombatLevel", combatLevel,
			"getComposition", comp,
			"getTransformedComposition", comp));
	}

	static NPCComposition composition(String name, int id, int combatLevel)
	{
		return proxy(NPCComposition.class, Map.of(
			"getName", name,
			"getId", id,
			"getCombatLevel", combatLevel));
	}

	static Player player(String name)
	{
		return proxy(Player.class, Map.of("getName", name, "getCombatLevel", 126));
	}

	/** A hitsplat the game would draw as damage dealt BY the local player ({@code isMine()}). */
	static Hitsplat myHit(int amount)
	{
		return proxy(Hitsplat.class, Map.of(
			"getHitsplatType", HitsplatID.DAMAGE_ME,
			"getAmount", amount));
	}

	@SuppressWarnings("unchecked")
	static <T> T proxy(Class<T> type, Map<String, Object> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (self, method, args) ->
		{
			String m = method.getName();
			if (answers.containsKey(m) && (args == null || args.length == 0))
			{
				return answers.get(m);
			}
			switch (m)
			{
				case "equals":
					return self == args[0];
				case "hashCode":
					return System.identityHashCode(self);
				case "toString":
					return "Fake" + type.getSimpleName() + answers;
			}
			if (method.isDefault())
			{
				return java.lang.invoke.MethodHandles.privateLookupIn(type, java.lang.invoke.MethodHandles.lookup())
					.unreflectSpecial(method, type).bindTo(self).invokeWithArguments(args == null ? new Object[0] : args);
			}
			return zero(method.getReturnType());
		});
	}

	private static Object zero(Class<?> t)
	{
		if (!t.isPrimitive() || t == void.class)
		{
			return null;
		}
		if (t == boolean.class)
		{
			return false;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t == float.class)
		{
			return 0f;
		}
		if (t == double.class)
		{
			return 0d;
		}
		if (t == char.class)
		{
			return (char) 0;
		}
		if (t == byte.class)
		{
			return (byte) 0;
		}
		if (t == short.class)
		{
			return (short) 0;
		}
		return 0;
	}
}

package com.anvil.scenario;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * One scripted sequence of fake game events. The on-disk shape is the contract the site's Tile Lab
 * mirrors (see scenarios/README.md), so parsing is strict about structure and lenient only where the
 * spec says so (numbers may be written as strings, which is what lets a placeholder stand in for one).
 */
public final class Scenario
{
	/** Where a scenario came from — shown in {@code ::anvil list}. A later origin shadows an earlier one. */
	public enum Origin
	{
		BUNDLED, LOCAL, SITE
	}

	static final Pattern NAME = Pattern.compile("[a-z0-9][a-z0-9-]{0,63}");
	private static final Pattern PLACEHOLDER = Pattern.compile("\\$\\{([A-Za-z0-9_]+)}");
	static final List<String> STEP_KINDS = List.of("wait", "chat", "loot", "varbit", "stat", "death", "pvpKill");

	public final String name;
	public final String description;
	public final Map<String, String> params;
	/** Raw step objects; placeholders are resolved per run by {@link #resolve}. */
	public final List<JsonObject> steps;
	public final Origin origin;

	private Scenario(String name, String description, Map<String, String> params, List<JsonObject> steps, Origin origin)
	{
		this.name = name;
		this.description = description;
		this.params = params;
		this.steps = steps;
		this.origin = origin;
	}

	public static Scenario parse(String json, Origin origin)
	{
		return fromJson(new JsonParser().parse(json).getAsJsonObject(), origin);
	}

	public static Scenario fromJson(JsonObject o, Origin origin)
	{
		String name = string(o, "name");
		if (name == null || !NAME.matcher(name).matches())
		{
			throw new IllegalArgumentException("scenario name must match " + NAME.pattern() + ": " + name);
		}
		String description = string(o, "description");
		Map<String, String> params = new LinkedHashMap<>();
		if (o.has("params") && o.get("params").isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("params").entrySet())
			{
				params.put(e.getKey(), e.getValue().getAsString());
			}
		}
		if (!o.has("steps") || !o.get("steps").isJsonArray())
		{
			throw new IllegalArgumentException(name + ": missing steps array");
		}
		List<JsonObject> steps = new ArrayList<>();
		JsonArray arr = o.getAsJsonArray("steps");
		for (int i = 0; i < arr.size(); i++)
		{
			if (!arr.get(i).isJsonObject())
			{
				throw new IllegalArgumentException(name + ": step " + i + " is not an object");
			}
			JsonObject step = arr.get(i).getAsJsonObject();
			if (step.size() != 1 || !STEP_KINDS.contains(kindOf(step)))
			{
				throw new IllegalArgumentException(name + ": step " + i + " must have exactly one of " + STEP_KINDS);
			}
			steps.add(step);
		}
		return new Scenario(name, description == null ? "" : description,
			Collections.unmodifiableMap(params), Collections.unmodifiableList(steps), origin);
	}

	public static String kindOf(JsonObject step)
	{
		return step.keySet().iterator().next();
	}

	/** The steps with every {@code ${param}} filled from the defaults overlaid with {@code args}. */
	public List<JsonObject> resolve(Map<String, String> args)
	{
		Map<String, String> values = new LinkedHashMap<>(params);
		values.putAll(args);
		List<JsonObject> out = new ArrayList<>(steps.size());
		for (JsonObject step : steps)
		{
			out.add(substitute(step, values).getAsJsonObject());
		}
		return out;
	}

	private static JsonElement substitute(JsonElement e, Map<String, String> values)
	{
		if (e.isJsonObject())
		{
			JsonObject copy = new JsonObject();
			for (Map.Entry<String, JsonElement> en : e.getAsJsonObject().entrySet())
			{
				copy.add(en.getKey(), substitute(en.getValue(), values));
			}
			return copy;
		}
		if (e.isJsonArray())
		{
			JsonArray copy = new JsonArray();
			for (JsonElement child : e.getAsJsonArray())
			{
				copy.add(substitute(child, values));
			}
			return copy;
		}
		if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isString())
		{
			Matcher m = PLACEHOLDER.matcher(e.getAsString());
			StringBuffer sb = new StringBuffer();
			while (m.find())
			{
				String v = values.get(m.group(1));
				if (v == null)
				{
					throw new IllegalArgumentException("no value for ${" + m.group(1) + "}");
				}
				m.appendReplacement(sb, Matcher.quoteReplacement(v));
			}
			m.appendTail(sb);
			return new JsonPrimitive(sb.toString());
		}
		return e;
	}

	/**
	 * {@code key=value} pairs from a command line. RuneLite splits {@code ::} commands on spaces, so a
	 * token without {@code =} continues the previous value: {@code boss=Phantom Muspah} survives.
	 */
	public static Map<String, String> parseArgs(String[] tokens, int from)
	{
		Map<String, String> args = new LinkedHashMap<>();
		String key = null;
		for (int i = from; i < tokens.length; i++)
		{
			String t = tokens[i];
			int eq = t.indexOf('=');
			if (eq > 0)
			{
				key = t.substring(0, eq);
				args.put(key, t.substring(eq + 1));
			}
			else if (key != null)
			{
				args.put(key, args.get(key) + " " + t);
			}
		}
		return args;
	}

	static String string(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : null;
	}

	/** An int field that may be written as a number or a (placeholder-resolved) string. */
	static int integer(JsonObject o, String key, int fallback)
	{
		if (!o.has(key) || o.get(key).isJsonNull())
		{
			return fallback;
		}
		return Integer.parseInt(o.get(key).getAsString().replace(",", "").trim());
	}
}

package com.anvil.scenario;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** Every bundled scenario parses, resolves, and turns into the events it claims to — no client needed. */
public class ScenarioFormatTest
{
	private static final Map<String, String> ME = Map.of("me", "Tester");

	@Test
	public void indexListsEveryBundledFile() throws IOException
	{
		Set<String> onDisk = new HashSet<>();
		try (DirectoryStream<Path> ds = Files.newDirectoryStream(Paths.get("src/test/resources/scenarios"), "*.json"))
		{
			for (Path p : ds)
			{
				onDisk.add(p.getFileName().toString());
			}
		}
		assertEquals(onDisk, new HashSet<>(ScenarioLibrary.bundledFiles()));
	}

	@Test
	public void bundledScenariosLoadCleanly() throws IOException
	{
		Path empty = Files.createTempDirectory("anvil-scenarios");
		ScenarioLibrary lib = new ScenarioLibrary(empty);
		List<String> errors = lib.reload();
		assertTrue(errors.toString(), errors.isEmpty());
		assertEquals(ScenarioLibrary.bundledFiles().size(), lib.all().size());
		for (Scenario s : lib.all())
		{
			assertEquals(Scenario.Origin.BUNDLED, s.origin);
			assertTrue(s.name + " needs a description", !s.description.isEmpty());
		}
	}

	/** Each step resolves (no dangling ${…}) and builds its event — catches bad enums, ids and names. */
	@Test
	public void everyStepBuildsItsEvent() throws IOException
	{
		ScenarioLibrary lib = new ScenarioLibrary(Files.createTempDirectory("anvil-scenarios"));
		lib.reload();
		for (Scenario s : lib.all())
		{
			for (JsonObject step : s.resolve(ME))
			{
				String kind = Scenario.kindOf(step);
				try
				{
					JsonObject body = "wait".equals(kind) ? null : step.getAsJsonObject(kind);
					switch (kind)
					{
						case "wait":
							assertTrue(step.get("wait").getAsInt() > 0);
							break;
						case "chat":
							ChatMessageType.valueOf(body.has("type") ? body.get("type").getAsString() : "GAMEMESSAGE");
							assertTrue(!body.get("message").getAsString().contains("${"));
							break;
						case "loot":
							assertNotNull(ScenarioPlayer.lootEvent(body));
							break;
						case "varbit":
							assertTrue(ScenarioPlayer.varbitId(body) > 0);
							Scenario.integer(body, "value", 0);
							break;
						case "stat":
							assertNotNull(ScenarioPlayer.statEvent(body));
							break;
						default:
							break;
					}
				}
				catch (RuntimeException e)
				{
					fail(s.name + " step " + step + ": " + e);
				}
			}
		}
	}

	@Test
	public void argsOverrideDefaultsAndKeepSpaces()
	{
		Map<String, String> args = Scenario.parseArgs(new String[]{"run", "boss-kc", "boss=Phantom", "Muspah", "kc=7"}, 2);
		assertEquals("Phantom Muspah", args.get("boss"));
		assertEquals("7", args.get("kc"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNamesThatArentFileSafe()
	{
		Scenario.parse("{\"name\":\"../evil\",\"steps\":[]}", Scenario.Origin.SITE);
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsStepsWithTwoKinds()
	{
		Scenario.parse("{\"name\":\"x\",\"steps\":[{\"wait\":1,\"chat\":{\"message\":\"hi\"}}]}", Scenario.Origin.LOCAL);
	}

	@Test
	public void lootKindsBuildTheRightEvents()
	{
		JsonObject l = new JsonObject();
		l.addProperty("name", "Zulrah");
		l.addProperty("npcId", 2042);
		com.google.gson.JsonArray items = new com.google.gson.JsonArray();
		JsonObject it = new JsonObject();
		it.addProperty("id", "12922");
		items.add(it);
		l.add("items", items);

		l.addProperty("kind", "server");
		ServerNpcLoot server = (ServerNpcLoot) ScenarioPlayer.lootEvent(l);
		assertEquals("Zulrah", server.getComposition().getName());
		assertEquals(12922, server.getItems().iterator().next().getId());

		l.addProperty("kind", "npc");
		NpcLootReceived npc = (NpcLootReceived) ScenarioPlayer.lootEvent(l);
		assertEquals("Zulrah", npc.getNpc().getName());
		assertEquals(2042, npc.getNpc().getId());

		l.addProperty("kind", "generic");
		l.addProperty("lootType", "EVENT");
		LootReceived generic = (LootReceived) ScenarioPlayer.lootEvent(l);
		assertEquals(LootRecordType.EVENT, generic.getType());
	}

	@Test
	public void fakeHitsplatIsOurs()
	{
		assertTrue(Fakes.myHit(25).isMine());
		assertEquals(25, Fakes.myHit(25).getAmount());
	}

	@Test
	public void gamevalNamesResolve()
	{
		JsonObject v = new JsonObject();
		v.addProperty("name", "raids_client_indungeon");
		assertEquals(5432, ScenarioPlayer.varbitId(v));
	}

	/** The player keeps the game's tick grouping: everything before a wait lands in one tick. */
	@Test
	public void playbackGroupsStepsByTick() throws IOException
	{
		ScenarioLibrary lib = new ScenarioLibrary(Files.createTempDirectory("anvil-scenarios"));
		lib.reload();
		List<Object> seen = new ArrayList<>();
		EventBus bus = new EventBus();
		bus.register(ChatMessage.class, seen::add, 0);
		bus.register(ActorDeath.class, seen::add, 0);
		Client client = Fakes.proxy(Client.class, Map.of());
		ScenarioPlayer player = new ScenarioPlayer(client, bus, (t, n, m, s) -> false, msg -> fail(msg));

		player.start("boss-pet", lib.get("boss-pet").resolve(Map.of("kc", "1999")));
		assertEquals(null, player.tick());
		assertEquals(3, seen.size()); // NPC death, KC line, pet line — same tick
		assertTrue(seen.get(0) instanceof ActorDeath);
		assertEquals("Your Scurrius kill count is: 1999.", ((ChatMessage) seen.get(1)).getMessage());
		assertEquals("boss-pet", player.tick()); // wait 1 elapses → the clog line, then done
		assertEquals("New item added to your collection log: Scurry", ((ChatMessage) seen.get(3)).getMessage());
		assertTrue(!player.isRunning());
	}

	@Test
	public void pvpKillIsHitThenDeathOfTheSamePlayer() throws IOException
	{
		ScenarioLibrary lib = new ScenarioLibrary(Files.createTempDirectory("anvil-scenarios"));
		lib.reload();
		List<Object> seen = new ArrayList<>();
		EventBus bus = new EventBus();
		bus.register(HitsplatApplied.class, seen::add, 0);
		bus.register(ActorDeath.class, seen::add, 0);
		Client client = Fakes.proxy(Client.class, Map.of());
		ScenarioPlayer player = new ScenarioPlayer(client, bus, (t, n, m, s) -> false, msg -> fail(msg));
		player.start("pvp-kill", lib.get("pvp-kill").resolve(Map.of()));
		for (int i = 0; i < 6 && player.isRunning(); i++)
		{
			player.tick();
		}
		assertEquals(2, seen.size());
		HitsplatApplied hit = (HitsplatApplied) seen.get(0);
		assertTrue(hit.getHitsplat().isMine());
		assertTrue(hit.getActor() instanceof net.runelite.api.Player);
		assertTrue(hit.getActor() == ((ActorDeath) seen.get(1)).getActor());
		assertEquals("Some Pker", hit.getActor().getName());
	}

	@Test
	public void statStepUppercasesSkill()
	{
		JsonObject s = new JsonObject();
		s.addProperty("skill", "Cooking");
		s.addProperty("xp", "13,034,431");
		s.addProperty("level", 99);
		StatChanged ev = ScenarioPlayer.statEvent(s);
		assertEquals(Skill.COOKING, ev.getSkill());
		assertEquals(13034431, ev.getXp());
		assertEquals(99, ev.getBoostedLevel());
	}
}

package com.anvil.scenario;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Every scenario the harness knows, keyed by name. Three sources, loaded in order so a later one
 * shadows an earlier one of the same name: bundled (src/test/resources/scenarios, listed in
 * index.txt because a classpath directory can't be enumerated reliably), local
 * (~/.runelite/anvil-scenarios/*.json, which includes recordings), then site
 * (~/.runelite/anvil-scenarios/site/*.json, written by {@code ::anvil sync}).
 */
public final class ScenarioLibrary
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(ScenarioLibrary.class);

	static final String BUNDLED_INDEX = "/scenarios/index.txt";

	private final Path localDir;
	private final Map<String, Scenario> byName = new TreeMap<>();
	private final List<String> errors = new ArrayList<>();

	public ScenarioLibrary(Path localDir)
	{
		this.localDir = localDir;
	}

	public Path localDir()
	{
		return localDir;
	}

	public Path siteDir()
	{
		return localDir.resolve("site");
	}

	/** Reload everything. Returns the per-file parse errors (a bad file never hides the good ones). */
	public synchronized List<String> reload()
	{
		byName.clear();
		errors.clear();
		for (String file : bundledFiles())
		{
			try (InputStream in = ScenarioLibrary.class.getResourceAsStream("/scenarios/" + file))
			{
				if (in == null)
				{
					errors.add("bundled " + file + ": listed in index.txt but missing");
					continue;
				}
				add(Scenario.parse(new String(in.readAllBytes(), StandardCharsets.UTF_8), Scenario.Origin.BUNDLED));
			}
			catch (IOException | RuntimeException e)
			{
				errors.add("bundled " + file + ": " + e.getMessage());
			}
		}
		loadDir(localDir, Scenario.Origin.LOCAL);
		loadDir(siteDir(), Scenario.Origin.SITE);
		return new ArrayList<>(errors);
	}

	public synchronized Scenario get(String name)
	{
		return byName.get(name);
	}

	public synchronized List<Scenario> all()
	{
		return new ArrayList<>(byName.values());
	}

	private void add(Scenario s)
	{
		byName.put(s.name, s);
	}

	private void loadDir(Path dir, Scenario.Origin origin)
	{
		if (!Files.isDirectory(dir))
		{
			return;
		}
		try (DirectoryStream<Path> files = Files.newDirectoryStream(dir, "*.json"))
		{
			for (Path f : files)
			{
				try
				{
					add(Scenario.parse(Files.readString(f), origin));
				}
				catch (IOException | RuntimeException e)
				{
					errors.add(f.getFileName() + ": " + e.getMessage());
				}
			}
		}
		catch (IOException e)
		{
			errors.add(dir + ": " + e.getMessage());
		}
	}

	/** File names from the bundled index — blank lines and # comments ignored. */
	public static List<String> bundledFiles()
	{
		List<String> out = new ArrayList<>();
		try (InputStream in = ScenarioLibrary.class.getResourceAsStream(BUNDLED_INDEX))
		{
			if (in == null)
			{
				return out;
			}
			BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (!line.isEmpty() && !line.startsWith("#"))
				{
					out.add(line);
				}
			}
		}
		catch (IOException e)
		{
			log.warn("scenario index unreadable", e);
		}
		return out;
	}
}

package com.anvil.scenario;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.lang.reflect.Field;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Plays resolved scenario steps, one game tick at a time. {@link #tick} is called from GameTick on
 * the client thread: it runs every step up to the next {@code wait}, then sleeps that many ticks.
 * Counting ticks (never sleeping) keeps ordering identical to the game's — two lines in one step
 * group land in the same tick, exactly as a KC line and its pet line do.
 */
final class ScenarioPlayer
{
	interface ChatSink
	{
		/** Put a line in the chatbox the way the game would; true if the client fired ChatMessage for it. */
		boolean add(ChatMessageType type, String name, String message, String sender);
	}

	private final Client client;
	private final EventBus eventBus;
	private final ChatSink chat;
	private final Consumer<String> note;

	private Deque<JsonObject> pending = new ArrayDeque<>();
	private int sleep;
	private String running;

	ScenarioPlayer(Client client, EventBus eventBus, ChatSink chat, Consumer<String> note)
	{
		this.client = client;
		this.eventBus = eventBus;
		this.chat = chat;
		this.note = note;
	}

	boolean isRunning()
	{
		return running != null;
	}

	String running()
	{
		return running;
	}

	void start(String name, List<JsonObject> steps)
	{
		pending = new ArrayDeque<>(steps);
		sleep = 0;
		running = name;
	}

	void stop()
	{
		pending.clear();
		running = null;
	}

	/** Advance one tick. Returns the name of a scenario that just finished, else null. */
	String tick()
	{
		if (running == null)
		{
			return null;
		}
		if (sleep > 0 && --sleep > 0)
		{
			return null;
		}
		while (!pending.isEmpty())
		{
			JsonObject step = pending.poll();
			String kind = Scenario.kindOf(step);
			if ("wait".equals(kind))
			{
				sleep = Math.max(1, step.get("wait").getAsInt());
				return null;
			}
			try
			{
				run(kind, step.getAsJsonObject(kind));
			}
			catch (RuntimeException e)
			{
				note.accept("step " + kind + " failed: " + e.getMessage());
			}
		}
		String done = running;
		running = null;
		return done;
	}

	private void run(String kind, JsonObject s)
	{
		switch (kind)
		{
			case "chat":
			{
				ChatMessageType type = ChatMessageType.valueOf(orDefault(Scenario.string(s, "type"), "GAMEMESSAGE"));
				String name = orDefault(Scenario.string(s, "name"), "");
				String message = Scenario.string(s, "message");
				String sender = Scenario.string(s, "sender");
				if (!chat.add(type, name, message, sender))
				{
					// The client didn't echo it as a ChatMessage (logged out, or a client that doesn't) —
					// post it ourselves so the plugin still sees the line.
					eventBus.post(new ChatMessage(null, type, name, message, sender, (int) (System.currentTimeMillis() / 1000)));
				}
				break;
			}
			case "loot":
				eventBus.post(lootEvent(s));
				break;
			case "varbit":
			{
				int id = varbitId(s);
				int value = Scenario.integer(s, "value", 0);
				// Same as DevTools' ::setvarb: write the client-side value (so getVarbitValue reads it)
				// and post the event the game would have fired. The server overwrites it the next time
				// it sends that varp, which for most gating varbits outside their content is never.
				client.setVarbit(id, value);
				VarbitChanged ev = new VarbitChanged();
				ev.setVarbitId(id);
				ev.setVarpId(-1);
				ev.setValue(value);
				eventBus.post(ev);
				break;
			}
			case "stat":
				eventBus.post(statEvent(s));
				break;
			case "death":
			{
				String who = orDefault(Scenario.string(s, "who"), "self");
				if ("self".equals(who))
				{
					eventBus.post(new ActorDeath(client.getLocalPlayer()));
				}
				else
				{
					eventBus.post(new ActorDeath(Fakes.npc(Scenario.string(s, "name"),
						Scenario.integer(s, "npcId", -1), Scenario.integer(s, "combatLevel", 0))));
				}
				break;
			}
			case "pvpKill":
			{
				// The plugin credits a PK off damage→death attribution, not a chat line: a hitsplat we
				// dealt to that Player, then the Player's ActorDeath inside the attribution window.
				net.runelite.api.Player victim = Fakes.player(Scenario.string(s, "victim"));
				HitsplatApplied hit = new HitsplatApplied();
				hit.setActor(victim);
				hit.setHitsplat(Fakes.myHit(Scenario.integer(s, "damage", 20)));
				eventBus.post(hit);
				eventBus.post(new ActorDeath(victim));
				break;
			}
			default:
				throw new IllegalArgumentException("unknown step " + kind);
		}
	}

	static Object lootEvent(JsonObject s)
	{
		String kind = orDefault(Scenario.string(s, "kind"), "npc");
		String name = Scenario.string(s, "name");
		int npcId = Scenario.integer(s, "npcId", -1);
		int combat = Scenario.integer(s, "combatLevel", 0);
		List<ItemStack> items = items(s.getAsJsonArray("items"));
		switch (kind)
		{
			case "npc":
				return new NpcLootReceived(Fakes.npc(name, npcId, combat), items);
			case "server":
				return new ServerNpcLoot(Fakes.composition(name, npcId, combat), items);
			case "generic":
				return new LootReceived(name, combat,
					LootRecordType.valueOf(orDefault(Scenario.string(s, "lootType"), "EVENT")),
					items, Scenario.integer(s, "amount", 1), null);
			default:
				throw new IllegalArgumentException("loot kind must be npc|server|generic: " + kind);
		}
	}

	static StatChanged statEvent(JsonObject s)
	{
		Skill skill = Skill.valueOf(Scenario.string(s, "skill").toUpperCase(Locale.ROOT));
		int level = Scenario.integer(s, "level", 1);
		return new StatChanged(skill, Scenario.integer(s, "xp", 0), level, Scenario.integer(s, "boostedLevel", level));
	}

	static List<ItemStack> items(JsonArray arr)
	{
		List<ItemStack> out = new ArrayList<>();
		if (arr == null)
		{
			return out;
		}
		for (JsonElement e : arr)
		{
			JsonObject it = e.getAsJsonObject();
			int id = it.has("id") ? Scenario.integer(it, "id", -1) : constant(ItemID.class, Scenario.string(it, "name"));
			out.add(new ItemStack(id, Scenario.integer(it, "qty", 1)));
		}
		return out;
	}

	static int varbitId(JsonObject s)
	{
		return s.has("id") ? Scenario.integer(s, "id", -1) : constant(VarbitID.class, Scenario.string(s, "name"));
	}

	/** A gameval constant by name (VarbitID.RAIDS_CLIENT_INDUNGEON, ItemID.COINS, …). */
	static int constant(Class<?> holder, String name)
	{
		if (name == null)
		{
			throw new IllegalArgumentException("need an id or a " + holder.getSimpleName() + " name");
		}
		try
		{
			Field f = holder.getField(name.toUpperCase(Locale.ROOT));
			return f.getInt(null);
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalArgumentException("no " + holder.getSimpleName() + "." + name);
		}
	}

	private static String orDefault(String v, String d)
	{
		return v == null || v.isEmpty() ? d : v;
	}
}

package com.anvil.scenario;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Collection;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemStack;

/**
 * Turns real events into scenario steps while recording is on. Each event is stamped with the
 * client tick it arrived on, and the gap since the previous event becomes a {@code wait} step — so a
 * replay keeps the game's own ordering and spacing.
 *
 * <p>Deliberately not recorded: player-authored chat (it is someone else's text, and the plugin never
 * credits off it), varbits unless asked for (hundreds change a minute), and StatChanged events that
 * didn't move XP (boost/drain ticks).</p>
 */
final class ScenarioRecorder
{
	private static final java.util.Set<ChatMessageType> SKIP_CHAT = java.util.EnumSet.of(
		ChatMessageType.PUBLICCHAT, ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
		ChatMessageType.MODCHAT, ChatMessageType.MODPRIVATECHAT, ChatMessageType.AUTOTYPER,
		ChatMessageType.MODAUTOTYPER, ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT,
		ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.CONSOLE);

	private final JsonArray steps = new JsonArray();
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private final boolean varbits;
	private int lastTick = -1;

	ScenarioRecorder(boolean varbits)
	{
		this.varbits = varbits;
	}

	boolean recordsVarbits()
	{
		return varbits;
	}

	int size()
	{
		return steps.size();
	}

	void chat(int tick, ChatMessageType type, String name, String message, String sender)
	{
		if (type == null || SKIP_CHAT.contains(type))
		{
			return;
		}
		JsonObject c = new JsonObject();
		c.addProperty("type", type.name());
		if (name != null && !name.isEmpty())
		{
			c.addProperty("name", name);
		}
		if (sender != null && !sender.isEmpty())
		{
			c.addProperty("sender", sender);
		}
		c.addProperty("message", message);
		add(tick, "chat", c);
	}

	void loot(int tick, String kind, String name, int npcId, int combatLevel, String lootType, Collection<ItemStack> items)
	{
		JsonObject l = new JsonObject();
		l.addProperty("kind", kind);
		l.addProperty("name", name);
		if (npcId >= 0)
		{
			l.addProperty("npcId", npcId);
		}
		if (combatLevel > 0)
		{
			l.addProperty("combatLevel", combatLevel);
		}
		if (lootType != null)
		{
			l.addProperty("lootType", lootType);
		}
		JsonArray arr = new JsonArray();
		for (ItemStack it : items)
		{
			JsonObject o = new JsonObject();
			o.addProperty("id", it.getId());
			o.addProperty("qty", it.getQuantity());
			arr.add(o);
		}
		l.add("items", arr);
		add(tick, "loot", l);
	}

	void varbit(int tick, int id, int value)
	{
		if (!varbits || id < 0)
		{
			return;
		}
		JsonObject v = new JsonObject();
		v.addProperty("id", id);
		v.addProperty("value", value);
		add(tick, "varbit", v);
	}

	void stat(int tick, Skill skill, int xp, int level, int boosted)
	{
		Integer prev = lastXp.put(skill, xp);
		if (prev == null || prev == xp)
		{
			return; // first sighting is the login burst; unchanged XP is a boost tick
		}
		JsonObject s = new JsonObject();
		s.addProperty("skill", skill.name());
		s.addProperty("xp", xp);
		s.addProperty("level", level);
		s.addProperty("boostedLevel", boosted);
		add(tick, "stat", s);
	}

	void death(int tick, boolean self, String npcName, int npcId)
	{
		JsonObject d = new JsonObject();
		d.addProperty("who", self ? "self" : "npc");
		if (!self)
		{
			d.addProperty("name", npcName);
			d.addProperty("npcId", npcId);
		}
		add(tick, "death", d);
	}

	private void add(int tick, String kind, JsonObject body)
	{
		if (lastTick >= 0 && tick > lastTick)
		{
			JsonObject w = new JsonObject();
			w.addProperty("wait", tick - lastTick);
			steps.add(w);
		}
		lastTick = tick;
		JsonObject step = new JsonObject();
		step.add(kind, body);
		steps.add(step);
	}

	/** Write the recording as a scenario file; returns its path. */
	Path save(Path dir, Gson gson) throws IOException
	{
		String stamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"));
		String name = "recorded-" + stamp;
		JsonObject o = new JsonObject();
		o.addProperty("name", name);
		o.addProperty("description", "Recorded " + stamp + " (" + steps.size() + " steps)");
		o.add("params", new JsonObject());
		o.add("steps", steps);
		Files.createDirectories(dir);
		Path file = dir.resolve(name + ".json");
		Files.writeString(file, gson.newBuilder().setPrettyPrinting().create().toJson(o));
		return file;
	}
}

package com.anvil.scenario;

import com.anvil.BingoApiClient;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import okhttp3.HttpUrl;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Everything the harness does to the plugin's traffic, all from the outside:
 *
 * <ul>
 * <li><b>Site override.</b> The plugin's site is a compile-time constant (anvilosrs.com), so the
 * harness wraps the BingoApiClient's two OkHttp clients (reflection on its private fields — test
 * code only) with an interceptor that re-hosts anvilosrs.com requests onto the chosen site. Sign-in
 * included, so the side panel's Sign in button gives a token for THAT site.</li>
 * <li><b>Scenario header.</b> While a scenario runs (and for a grace period after, because pushes
 * are coalesced) every plugin request carries {@code X-Anvil-Scenario: <name>}, so a site can tell a
 * replayed pet from a real one.</li>
 * <li><b>Sync.</b> {@code GET /api/plugin/lab/scenarios} with the plugin's own auth headers.</li>
 * </ul>
 */
final class SiteBridge
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(SiteBridge.class);

	static final String HEADER = "X-Anvil-Scenario";
	private static final long HEADER_GRACE_MS = 120_000;

	private volatile HttpUrl override;
	private volatile String scenario;
	private volatile long scenarioUntil;
	private boolean installed;

	/** null/blank/"off" clears it. Throws on a URL that doesn't parse. */
	void setSite(String url)
	{
		if (url == null || url.isBlank() || url.equalsIgnoreCase("off"))
		{
			override = null;
			return;
		}
		HttpUrl parsed = HttpUrl.parse(url.trim());
		if (parsed == null)
		{
			throw new IllegalArgumentException("not a URL: " + url);
		}
		override = parsed;
	}

	String site()
	{
		HttpUrl o = override;
		return o == null ? BingoApiClient.CANONICAL_SITE : o.toString().replaceAll("/$", "");
	}

	boolean overridden()
	{
		return override != null;
	}

	void scenarioStarted(String name)
	{
		scenario = name;
		scenarioUntil = Long.MAX_VALUE;
	}

	void scenarioEnded()
	{
		scenarioUntil = System.currentTimeMillis() + HEADER_GRACE_MS;
	}

	/** Wrap the api client's HTTP clients once. Returns false (and logs) if the fields moved. */
	boolean install(BingoApiClient api)
	{
		if (installed)
		{
			return true;
		}
		try
		{
			// Every OkHttpClient the API client holds, found by type rather than by name: the plugin
			// has renamed and split these before (httpClient/uploadClient became httpClient/readClient),
			// and a name list that misses one leaves that client talking to production. All or
			// nothing — the clients are wrapped only once every one of them has been found.
			List<Field> fields = new ArrayList<>();
			for (Field f : BingoApiClient.class.getDeclaredFields())
			{
				if (f.getType() == OkHttpClient.class && !java.lang.reflect.Modifier.isStatic(f.getModifiers()))
				{
					f.setAccessible(true);
					fields.add(f);
				}
			}
			if (fields.isEmpty())
			{
				log.warn("scenario harness: BingoApiClient holds no OkHttpClient field to wrap");
				return false;
			}
			List<OkHttpClient> wrapped = new ArrayList<>();
			for (Field f : fields)
			{
				OkHttpClient original = (OkHttpClient) f.get(api);
				wrapped.add(original.newBuilder().addInterceptor(this::intercept).build());
			}
			for (int i = 0; i < fields.size(); i++)
			{
				fields.get(i).set(api, wrapped.get(i));
			}
			installed = true;
			return true;
		}
		catch (ReflectiveOperationException | RuntimeException e)
		{
			log.warn("scenario harness: couldn't wrap BingoApiClient HTTP clients", e);
			return false;
		}
	}

	private Response intercept(Interceptor.Chain chain) throws IOException
	{
		Request req = chain.request();
		HttpUrl o = override;
		Request.Builder b = req.newBuilder();
		boolean changed = false;
		if (o != null && "anvilosrs.com".equalsIgnoreCase(req.url().host()))
		{
			HttpUrl.Builder u = req.url().newBuilder().scheme(o.scheme()).host(o.host()).port(o.port());
			// A base with a path prefix (rare) is prepended.
			List<String> prefix = new ArrayList<>(o.pathSegments());
			prefix.removeIf(String::isEmpty);
			if (!prefix.isEmpty())
			{
				List<String> segs = new ArrayList<>(prefix);
				segs.addAll(req.url().pathSegments());
				u.encodedPath("/");
				for (String s : segs)
				{
					u.addPathSegment(s);
				}
			}
			b.url(u.build());
			changed = true;
		}
		String s = scenario;
		if (s != null && System.currentTimeMillis() < scenarioUntil)
		{
			b.header(HEADER, s);
			changed = true;
		}
		return chain.proceed(changed ? b.build() : req);
	}

	/**
	 * Device sign-in against {@link #site()}. The side panel's Sign in refuses any login page that
	 * isn't on anvilosrs.com (DeviceSignIn.isConfiguredHomeUrl, a real safeguard), so with an override
	 * the harness runs the same RFC 8628 flow itself. Blocking — call off the client thread. Returns
	 * the token, or null after reporting why through {@code status}.
	 */
	String signIn(OkHttpClient http, Gson gson, java.util.function.Consumer<String> status,
		java.util.function.Consumer<String> openUrl) throws InterruptedException
	{
		BingoApiClient.DeviceAuthStart start;
		Request startReq = new Request.Builder().url(site() + "/api/plugin/auth/start")
			.header("X-Anvil-Plugin-Version", pluginVersion())
			.post(okhttp3.RequestBody.create(null, new byte[0])).build();
		try (Response r = http.newCall(startReq).execute())
		{
			if (!r.isSuccessful() || r.body() == null)
			{
				status.accept("sign-in start failed: HTTP " + r.code() + " from " + site());
				return null;
			}
			start = gson.fromJson(r.body().charStream(), BingoApiClient.DeviceAuthStart.class);
		}
		catch (IOException | RuntimeException e)
		{
			status.accept("sign-in start failed: " + e.getMessage());
			return null;
		}
		String url = start.verification_url_complete != null ? start.verification_url_complete : start.verification_url;
		status.accept("approve code " + start.user_code + " at " + url);
		openUrl.accept(url);
		long interval = Math.max(1, start.interval > 0 ? start.interval : 5) * 1000L;
		long deadline = System.currentTimeMillis() + (start.expires_in > 0 ? start.expires_in : 600) * 1000L;
		okhttp3.MediaType json = okhttp3.MediaType.parse("application/json");
		while (System.currentTimeMillis() < deadline)
		{
			Thread.sleep(interval);
			Request poll = new Request.Builder().url(site() + "/api/plugin/auth/poll")
				.header("X-Anvil-Plugin-Version", pluginVersion())
				.post(okhttp3.RequestBody.create(json,
					gson.toJson(java.util.Collections.singletonMap("device_code", start.device_code)))).build();
			try (Response r = http.newCall(poll).execute())
			{
				if (!r.isSuccessful() || r.body() == null)
				{
					continue;
				}
				BingoApiClient.DeviceAuthPoll p = gson.fromJson(r.body().charStream(), BingoApiClient.DeviceAuthPoll.class);
				if ("complete".equals(p.status) && p.token != null)
				{
					return p.token;
				}
				if ("expired".equals(p.status) || "denied".equals(p.status))
				{
					status.accept("sign-in " + p.status);
					return null;
				}
				if ("slow_down".equals(p.status))
				{
					interval += 5000;
				}
			}
			catch (IOException | RuntimeException e)
			{
				// transient — keep polling until the deadline
			}
		}
		status.accept("sign-in timed out");
		return null;
	}

	/** Same resource BingoApiClient reads (its constant is package-private to com.anvil). */
	static String pluginVersion()
	{
		try (java.io.InputStream in = BingoApiClient.class.getResourceAsStream("version.txt"))
		{
			return in == null ? "unknown" : new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).trim();
		}
		catch (IOException e)
		{
			return "unknown";
		}
	}

	/** Outcome of a sync, for the chat line. */
	static final class SyncResult
	{
		final int count;
		final String error;

		SyncResult(int count, String error)
		{
			this.count = count;
			this.error = error;
		}
	}

	/**
	 * Fetch the site's scenarios and mirror them into {@code siteDir} (replacing what was there, so a
	 * scenario deleted on the site disappears here). Blocking — call off the client thread.
	 */
	SyncResult sync(OkHttpClient http, Gson gson, String token, String rsn, long accountHash, Path siteDir)
	{
		if (token == null || token.isBlank())
		{
			return new SyncResult(0, "not signed in — sign in from the Anvil side panel first");
		}
		Request.Builder rb = new Request.Builder().url(site() + "/api/plugin/lab/scenarios")
			.header("Authorization", "Bearer " + token)
			.header("X-Anvil-Plugin-Version", pluginVersion());
		if (rsn != null && !rsn.isEmpty())
		{
			rb.header("X-RSN", rsn);
		}
		if (accountHash != -1)
		{
			rb.header("X-Account-Hash", Long.toString(accountHash));
		}
		try (Response r = http.newCall(rb.build()).execute())
		{
			if (r.code() == 403)
			{
				return new SyncResult(0, "403 — this account isn't platform staff on " + site());
			}
			if (!r.isSuccessful() || r.body() == null)
			{
				return new SyncResult(0, "HTTP " + r.code() + " from " + site());
			}
			JsonElement root = new JsonParser().parse(r.body().string());
			JsonArray arr = root.getAsJsonObject().getAsJsonArray("scenarios");
			List<JsonObject> valid = new ArrayList<>();
			List<String> bad = new ArrayList<>();
			for (JsonElement e : arr)
			{
				try
				{
					JsonObject o = e.getAsJsonObject();
					Scenario.fromJson(o, Scenario.Origin.SITE); // validates the name (it becomes a file name) + steps
					valid.add(o);
				}
				catch (RuntimeException ex)
				{
					bad.add(ex.getMessage());
				}
			}
			Files.createDirectories(siteDir);
			try (DirectoryStream<Path> old = Files.newDirectoryStream(siteDir, "*.json"))
			{
				for (Path p : old)
				{
					Files.deleteIfExists(p);
				}
			}
			for (JsonObject o : valid)
			{
				Files.writeString(siteDir.resolve(o.get("name").getAsString() + ".json"),
					gson.newBuilder().setPrettyPrinting().create().toJson(o));
			}
			return new SyncResult(valid.size(), bad.isEmpty() ? null : "skipped " + bad.size() + " invalid: " + bad);
		}
		catch (IOException | RuntimeException e)
		{
			return new SyncResult(0, "sync failed: " + e.getMessage());
		}
	}
}

package com.anvil.scenario;

import com.anvil.BingoApiClient;
import com.google.gson.Gson;
import com.sun.net.httpserver.HttpServer;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The bridge must reroute EVERY client the real BingoApiClient holds. It once wrapped two by name,
 * the plugin renamed one of them, and the reads (config, board) would have kept talking to
 * production while the replay's writes went to beta. This runs the real class, so a future rename
 * fails here instead of in somebody's dev client.
 */
public class SiteBridgeTest
{
	private HttpServer server;
	private final List<String> hits = new CopyOnWriteArrayList<>();

	@Before
	public void start() throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", ex ->
		{
			hits.add(ex.getRequestURI().getPath() + " " + ex.getRequestHeaders().getFirst(SiteBridge.HEADER));
			byte[] body = "{}".getBytes();
			ex.sendResponseHeaders(200, body.length);
			ex.getResponseBody().write(body);
			ex.close();
		});
		server.start();
	}

	@After
	public void stop()
	{
		server.stop(0);
	}

	@Test
	public void everyClientOfTheRealApiIsRerouted() throws Exception
	{
		BingoApiClient api = new BingoApiClient(new Gson(), new OkHttpClient());
		SiteBridge bridge = new SiteBridge();
		bridge.setSite("http://127.0.0.1:" + server.getAddress().getPort());
		assertTrue("installs on the current BingoApiClient", bridge.install(api));
		bridge.scenarioStarted("boss-pet");

		List<OkHttpClient> clients = new ArrayList<>();
		for (Field f : BingoApiClient.class.getDeclaredFields())
		{
			if (f.getType() == OkHttpClient.class)
			{
				f.setAccessible(true);
				clients.add((OkHttpClient) f.get(api));
			}
		}
		assertFalse("BingoApiClient holds clients", clients.isEmpty());

		for (OkHttpClient c : clients)
		{
			try (Response r = c.newCall(new Request.Builder().url("https://anvilosrs.com/api/plugin/config").build()).execute())
			{
				assertEquals(200, r.code());
			}
		}
		assertEquals("each client reached the override site, not anvilosrs.com", clients.size(), hits.size());
		for (String hit : hits)
		{
			assertEquals("/api/plugin/config boss-pet", hit);
		}
	}
}
